insert  into `communication_tbl`(`recordid`,`requestid`,`fromuserid`,`message`,`message_file`,`creationdate`,`isclosed`,`closedby`,`subuserid`,`vendorids`,`departmentid`) values (21,113,1,'With reference to EoI No. EoI/DMFT/ BALODABAZARCSF/PMU/2026 for “Setting up of Project Management Unit (PMU) for District Mineral Foundation Trust (DMFT), Baloda Bazar-Bhatapara District,” it is to inform that the Department, DMFT Baloda Bazar-Bhatapara, has scheduled the presentation and interview as per the details below: Date: 20.03.2026 Time: 11:00 AM Mode: Offline Venue: Office of Collector & District Magistrate, District Composite Building, Collectorate, Panchsheel Nagar, Balodabazar-Bhatapara (C.G.) - 493332 The firm is requested to attend the presentation and interview as per the above schedule.',NULL,'2026-03-19 10:38:02',1,0,NULL,'8',NULL);
