insert  into `eoi_request`(`requestid`,`projectid`,`userid`,`eoinumber`,`isgenerated`,`projecttitle`,`projectduration`,`projectobjective`,`categoryid`,`createdby`,`creationdate`,`isapproved`,`approvedby`,`approvedon`,`approvalremark`,`totalbudget`,`totaladmincharge`,`totalamount`,`operatingmargin`,`tax`,`admincharge`,`aboutproject`,`page_indexing`,`chips_objective`,`scopeofwork`,`anyother`,`termsandcondition`,`evaluation_index`,`evaluationprocess`,`criticalinformation`,`documentrequired`,`replywithremark`,`acceptanceotp`,`acceptancedatetime`,`eoistatus`,`sentby`,`senton`,`confirmedby`,`confirmedon`,`authletter`,`eoifloatdate`,`floatedby`,`presentationfile1`,`isfileuploaded1`,`iscommittee`,`floatdate`,`expirydate`,`issuername`,`engagementname`,`releasedate`,`prebidlastdate`,`deadlinedate`,`interviewdate`,`interview_place`,`selection_method`,`communicationaddress`,`eoiexpirydate`,`isinprebid`,`isordered`,`isupdated`,`authorizationletter`,`draftedeoi`,`isUpdateRequired`,`tier_choice`,`isInterviewSet`,`project_type`,`vendorids`,`iscancelled`,`approvalStatus`,`approvalClosed`,`approvalOtp`,`eoi_file`,`isExtended`,`isSecondCall`,`hasOldPreBid`,`oldRequestId`,`notesheet_file`,`isInterviewDone`,`isMomReceived`,`isDemandNoteRaised`,`isPaymentReceoved`,`isOrderFileReceived`,`corrigendum_file`,`corrigendum_date`,`corrigendum_remark`,`isClosed`,`closedOn`,`closure_file`,`eoi_resource_value`,`eoi_admincharge`,`eoi_operatingcost`,`eoi_tax`,`eoi_total_value`,`isCalculated`,`allowResourceAdd`,`addition_resource_letter`,`upload_time`) values (113,0,83,'EoI/DMFT/BALODABAZAR/CSF/PMU/2026',1,'Setting up of Project Management Unit (PMU) for District Mineral Foundation Trust (DMFT), Baloda Bazar- Bhatapara District','6','<p><span style=\"font-size: 11.0pt; font-family: \'Times New Roman\',\'serif\'; mso-fareast-font-family: \'Times New Roman\'; letter-spacing: -.1pt; mso-ansi-language: EN-US; mso-fareast-language: EN-US; mso-bidi-language: AR-SA;\">The District Mineral Foundation Trust (DMFT), Baloda Bazar- Bhatapara district, aims to ensure effective planning, implementation, monitoring, and governance of DMF-funded development initiatives. To strengthen institutional capacity and ensure professional management, the District Administration proposes to establish a Project Management Unit (PMU) through a consulting agency empanelled with CHiPS (Chhattisgarh Infotech Promotion Society).</span></p>',2,83,'2026-02-03 16:24:06',0,0,NULL,NULL,0,0,0,0,18,5,NULL,'<p>1. Factsheet&nbsp;<br>2. Introduction&nbsp;<br>3. Scope of Work&nbsp;<br>4. Team Composition&nbsp;<br>5. Duration of the Assignment&nbsp;<br>6. Payment Terms&nbsp;<br>7. Critical Information and Last Date for Response&nbsp;<br>8. Evaluation Process&nbsp;<br>9. Documents Required as response to this EoI&nbsp;</p>',NULL,'<p class=\"MsoNormal\" style=\"mso-para-margin-top: 3.0pt; mso-para-margin-right: 40.5pt; mso-para-margin-bottom: .6gd; mso-para-margin-left: 31.5pt; text-align: justify; line-height: 115%; margin: 3.0pt 40.5pt .1in 31.5pt;\">The PMU shall perform the following functions:</p>\r\n<p class=\"MsoListParagraph\" style=\"mso-para-margin-top: 0in; mso-para-margin-right: 40.5pt; mso-para-margin-bottom: .6gd; mso-para-margin-left: 67.5pt; text-align: justify; line-height: 115%; mso-list: l4 level1 lfo1; margin: 0in 40.5pt .1in 67.5pt;\"><!-- [if !supportLists]--><strong style=\"mso-bidi-font-weight: normal;\"><span style=\"mso-list: Ignore;\">1.<span style=\"font: 7.0pt \'Times New Roman\';\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></span></strong><!--[endif]--><strong style=\"mso-bidi-font-weight: normal;\">Governance &amp; Program Management</strong></p>\r\n<p class=\"MsoListParagraph\" style=\"mso-para-margin-top: 0in; mso-para-margin-right: 40.5pt; mso-para-margin-bottom: .6gd; mso-para-margin-left: 103.5pt; text-align: justify; mso-list: l2 level1 lfo2; margin: 0in 40.5pt .1in 103.5pt;\"><!-- [if !supportLists]--><span style=\"font-family: Symbol; mso-fareast-font-family: Symbol; mso-bidi-font-family: Symbol;\"><span style=\"mso-list: Ignore;\">&middot;<span style=\"font: 7.0pt \'Times New Roman\';\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></span></span><!--[endif]-->Support preparation of annual and perspective DMF plans.</p>\r\n<p class=\"MsoListParagraph\" style=\"mso-para-margin-top: 0in; mso-para-margin-right: 40.5pt; mso-para-margin-bottom: .6gd; mso-para-margin-left: 103.5pt; text-align: justify; mso-list: l2 level1 lfo2; margin: 0in 40.5pt .1in 103.5pt;\"><!-- [if !supportLists]--><span style=\"font-family: Symbol; mso-fareast-font-family: Symbol; mso-bidi-font-family: Symbol;\"><span style=\"mso-list: Ignore;\">&middot;<span style=\"font: 7.0pt \'Times New Roman\';\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></span></span><!--[endif]-->Assist in project conceptualization, appraisal, and prioritization.</p>\r\n<p class=\"MsoListParagraph\" style=\"mso-para-margin-top: 0in; mso-para-margin-right: 40.5pt; mso-para-margin-bottom: .6gd; mso-para-margin-left: 103.5pt; text-align: justify; mso-list: l2 level1 lfo2; margin: 0in 40.5pt .1in 103.5pt;\"><!-- [if !supportLists]--><span style=\"font-family: Symbol; mso-fareast-font-family: Symbol; mso-bidi-font-family: Symbol;\"><span style=\"mso-list: Ignore;\">&middot;<span style=\"font: 7.0pt \'Times New Roman\';\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></span></span><!--[endif]-->Facilitate convergence with State and Central Government Schemes.</p>\r\n<p class=\"MsoListParagraph\" style=\"mso-para-margin-top: 0in; mso-para-margin-right: 40.5pt; mso-para-margin-bottom: .6gd; mso-para-margin-left: 103.5pt; text-align: justify; mso-list: l2 level1 lfo2; margin: 0in 40.5pt .1in 103.5pt;\"><!-- [if !supportLists]--><span style=\"font-family: Symbol; mso-fareast-font-family: Symbol; mso-bidi-font-family: Symbol;\"><span style=\"mso-list: Ignore;\">&middot;<span style=\"font: 7.0pt \'Times New Roman\';\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></span></span><!--[endif]-->Provide secretarial and technical support to DMF Governing Council and Executive Committee meetings.</p>\r\n<p class=\"MsoListParagraph\" style=\"mso-para-margin-top: 0in; mso-para-margin-right: 40.5pt; mso-para-margin-bottom: .6gd; mso-para-margin-left: 103.5pt; text-align: justify; mso-list: l2 level1 lfo2; margin: 0in 40.5pt .1in 103.5pt;\"><!-- [if !supportLists]--><span style=\"font-family: Symbol; mso-fareast-font-family: Symbol; mso-bidi-font-family: Symbol;\"><span style=\"mso-list: Ignore;\">&middot;<span style=\"font: 7.0pt \'Times New Roman\';\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></span></span><!--[endif]-->Support inter-departmental coordination and decision-making.</p>\r\n<p class=\"MsoListParagraph\" style=\"mso-para-margin-top: 3.0pt; mso-para-margin-right: 40.5pt; mso-para-margin-bottom: .6gd; mso-para-margin-left: 67.5pt; text-align: justify; line-height: 115%; mso-list: l4 level1 lfo1; margin: 3.0pt 40.5pt .1in 67.5pt;\"><!-- [if !supportLists]--><strong style=\"mso-bidi-font-weight: normal;\"><span style=\"mso-list: Ignore;\">2.<span style=\"font: 7.0pt \'Times New Roman\';\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></span></strong><!--[endif]--><strong style=\"mso-bidi-font-weight: normal;\">Financial &amp; Legal Support</strong></p>\r\n<p class=\"MsoListParagraph\" style=\"mso-para-margin-top: 0in; mso-para-margin-right: 40.5pt; mso-para-margin-bottom: .6gd; mso-para-margin-left: 103.5pt; text-align: justify; mso-list: l1 level1 lfo3; margin: 0in 40.5pt .1in 103.5pt;\"><!-- [if !supportLists]--><span style=\"font-family: Symbol; mso-fareast-font-family: Symbol; mso-bidi-font-family: Symbol;\"><span style=\"mso-list: Ignore;\">&middot;<span style=\"font: 7.0pt \'Times New Roman\';\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></span></span><!--[endif]-->Ensure compliance with DMF financial rules, accounting norms, and audit requirements.</p>\r\n<p class=\"MsoListParagraph\" style=\"mso-para-margin-top: 0in; mso-para-margin-right: 40.5pt; mso-para-margin-bottom: .6gd; mso-para-margin-left: 103.5pt; text-align: justify; mso-list: l1 level1 lfo3; margin: 0in 40.5pt .1in 103.5pt;\"><!-- [if !supportLists]--><span style=\"font-family: Symbol; mso-fareast-font-family: Symbol; mso-bidi-font-family: Symbol;\"><span style=\"mso-list: Ignore;\">&middot;<span style=\"font: 7.0pt \'Times New Roman\';\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></span></span><!--[endif]-->Support budgeting, fund flow management, utilization certificates, and financial reporting.</p>\r\n<p class=\"MsoListParagraph\" style=\"mso-para-margin-top: 0in; mso-para-margin-right: 40.5pt; mso-para-margin-bottom: .6gd; mso-para-margin-left: 103.5pt; text-align: justify; mso-list: l1 level1 lfo3; margin: 0in 40.5pt .1in 103.5pt;\"><!-- [if !supportLists]--><span style=\"font-family: Symbol; mso-fareast-font-family: Symbol; mso-bidi-font-family: Symbol;\"><span style=\"mso-list: Ignore;\">&middot;<span style=\"font: 7.0pt \'Times New Roman\';\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></span></span><!--[endif]-->Assist in preparation and vetting of contracts, MoUs, and agreements.</p>\r\n<p class=\"MsoListParagraph\" style=\"mso-para-margin-top: 0in; mso-para-margin-right: 40.5pt; mso-para-margin-bottom: .6gd; mso-para-margin-left: 103.5pt; text-align: justify; mso-list: l1 level1 lfo3; margin: 0in 40.5pt .1in 103.5pt;\"><!-- [if !supportLists]--><span style=\"font-family: Symbol; mso-fareast-font-family: Symbol; mso-bidi-font-family: Symbol;\"><span style=\"mso-list: Ignore;\">&middot;<span style=\"font: 7.0pt \'Times New Roman\';\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></span></span><!--[endif]-->Coordinate statutory audits and address audit observations.</p>\r\n<p class=\"MsoListParagraph\" style=\"mso-para-margin-top: 3.0pt; mso-para-margin-right: 40.5pt; mso-para-margin-bottom: .6gd; mso-para-margin-left: 67.5pt; text-align: justify; line-height: 115%; mso-list: l4 level1 lfo1; margin: 3.0pt 40.5pt .1in 67.5pt;\"><!-- [if !supportLists]--><strong style=\"mso-bidi-font-weight: normal;\"><span style=\"mso-list: Ignore;\">3.<span style=\"font: 7.0pt \'Times New Roman\';\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></span></strong><!--[endif]--><strong style=\"mso-bidi-font-weight: normal;\">Social &amp;Sectoral Support</strong></p>\r\n<p class=\"MsoListParagraph\" style=\"mso-para-margin-top: 3.0pt; mso-para-margin-right: 40.5pt; mso-para-margin-bottom: .6gd; mso-para-margin-left: 103.5pt; text-align: justify; mso-list: l3 level1 lfo4; margin: 3.0pt 40.5pt .1in 103.5pt;\"><!-- [if !supportLists]--><span style=\"font-family: Symbol; mso-fareast-font-family: Symbol; mso-bidi-font-family: Symbol;\"><span style=\"mso-list: Ignore;\">&middot;<span style=\"font: 7.0pt \'Times New Roman\';\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></span></span><!--[endif]-->Support planning and monitoring of projects in health, education, nutrition, livelihood, skill development, infrastructure, and other priority sectors.</p>\r\n<p class=\"MsoListParagraph\" style=\"mso-para-margin-top: 3.0pt; mso-para-margin-right: 40.5pt; mso-para-margin-bottom: .6gd; mso-para-margin-left: 103.5pt; text-align: justify; mso-list: l3 level1 lfo4; margin: 3.0pt 40.5pt .1in 103.5pt;\"><!-- [if !supportLists]--><span style=\"font-family: Symbol; mso-fareast-font-family: Symbol; mso-bidi-font-family: Symbol;\"><span style=\"mso-list: Ignore;\">&middot;<span style=\"font: 7.0pt \'Times New Roman\';\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></span></span><!--[endif]-->Facilitate community engagement, stakeholder consultations, and beneficiary outreach.</p>\r\n<p class=\"MsoListParagraph\" style=\"mso-para-margin-top: 3.0pt; mso-para-margin-right: 40.5pt; mso-para-margin-bottom: .6gd; mso-para-margin-left: 103.5pt; text-align: justify; mso-list: l3 level1 lfo4; margin: 3.0pt 40.5pt .1in 103.5pt;\"><!-- [if !supportLists]--><span style=\"font-family: Symbol; mso-fareast-font-family: Symbol; mso-bidi-font-family: Symbol;\"><span style=\"mso-list: Ignore;\">&middot;<span style=\"font: 7.0pt \'Times New Roman\';\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></span></span><!--[endif]-->Support social audits, impact assessments, and documentation of best practices.</p>\r\n<p class=\"MsoListParagraph\" style=\"mso-para-margin-top: 3.0pt; mso-para-margin-right: 40.5pt; mso-para-margin-bottom: .6gd; mso-para-margin-left: 67.5pt; text-align: justify; line-height: 115%; mso-list: l4 level1 lfo1; margin: 3.0pt 40.5pt .1in 67.5pt;\"><!-- [if !supportLists]--><strong style=\"mso-bidi-font-weight: normal;\"><span style=\"mso-list: Ignore;\">4.<span style=\"font: 7.0pt \'Times New Roman\';\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></span></strong><!--[endif]--><strong style=\"mso-bidi-font-weight: normal;\">Monitoring, Evaluation &amp; Reporting</strong></p>\r\n<p class=\"MsoListParagraph\" style=\"mso-para-margin-top: 3.0pt; mso-para-margin-right: 40.5pt; mso-para-margin-bottom: .6gd; mso-para-margin-left: 103.5pt; text-align: justify; mso-list: l0 level1 lfo5; margin: 3.0pt 40.5pt .1in 103.5pt;\"><!-- [if !supportLists]--><span style=\"font-family: Symbol; mso-fareast-font-family: Symbol; mso-bidi-font-family: Symbol;\"><span style=\"mso-list: Ignore;\">&middot;<span style=\"font: 7.0pt \'Times New Roman\';\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></span></span><!--[endif]-->Develop MIS and reporting formats for DMF projects.</p>\r\n<p class=\"MsoListParagraph\" style=\"mso-para-margin-top: 3.0pt; mso-para-margin-right: 40.5pt; mso-para-margin-bottom: .6gd; mso-para-margin-left: 103.5pt; text-align: justify; mso-list: l0 level1 lfo5; margin: 3.0pt 40.5pt .1in 103.5pt;\"><!-- [if !supportLists]--><span style=\"font-family: Symbol; mso-fareast-font-family: Symbol; mso-bidi-font-family: Symbol;\"><span style=\"mso-list: Ignore;\">&middot;<span style=\"font: 7.0pt \'Times New Roman\';\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></span></span><!--[endif]-->Conduct regular field monitoring and progress reviews.</p>\r\n<p class=\"MsoListParagraph\" style=\"mso-para-margin-top: 3.0pt; mso-para-margin-right: 40.5pt; mso-para-margin-bottom: .6gd; mso-para-margin-left: 103.5pt; text-align: justify; mso-list: l0 level1 lfo5; margin: 3.0pt 40.5pt .1in 103.5pt;\"><!-- [if !supportLists]--><span style=\"font-family: Symbol; mso-fareast-font-family: Symbol; mso-bidi-font-family: Symbol;\"><span style=\"mso-list: Ignore;\">&middot;<span style=\"font: 7.0pt \'Times New Roman\';\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></span></span><!--[endif]-->Prepare monthly, quarterly, and annual progress reports.</p>\r\n<p><span style=\"font-size: 11.0pt; font-family: \'Times New Roman\',\'serif\'; mso-fareast-font-family: \'Times New Roman\'; mso-ansi-language: EN-US; mso-fareast-language: EN-US; mso-bidi-language: AR-SA;\">Support third-party evaluations as required.</span></p>\r\n<p><span style=\"font-size: 11.0pt; font-family: \'Times New Roman\',\'serif\'; mso-fareast-font-family: \'Times New Roman\'; mso-ansi-language: EN-US; mso-fareast-language: EN-US; mso-bidi-language: AR-SA;\"><strong style=\"mso-bidi-font-weight: normal;\"><span style=\"font-size: 10.0pt; mso-bidi-font-size: 11.0pt; font-family: \'Times New Roman\',\'serif\'; mso-fareast-font-family: \'Times New Roman\'; color: black; mso-ansi-language: EN-US; mso-fareast-language: EN-US; mso-bidi-language: AR-SA;\">Consultant- Governance Sector</span></strong>&nbsp;</span></p>\r\n<p class=\"MsoBodyText\" style=\"text-align: justify; text-indent: -14.2pt; line-height: 115%; mso-list: l0 level1 lfo1; margin: 2.4pt 0in .0001pt 22.95pt;\"><!-- [if !supportLists]--><span style=\"font-size: 10.0pt; mso-bidi-font-size: 11.0pt; line-height: 115%;\"><span style=\"mso-list: Ignore;\">&bull;<span style=\"font: 7.0pt \'Times New Roman\';\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></span></span><!--[endif]--><span style=\"font-size: 10.0pt; mso-bidi-font-size: 11.0pt; line-height: 115%;\">Overall leadership and coordination of the PMU.</span></p>\r\n<p class=\"MsoBodyText\" style=\"text-align: justify; text-indent: -14.2pt; line-height: 115%; mso-list: l0 level1 lfo1; margin: 2.4pt 0in .0001pt 22.95pt;\"><!-- [if !supportLists]--><span style=\"font-size: 10.0pt; mso-bidi-font-size: 11.0pt; line-height: 115%;\"><span style=\"mso-list: Ignore;\">&bull;<span style=\"font: 7.0pt \'Times New Roman\';\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></span></span><!--[endif]--><span style=\"font-size: 10.0pt; mso-bidi-font-size: 11.0pt; line-height: 115%;\">Liaison with District Administration and line department.</span></p>\r\n<p class=\"MsoBodyText\" style=\"text-align: justify; text-indent: -14.2pt; line-height: 115%; mso-list: l0 level1 lfo1; margin: 2.4pt 0in .0001pt 22.95pt;\"><!-- [if !supportLists]--><span style=\"font-size: 10.0pt; mso-bidi-font-size: 11.0pt; line-height: 115%;\"><span style=\"mso-list: Ignore;\">&bull;<span style=\"font: 7.0pt \'Times New Roman\';\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></span></span><!--[endif]--><span style=\"font-size: 10.0pt; mso-bidi-font-size: 11.0pt; line-height: 115%;\">Strategic Planning, advisory support, and quality assurance of deliverables.</span></p>\r\n<p class=\"MsoBodyText\" style=\"text-align: justify; text-indent: -14.2pt; line-height: 115%; mso-list: l0 level1 lfo1; margin: 2.4pt 0in .0001pt 22.95pt;\"><span style=\"font-size: 11.0pt; font-family: \'Times New Roman\',\'serif\'; mso-fareast-font-family: \'Times New Roman\'; mso-ansi-language: EN-US; mso-fareast-language: EN-US; mso-bidi-language: AR-SA;\"><span style=\"font-size: 10.0pt; mso-bidi-font-size: 11.0pt; font-family: \'Times New Roman\',\'serif\'; mso-fareast-font-family: \'Times New Roman\'; mso-ansi-language: EN-US; mso-fareast-language: EN-US; mso-bidi-language: AR-SA;\"><span style=\"font-size: 10.0pt; mso-bidi-