insert  into `eoi_request_detail`(`recordid`,`requestid`,`tierid`,`sectorid`,`positionid`,`role`,`experience`,`rateid`,`remunerationid`,`qualification`,`experiencelevel`,`temp_experiencelevel`,`temp_name`,`duration`,`employmenttype`,`budget`,`total`,`creationdate`,`resumes`,`name`,`mobilenumber`,`remark`,`isordered`,`remuneration`,`operating`,`operatingvalue`,`tax`,`taxvalue`,`admin`,`admincharge`,`grandtotal`,`isAdditional`,`change_refrence`) values (3635,131,1,3,1,'','(10+ years)',2,47,'<p class=\"p1\"><strong>Educational Qualification</strong></p>\r\n<ul class=\"ul1\">\r\n<li class=\"li1\">Any Graduation And Master&rsquo;s in Public Policy/ Public Administration / Management / IT / Data / Economics (or equivalent)</li>\r\n</ul>\r\n<p class=\"p2\"><strong>Preferred Experience </strong></p>\r\n<ul class=\"ul1\">\r\n<li class=\"li1\">Minimum 5 years of relevant experience in managing Reforms/ Policy Advisory projects/government performance management systems, largescale institutional reform initiatives, KPIdriven governance mechanisms, and digital governance Projects.</li>\r\n</ul>\r\n<p class=\"p1\"><strong>Work Profile</strong></p>\r\n<ul class=\"ul1\">\r\n<li class=\"li1\">Lead implementation of AMP PhaseII under DoGGC.</li>\r\n<li class=\"li1\">Coordinate all Departments, Districts and CHiPS for data governance, KPI updates and system operations.</li>\r\n<li class=\"li1\">Manage PMU workflows, timelines, compliance and risk mitigation.</li>\r\n<li class=\"li1\">Provide oversight on performance monitoring, exception handling, and reviewreadiness.</li>\r\n<li class=\"li1\">Ensure adherence to State guidelines and governance protocols.</li>\r\n<li class=\"li1\">Undertake handholding support to the user departments about AMP and conduct capacity building program</li>\r\n</ul>',0,0,NULL,'12','FULL TIME',5664000,0,'2026-03-13 17:37:56',NULL,NULL,NULL,'<p class=\"p1\">Team Lead</p>',1,400000,0,0,18,864000,5,283200,5947200,0,NULL);
