insert  into `eoi_request_detail`(`recordid`,`requestid`,`tierid`,`sectorid`,`positionid`,`role`,`experience`,`rateid`,`remunerationid`,`qualification`,`experiencelevel`,`temp_experiencelevel`,`temp_name`,`duration`,`employmenttype`,`budget`,`total`,`creationdate`,`resumes`,`name`,`mobilenumber`,`remark`,`isordered`,`remuneration`,`operating`,`operatingvalue`,`tax`,`taxvalue`,`admin`,`admincharge`,`grandtotal`,`isAdditional`,`change_refrence`) values (3647,134,2,2,5,'','(1-3 years)',2,76,'<ul>\r\n<li class=\"p1\">Company Secretary</li>\r\n<li class=\"p1\">2+ years of experience</li>\r\n<li class=\"p1\">Strong understanding of all legalities and governance systems, board charters, delegation matrices, and ethical codes of conduct</li>\r\n</ul>',0,0,NULL,'12','FULL TIME',2146981.68,0,'2026-03-18 12:27:29',NULL,NULL,NULL,'<p class=\"p1\"><strong>Company Secretary<br></strong></p>\r\n<p class=\"p1\">Ensure statutory&nbsp;compliance, audit&nbsp;readiness, contract vetting,&nbsp;legal defensibility, and&nbsp;validation of all&nbsp;procurement, financial,&nbsp;and program documents in&nbsp;alignment with Companies&nbsp;Act, GFR, and state&nbsp;norms.</p>',1,151623,0,0,18,327505.68,5,107349.08,2254330.76,0,NULL);
insert  into `eoi_request_detail`(`recordid`,`requestid`,`tierid`,`sectorid`,`positionid`,`role`,`experience`,`rateid`,`remunerationid`,`qualification`,`experiencelevel`,`temp_experiencelevel`,`temp_name`,`duration`,`employmenttype`,`budget`,`total`,`creationdate`,`resumes`,`name`,`mobilenumber`,`remark`,`isordered`,`remuneration`,`operating`,`operatingvalue`,`tax`,`taxvalue`,`admin`,`admincharge`,`grandtotal`,`isAdditional`,`change_refrence`) values (3648,131,1,3,3,NULL,'(5+ years)',2,49,'<p class=\"p1\"><strong>Educational Qualification</strong></p>\r\n<ul class=\"ul1\">\r\n<li class=\"li2\">Any Graduation And Master&rsquo;s in Public Policy / Development Studies / Statistics / Economics / M&amp;E / Management (or equivalent).</li>\r\n</ul>\r\n<p class=\"p2\"><strong>Preferred Experience </strong></p>\r\n<ul class=\"ul1\">\r\n<li class=\"li3\">Minimum 2 years of relevant exposure to KPI frameworks, resultsbased management, monitoring/evaluation systems, or government performance analytics.</li>\r\n</ul>\r\n<p class=\"p4\"><strong>Work Profile</strong></p>\r\n<ul class=\"ul1\">\r\n<li class=\"li4\">Support KPI rationalization and performance measurement frameworks under AMP.</li>\r\n<li class=\"li4\">Track update status, exceptions and compliance across Departments &amp; Districts.</li>\r\n<li class=\"li4\">Strengthen evidencebased monitoring using drilldowns and performance analysis.</li>\r\n<li class=\"li4\">Support actiontracking arising from review meetings.</li>\r\n<li class=\"li1\">Provide M&amp;E aligned insights for governance decisionmaking.</li>\r\n</ul>',0,0,NULL,'12','FULL TIME',4531200,0,'2026-03-24 15:03:53',NULL,NULL,NULL,'<p class=\"p1\">Monitoring Specialist</p>',1,320000,0,0,18,691200,5,226560,4757760,0,NULL);
insert  into `eoi_request_detail`(`recordid`,`requestid`,`tierid`,`sectorid`,`positionid`,`role`,`experience`,`rateid`,`remunerationid`,`qualification`,`experiencelevel`,`temp_experiencelevel`,`temp_name`,`duration`,`employmenttype`,`budget`,`total`,`creationdate`,`resumes`,`name`,`mobilenumber`,`remark`,`isordered`,`remuneration`,`operating`,`operatingvalue`,`tax`,`taxvalue`,`admin`,`admincharge`,`grandtotal`,`isAdditional`,`change_refrence`) values (3649,131,1,3,4,NULL,'(3+ years)',2,50,'<p class=\"p1\"><strong>Educational Qualification</strong></p>\r\n<ul class=\"ul1\">\r\n<li class=\"li2\">Graduation in Statistics / Economics / Computer Science / IT / Data Analytics / Public Policy (or equivalent).</li>\r\n</ul>\r\n<p class=\"p2\"><strong>Preferred Experience </strong></p>\r\n<ul class=\"ul1\">\r\n<li class=\"li3\">Minimum 2 years of relevant exposure on hands on understanding of data analysis tools, dashboard development, data validation processes.</li>\r\n</ul>\r\n<p class=\"p1\"><strong>Work Profile</strong></p>\r\n<ul class=\"ul1\">\r\n<li class=\"li1\">Conduct data validation, cleaning, and preparation for AMP dashboards.</li>\r\n<li class=\"li1\">Generate analytical inputs, comparisons, exception lists and trendbased insights.</li>\r\n<li class=\"li1\">Maintain data pipelines supporting KPI updates at State level.</li>\r\n<li class=\"li1\">Support MIS&ndash;AMP data mapping and integration processes.</li>\r\n</ul>',0,0,NULL,'12','FULL TIME',3894000,0,'2026-03-24 15:14:03',NULL,NULL,NULL,'<p class=\"p1\">Data Analyst</p>',1,275000,0,0,18,594000,5,194700,4088700,0,NULL);
insert  into `eoi_request_detail`(`recordid`,`requestid`,`tierid`,`sectorid`,`positionid`,`role`,`experience`,`rateid`,`remunerationid`,`qualification`,`experiencelevel`,`temp_experiencelevel`,`temp_name`,`duration`,`employmenttype`,`budget`,`total`,`creationdate`,`resumes`,`name`,`mobilenumber`,`remark`,`isordered`,`remuneration`,`operating`,`operatingvalue`,`tax`,`taxvalue`,`admin`,`admincharge`,`grandtotal`,`isAdditional`,`change_refrence`) values (3650,131,1,3,4,NULL,'(3+ years)',2,50,'<p class=\"p1\"><strong>Educational Qualification</strong></p>\r\n<ul class=\"ul1\">\r\n<li class=\"li2\">Graduation in Statistics / Economics / Computer Science / IT / Data Analytics / Public Policy (or equivalent).</li>\r\n</ul>\r\n<p class=\"p2\"><strong>Preferred Experience </strong></p>\r\n<ul class=\"ul1\">\r\n<li class=\"li3\">Minimum 2 years of relevant exposure on hands on understanding of data analysis tools, dashboard development, data validation processes.</li>\r\n</ul>\r\n<p class=\"p1\"><strong>Work Profile</strong></p>\r\n<ul class=\"ul1\">\r\n<li class=\"li1\">Conduct data validation, cleaning, and preparation for AMP dashboards.</li>\r\n<li class=\"li1\">Generate analytical inputs, comparisons, exception lists and trendbased insights.</li>\r\n<li class=\"li1\">Maintain data pipelines supporting KPI updates at State level.</li>\r\n<li class=\"li1\">Support MIS&ndash;AMP data mapping and integration processes.</li>\r\n</ul>',0,0,NULL,'12','FULL TIME',3894000,0,'2026-03-24 15:14:03',NULL,NULL,NULL,'<p class=\"p1\">Data Analyst</p>',1,275000,0,0,18,594000,5,194700,4088700,0,NULL);
insert  into `eoi_request_detail`(`recordid`,`requestid`,`tierid`,`sectorid`,`positionid`,`role`,`experience`,`rateid`,`remunerationid`,`qualification`,`experiencelevel`,`temp_experiencelevel`,`temp_name`,`duration`,`employmenttype`,`budget`,`total`,`creationdate`,`resumes`,`name`,`mobilenumber`,`remark`,`isordered`,`remuneration`,`operating`,`operatingvalue`,`tax`,`taxvalue`,`admin`,`admincharge`,`grandtotal`,`isAdditional`,`change_refrence`) values (3651,135,2,0,0,'Project Associate','5+ Years',1,19,'<p class=\"p1\">BE / B.Tech / BCA / MCA or Similar) with a minimum 60% marks</p>\r\n<p class=\"p1\"><strong>Total Experience - 6+ years</strong><br><br><strong>Relevant Experience</strong></p>\r\n<ul class=\"ul1\">\r\n<li class=\"li2\">Minimum 3&ndash;5 years of experience in managing IT/e-Governance projects, preferably within Government departments, PSUs, or State Data Center / SWAN environments.</li>\r\n<li class=\"li2\">Managing technical reports, approvals, Minutes of Meetings, audit records, and official correspondence.</li>\r\n<li class=\"li3\">Supporting audit processes and compliance documentation.</li>\r\n<li class=\"li3\">Experience in coordinating with multiple stakeholders</li>\r\n<li class=\"li3\">SLA monitoring and performance tracking.</li>\r\n<li class=\"li3\">Milestone tracking and deliverable verification.</li>\r\n<li class=\"li3\">Experience in providing day-to-day operational support to departments.</li>\r\n<li class=\"li3\">Strong coordination skills for cross-functional stakeholder engagement.</li>\r\n<li class=\"li4\">Experience in issue tracking systems and reporting dashboards.</li>\r\n</ul>',1,1,'Bhoopendra Kumar Sahu','12','FULL TIME',504662.4,0,'2026-04-02 22:00:25',NULL,NULL,NULL,NULL,1,32400,10,38880,18,76982.4,0,0,504662.4,0,NULL);
insert  into `eoi_request_detail`(`recordid`,`requestid`,`tierid`,`sectorid`,`positionid`,`role`,`experience`,`rateid`,`remunerationid`,`qualification`,`experiencelevel`,`temp_experiencelevel`,`temp_name`,`duration`,`employmenttype`,`budget`,`total`,`creationdate`,`resumes`,`name`,`mobilenumber`,`remark`,`isordered`,`remuneration`,`operating`,`operatingvalue`,`tax`,`taxvalue`,`admin`,`admincharge`,`grandtotal`,`isAdditional`,`change_refrence`) values (3652,136,1,6,1,'','(10+ years)',2,62,'<ul>\r\n<li>Plan and coordinate the overall study framework, design and methodology, including setting objectives, milestones, and performance metrics, ensuring alignment with study objectives and compliance with quality standards.</li>\r\n<li>Supervise and support the Senior Consultants and Field Supervisors, providing guidance, direction, and resources to ensure effective team performance.</li>\r\n<li>Foster a collaborative and productive work environment, addressing any team dynamics or operational issues.</li>\r\n<li>Monitor study progress, including timelines, budgets, and deliverables, and make adjustments as needed to keep the study on track.</li>\r\n<li>Engage with key stakeholders, including senior management and department officials, to gather input, provide updates, and address concerns.</li>\r\n<li>Implement and monitor quality control measures to maintain the accuracy and reliability of data and findings.</li>\r\n<li>Review and deliver comprehensive reports and presentations to senior management and stakeholders, highlighting key findings, insights, and recommendations.</li>\r\n</ul>\r\n<p>&nbsp;</p>',0,0,NULL,'12','FULL TIME',5664000,0,'2026-04-03 10:40:04',NULL,NULL,NULL,'<p>Project Manager</p>\r\n<p>&nbsp;</p>',1,400000,0,0,18,864000,5,283200,5947200,0,NULL);
insert  into `eoi_request_detail`(`recordid`,`requestid`,`tierid`,`sectorid`,`positionid`,`role`,`experience`,`rateid`,`remunerationid`,`qualification`,`experiencelevel`,`temp_experiencelevel`,`temp_name`,`duration`,`employmenttype`,`budget`,`total`,`creationdate`,`resumes`,`name`,`mobilenumber`,`remark`,`isordered`,`remuneration`,`operating`,`operatingvalue`,`tax`,`taxvalue`,`admin`,`admincharge`,`grandtotal`,`isAdditional`,`change_refrence`) values (3653,136,1,6,3,'','(5+ years)',2,64,'<ul>\r\n<li>Conduct desk review of project documentation, gather secondary data, review applicable statutory provisions, and identify any gaps in existing information sources.</li>\r\n<li>Undertake preliminary visit to the project area to carry out preparatory activities.</li>\r\n<li>Design survey instruments, train investigators and pilot test the questionnaires.</li>\r\n<li>Oversee the implementation of the study, ensuring that all activities are conducted according to the study plan.</li>\r\n<li>Provide training and support to the Field Supervisor and their team on study protocols and data collection methods.</li>\r\n<li>Manage and support the Field Supervisor and their team, providing guidance, resources, and troubleshooting as needed.</li>\r\n<li>Monitor progress and performance to ensure adherence to timelines, budgets, and quality standards.</li>\r\n<li>Implement quality control measures to ensure the validity and reliability of the study results.</li>\r\n<li>Review and verify data collection processes and outcomes, addressing any discrepancies or issues.</li>\r\n<li>Maintain a comprehensive record of study activities, data, and communications.</li>\r\n<li>Participate in stakeholder consultations along with the survey team.</li>\r\n<li>Compile, clean, and analyze the quantitative and qualitative data collected during the study, utilizing appropriate analytical tools and techniques.</li>\r\n<li>Synthesize findings, highlighting key insights and implications for stakeholders.</li>\r\n<li>Prepare detailed reports and presentations on the findings and recommendations for action.</li>\r\n</ul>',0,0,NULL,'12','FULL TIME',4531200,0,'2026-04-03 10:41:32',NULL,NULL,NULL,'',1,320000,0,0,18,691200,5,226560,4757760,0,NULL);
insert  into `eoi_request_detail`(`recordid`,`requestid`,`tierid`,`sectorid`,`positionid`,`role`,`experience`,`rateid`,`remunerationid`,`qualification`,`experiencelevel`,`temp_experiencelevel`,`temp_name`,`duration`,`employmenttype`,`budget`,`total`,`creationdate`,`resumes`,`name`,`mobilenumber`,`remark`,`isordered`,`remuneration`,`operating`,`operatingvalue`,`tax`,`taxvalue`,`admin`,`admincharge`,`grandtotal`,`isAdditional`,`change_refrence`) values (3654,136,1,6,3,'','(5+ years)',2,64,'<ul>\r\n<li>Conduct desk review of project documentation, gather secondary data, review applicable statutory provisions, and identify any gaps in existing information sources.</li>\r\n<li>Undertake preliminary visit to the project area to carry out preparatory activities.</li>\r\n<li>Design survey instruments, train investigators and pilot test the questionnaires.</li>\r\n<li>Oversee the implementation of the study, ensuring that all activities are conducted according to the study plan.</li>\r\n<li>Provide training and support to the Field Supervisor and their team on study protocols and data collection methods.</li>\r\n<li>Manage and support the Field Supervisor and their team, providing guidance, resources, and troubleshooting as needed.</li>\r\n<li>Monitor progress and performance to ensure adherence to timelines, budgets, and quality standards.</li>\r\n<li>Implement quality control measures to ensure the validity and reliability of the study results.</li>\r\n<li>Review and verify data collection processes and outcomes, addressing any discrepancies or issues.</li>\r\n<li>Maintain a comprehensive record of study activities, data, and communications.</li>\r\n<li>Participate in stakeholder consultations along with the survey team.</li>\r\n<li>Compile, clean, and analyze the quantitative and qualitative data collected during the study, utilizing appropriate analytical tools and techniques.</li>\r\n<li>Synthesize findings, highlighting key insights and implications for stakeholders.</li>\r\n<li>Prepare detailed reports and presentations on the findings and recommendations for action.</li>\r\n</ul>',0,0,NULL,'12','FULL TIME',4531200,0,'2026-04-03 10:41:32',NULL,NULL,NULL,'',1,320000,0,0,18,691200,5,226560,4757760,0,NULL);
insert  into `eoi_request_detail`(`recordid`,`requestid`,`tierid`,`sectorid`,`positionid`,`role`,`experience`,`rateid`,`remunerationid`,`qualification`,`experiencelevel`,`temp_experiencelevel`,`temp_name`,`duration`,`employmenttype`,`budget`,`total`,`creationdate`,`resumes`,`name`,`mobilenumber`,`remark`,`isordered`,`remuneration`,`operating`,`operatingvalue`,`tax`,`taxvalue`,`admin`,`admincharge`,`grandtotal`,`isAdditional`,`change_refrence`) values (3655,136,1,6,4,'','(3+ years)',2,65,'<ul>\r\n<li>Oversee and manage a team of 4 Field Surveyor each.</li>\r\n<li>Provide clear instructions and guidance to the Field Surveyors.</li>\r\n<li>Support the Field Surveyors in conducting the surveys.</li>\r\n<li>Review and verify the collected survey data for accuracy and completeness. Address discrepancies or errors in data collection promptly.</li>\r\n<li>Ensure data is properly recorded, stored, and transmitted according to project guidelines.</li>\r\n<li>Ensure adherence to timelines and protocols</li>\r\n<li>Address any issues or challenges faced by field staff and provide solutions or escalate to higher management as needed.</li>\r\n<li>Prepare and submit regular reports on survey progress, challenges, and findings to the Senior Consultants or Project Manager.</li>\r\n<li>Ensure that all field operations comply with legal, ethical, and safety standards.</li>\r\n<li>Assist in logistical arrangements for field operations, including transportation and equipment.</li>\r\n<li>Coordinate with all stakeholders, including local authorities and community representatives and facilitate necessary stakeholder consultations under the study.</li>\r\n</ul>',0,0,NULL,'12','FULL TIME',3894000,0,'2026-04-03 10:43:11',NULL,NULL,NULL,'<p>Field Supervisor</p>',1,275000,0,0,18,594000,5,194700,4088700,0,NULL);
