insert  into `eoi_request_detail`(`recordid`,`requestid`,`tierid`,`sectorid`,`positionid`,`role`,`experience`,`rateid`,`remunerationid`,`qualification`,`experiencelevel`,`temp_experiencelevel`,`temp_name`,`duration`,`employmenttype`,`budget`,`total`,`creationdate`,`resumes`,`name`,`mobilenumber`,`remark`,`isordered`,`remuneration`,`operating`,`operatingvalue`,`tax`,`taxvalue`,`admin`,`admincharge`,`grandtotal`,`isAdditional`,`change_refrence`) values (3657,136,1,6,4,'','(3+ years)',2,65,'<ul>\r\n<li>Oversee and manage a team of 4 Field Surveyor each.</li>\r\n<li>Provide clear instructions and guidance to the Field Surveyors.</li>\r\n<li>Support the Field Surveyors in conducting the surveys.</li>\r\n<li>Review and verify the collected survey data for accuracy and completeness. Address discrepancies or errors in data collection promptly.</li>\r\n<li>Ensure data is properly recorded, stored, and transmitted according to project guidelines.</li>\r\n<li>Ensure adherence to timelines and protocols</li>\r\n<li>Address any issues or challenges faced by field staff and provide solutions or escalate to higher management as needed.</li>\r\n<li>Prepare and submit regular reports on survey progress, challenges, and findings to the Senior Consultants or Project Manager.</li>\r\n<li>Ensure that all field operations comply with legal, ethical, and safety standards.</li>\r\n<li>Assist in logistical arrangements for field operations, including transportation and equipment.</li>\r\n<li>Coordinate with all stakeholders, including local authorities and community representatives and facilitate necessary stakeholder consultations under the study.</li>\r\n</ul>',0,0,NULL,'12','FULL TIME',3894000,0,'2026-04-03 10:43:11',NULL,NULL,NULL,'<p>Field Supervisor</p>',1,275000,0,0,18,594000,5,194700,4088700,0,NULL);
insert  into `eoi_request_detail`(`recordid`,`requestid`,`tierid`,`sectorid`,`positionid`,`role`,`experience`,`rateid`,`remunerationid`,`qualification`,`experiencelevel`,`temp_experiencelevel`,`temp_name`,`duration`,`employmenttype`,`budget`,`total`,`creationdate`,`resumes`,`name`,`mobilenumber`,`remark`,`isordered`,`remuneration`,`operating`,`operatingvalue`,`tax`,`taxvalue`,`admin`,`admincharge`,`grandtotal`,`isAdditional`,`change_refrence`) values (3658,136,1,6,5,'','(1-3 years)',2,66,'<ul>\r\n<li>Participate in training sessions provided by the Senior Consultants and Field Supervisor to understand survey methods and tools.</li>\r\n<li>Conduct face-to-face census survey within the project-affected area, including a comprehensive socio-economic survey of all affected families.</li>\r\n<li>Perform land survey, including the examination of land revenue maps, assessment of land records, field verification of project boundaries and coordinates, and determination of land use within the project area.</li>\r\n<li>Undertake Participatory Rural Appraisal, including resource mapping, social mapping, and transect walks to physically identify and verify families affected by the project.</li>\r\n<li>Photograph and GIS-tag structures within the affected area.</li>\r\n<li>Accurately record responses and ensure data integrity.</li>\r\n<li>Adhere to the survey schedule and visit all designated locations in a timely manner.</li>\r\n<li>Review responses for consistency and accuracy before submission.</li>\r\n<li>Report any discrepancies, incomplete data, or issues encountered during data collection to the Field Supervisor.</li>\r\n<li>Submit daily reports on the progress of data collection and any challenges encountered.</li>\r\n<li>Ensure adherence to legal, ethical, and privacy guidelines related to data collection.</li>\r\n</ul>',0,0,NULL,'12','FULL TIME',3115200,0,'2026-04-03 10:48:34',NULL,NULL,NULL,'<p>Field Surveyor</p>',1,220000,0,0,18,475200,5,155760,3270960,0,NULL);
insert  into `eoi_request_detail`(`recordid`,`requestid`,`tierid`,`sectorid`,`positionid`,`role`,`experience`,`rateid`,`remunerationid`,`qualification`,`experiencelevel`,`temp_experiencelevel`,`temp_name`,`duration`,`employmenttype`,`budget`,`total`,`creationdate`,`resumes`,`name`,`mobilenumber`,`remark`,`isordered`,`remuneration`,`operating`,`operatingvalue`,`tax`,`taxvalue`,`admin`,`admincharge`,`grandtotal`,`isAdditional`,`change_refrence`) values (3659,136,1,6,5,'','(1-3 years)',2,66,'<ul>\r\n<li>Participate in training sessions provided by the Senior Consultants and Field Supervisor to understand survey methods and tools.</li>\r\n<li>Conduct face-to-face census survey within the project-affected area, including a comprehensive socio-economic survey of all affected families.</li>\r\n<li>Perform land survey, including the examination of land revenue maps, assessment of land records, field verification of project boundaries and coordinates, and determination of land use within the project area.</li>\r\n<li>Undertake Participatory Rural Appraisal, including resource mapping, social mapping, and transect walks to physically identify and verify families affected by the project.</li>\r\n<li>Photograph and GIS-tag structures within the affected area.</li>\r\n<li>Accurately record responses and ensure data integrity.</li>\r\n<li>Adhere to the survey schedule and visit all designated locations in a timely manner.</li>\r\n<li>Review responses for consistency and accuracy before submission.</li>\r\n<li>Report any discrepancies, incomplete data, or issues encountered during data collection to the Field Supervisor.</li>\r\n<li>Submit daily reports on the progress of data collection and any challenges encountered.</li>\r\n<li>Ensure adherence to legal, ethical, and privacy guidelines related to data collection.</li>\r\n</ul>',0,0,NULL,'12','FULL TIME',3115200,0,'2026-04-03 10:48:34',NULL,NULL,NULL,'<p>Field Surveyor</p>',1,220000,0,0,18,475200,5,155760,3270960,0,NULL);
