insert  into `eoi_request_detail`(`recordid`,`requestid`,`tierid`,`sectorid`,`positionid`,`role`,`experience`,`rateid`,`remunerationid`,`qualification`,`experiencelevel`,`temp_experiencelevel`,`temp_name`,`duration`,`employmenttype`,`budget`,`total`,`creationdate`,`resumes`,`name`,`mobilenumber`,`remark`,`isordered`,`remuneration`,`operating`,`operatingvalue`,`tax`,`taxvalue`,`admin`,`admincharge`,`grandtotal`,`isAdditional`,`change_refrence`) values (3672,136,1,6,5,'','(1-3 years)',2,66,'<ul>\r\n<li>Participate in training sessions provided by the Senior Consultants and Field Supervisor to understand survey methods and tools.</li>\r\n<li>Conduct face-to-face census survey within the project-affected area, including a comprehensive socio-economic survey of all affected families.</li>\r\n<li>Perform land survey, including the examination of land revenue maps, assessment of land records, field verification of project boundaries and coordinates, and determination of land use within the project area.</li>\r\n<li>Undertake Participatory Rural Appraisal, including resource mapping, social mapping, and transect walks to physically identify and verify families affected by the project.</li>\r\n<li>Photograph and GIS-tag structures within the affected area.</li>\r\n<li>Accurately record responses and ensure data integrity.</li>\r\n<li>Adhere to the survey schedule and visit all designated locations in a timely manner.</li>\r\n<li>Review responses for consistency and accuracy before submission.</li>\r\n<li>Report any discrepancies, incomplete data, or issues encountered during data collection to the Field Supervisor.</li>\r\n<li>Submit daily reports on the progress of data collection and any challenges encountered.</li>\r\n<li>Ensure adherence to legal, ethical, and privacy guidelines related to data collection.</li>\r\n</ul>',0,0,NULL,'12','FULL TIME',3115200,0,'2026-04-03 10:48:34',NULL,NULL,NULL,'<p>Field Surveyor</p>',1,220000,0,0,18,475200,5,155760,3270960,0,NULL);
insert  into `eoi_request_detail`(`recordid`,`requestid`,`tierid`,`sectorid`,`positionid`,`role`,`experience`,`rateid`,`remunerationid`,`qualification`,`experiencelevel`,`temp_experiencelevel`,`temp_name`,`duration`,`employmenttype`,`budget`,`total`,`creationdate`,`resumes`,`name`,`mobilenumber`,`remark`,`isordered`,`remuneration`,`operating`,`operatingvalue`,`tax`,`taxvalue`,`admin`,`admincharge`,`grandtotal`,`isAdditional`,`change_refrence`) values (3673,137,1,6,2,'','(7+ years)',2,63,'<ul>\r\n<li>Responsible for overall functioning of the PMU.</li>\r\n<li>Build and maintain a high performing team in the PMU.</li>\r\n<li>Oversee the planning, monitoring and implementation of key dept, schemes across the state ensuring adherence to rules/guidelines, timelines and budget.</li>\r\n<li>Provide effective project management support to achieve the objectives of the engagement.</li>\r\n<li>Ensure the development of capacity building and training plan for the stakeholders and effective implementation.</li>\r\n<li>Design survey instruments, train investigators and pilot test the questionnaires.</li>\r\n<li>Provide training and support to the Field Supervisor and their team on study protocols and data collection methods.</li>\r\n<li>Manage and support the Field Supervisor and their team, providing guidance, resources, and troubleshooting as needed Ensure that deliverables are satisfied in a timely manner.</li>\r\n<li>Act as a formal channel of communication between the Consultant and Department.</li>\r\n<li>Any other work as may be assigned by the directorate</li>\r\n</ul>\r\n<p>&nbsp;</p>',0,0,NULL,'12','FULL TIME',5097600,0,'2026-04-06 15:14:25',NULL,NULL,NULL,'<p>Team Leader</p>\r\n<p>&nbsp;</p>',1,360000,0,0,18,777600,5,254880,5352480,0,NULL);
insert  into `eoi_request_detail`(`recordid`,`requestid`,`tierid`,`sectorid`,`positionid`,`role`,`experience`,`rateid`,`remunerationid`,`qualification`,`experiencelevel`,`temp_experiencelevel`,`temp_name`,`duration`,`employmenttype`,`budget`,`total`,`creationdate`,`resumes`,`name`,`mobilenumber`,`remark`,`isordered`,`remuneration`,`operating`,`operatingvalue`,`tax`,`taxvalue`,`admin`,`admincharge`,`grandtotal`,`isAdditional`,`change_refrence`) values (3674,137,1,6,3,'','(5+ years)',2,64,'<ul>\r\n<li>Conduct desk review of project documentation, gather secondary data, review applicable statutory provisions, and identify any gaps in existing information sources.</li>\r\n<li>Monitor progress and performance to ensure adherence to timelines, budgets, and quality standards.</li>\r\n<li>Implement quality control measures to ensure the validity and reliability of the documents / reports.</li>\r\n<li>Maintain a comprehensive record of study activities, data, reports, and communications.</li>\r\n<li>Participate in stakeholder consultations.</li>\r\n<li>Synthesize findings, highlighting key insights and implications for stakeholders.</li>\r\n<li>Prepare detailed reports and presentations on the findings and recommendations for action.</li>\r\n</ul>',0,0,NULL,'12','FULL TIME',4531200,0,'2026-04-06 15:15:18',NULL,NULL,NULL,'<p>Documentati on and Reporting Expert</p>',1,320000,0,0,18,691200,5,226560,4757760,0,NULL);
insert  into `eoi_request_detail`(`recordid`,`requestid`,`tierid`,`sectorid`,`positionid`,`role`,`experience`,`rateid`,`remunerationid`,`qualification`,`experiencelevel`,`temp_experiencelevel`,`temp_name`,`duration`,`employmenttype`,`budget`,`total`,`creationdate`,`resumes`,`name`,`mobilenumber`,`remark`,`isordered`,`remuneration`,`operating`,`operatingvalue`,`tax`,`taxvalue`,`admin`,`admincharge`,`grandtotal`,`isAdditional`,`change_refrence`) values (3675,137,1,6,4,'','(3+ years)',2,65,'<ul>\r\n<li>Coordinate the data collection by identifying sources of information and designing survey and collection methods.</li>\r\n<li>Review and verify data collection processes and outcomes, addressing any discrepancies or issues.</li>\r\n<li>Coordinate all the data collection and survey exercises for the department by coordinating with other departmental and district level officials.</li>\r\n<li>Compile, clean, and analyze the quantitative and qualitative data collected during the study and surveys utilizing appropriate analytical tools and techniques.</li>\r\n<li>Coordinate the various capacity building initiatives for various stakeholders on data analysis and visualization.</li>\r\n<li>Facilitate the different analytical reports, dashboards, visualization, and reporting tools as per the requirement of the department.</li>\r\n</ul>',0,0,NULL,'12','FULL TIME',3894000,0,'2026-04-06 15:16:13',NULL,NULL,NULL,'<p>Senior Data Analyst</p>',1,275000,0,0,18,594000,5,194700,4088700,0,NULL);
insert  into `eoi_request_detail`(`recordid`,`requestid`,`tierid`,`sectorid`,`positionid`,`role`,`experience`,`rateid`,`remunerationid`,`qualification`,`experiencelevel`,`temp_experiencelevel`,`temp_name`,`duration`,`employmenttype`,`budget`,`total`,`creationdate`,`resumes`,`name`,`mobilenumber`,`remark`,`isordered`,`remuneration`,`operating`,`operatingvalue`,`tax`,`taxvalue`,`admin`,`admincharge`,`grandtotal`,`isAdditional`,`change_refrence`) values (3676,137,1,1,4,'','(3+ years)',2,40,'<ul>\r\n<li>Responsible for the overall IT based solutions</li>\r\n<li>Support to analysed and understand detailed business requirements to provide mapping requirements and software solutions.</li>\r\n<li>Coordinate the data collection by identifying sources of information and designing survey and collection methods.</li>\r\n<li>Support in Creating, analysing, and validating detailed functional specifications.</li>\r\n<li>Facilitate design sessions with the implementation team to define the solution.</li>\r\n<li>Should have experience in Delivering elements of systems design, including data migration rules, business rules, wireframes, or other detailed deliverables</li>\r\n</ul>',0,0,NULL,'12','FULL TIME',3894000,0,'2026-04-06 15:16:54',NULL,NULL,NULL,'<p>IT Expert</p>',0,275000,0,0,18,594000,5,194700,4088700,0,NULL);
