insert  into `eoi_request_detail`(`recordid`,`requestid`,`tierid`,`sectorid`,`positionid`,`role`,`experience`,`rateid`,`remunerationid`,`qualification`,`experiencelevel`,`temp_experiencelevel`,`temp_name`,`duration`,`employmenttype`,`budget`,`total`,`creationdate`,`resumes`,`name`,`mobilenumber`,`remark`,`isordered`,`remuneration`,`operating`,`operatingvalue`,`tax`,`taxvalue`,`admin`,`admincharge`,`grandtotal`,`isAdditional`,`change_refrence`) values (3740,150,1,3,3,'','(5+ years)',2,49,'<ol>\r\n<li>Education and Certifications - a. BE/BTech any specialization b. MBA/MCA</li>\r\n<li>5+ years of procurement experience in the government and public sector domain</li>\r\n<li>5+ years of experience in working with state/central government projects</li>\r\n<li>Preferred procurement experience for IT project in the government and public sector domain</li>\r\n<li>Experience of managing 3 or more large e-governance/IT projects for the government in the capacity of team lead/ project lead/project manager</li>\r\n</ol>',0,0,NULL,'12','FULL TIME',4531200,0,'2026-05-03 14:22:03',NULL,NULL,NULL,'<p>Senior Consultant - Procurement</p>',1,320000,0,0,18,691200,5,226560,4757760,0,NULL);
insert  into `eoi_request_detail`(`recordid`,`requestid`,`tierid`,`sectorid`,`positionid`,`role`,`experience`,`rateid`,`remunerationid`,`qualification`,`experiencelevel`,`temp_experiencelevel`,`temp_name`,`duration`,`employmenttype`,`budget`,`total`,`creationdate`,`resumes`,`name`,`mobilenumber`,`remark`,`isordered`,`remuneration`,`operating`,`operatingvalue`,`tax`,`taxvalue`,`admin`,`admincharge`,`grandtotal`,`isAdditional`,`change_refrence`) values (3741,150,1,1,3,'','(5+ years)',2,39,'<ol>\r\n<li>Education and Certifications - a. BE/Btech any specialization or MCA</li>\r\n<li>5+ Years of relevant experience in IT project implementation/project management /software development</li>\r\n<li>Experience in drafting DPR, RFP for IT projects for government</li>\r\n</ol>',0,0,NULL,'12','FULL TIME',4531200,0,'2026-05-03 14:22:31',NULL,NULL,NULL,'<p>Senior Consultant - IT Sector</p>',1,320000,0,0,18,691200,5,226560,4757760,0,NULL);
insert  into `eoi_request_detail`(`recordid`,`requestid`,`tierid`,`sectorid`,`positionid`,`role`,`experience`,`rateid`,`remunerationid`,`qualification`,`experiencelevel`,`temp_experiencelevel`,`temp_name`,`duration`,`employmenttype`,`budget`,`total`,`creationdate`,`resumes`,`name`,`mobilenumber`,`remark`,`isordered`,`remuneration`,`operating`,`operatingvalue`,`tax`,`taxvalue`,`admin`,`admincharge`,`grandtotal`,`isAdditional`,`change_refrence`) values (3742,151,1,3,1,'','(10+ years)',2,47,'<p>Governance Sector</p>',0,0,NULL,'12','FULL TIME',5664000,0,'2026-05-03 14:48:06',NULL,NULL,NULL,'<p>Focus- Strategy, policy, and high-level administration</p>\r\n<ol>\r\n<li>Strategic roadmap- Develop a 3-5 year digital transformation vision for the corporation.</li>\r\n<li>Policy formulation- Draft internal policies regarding procurement, human resources, and corporate ethics.</li>\r\n<li>Institutional Strengthening- Identify gaps in organizational structure and recommend capacity-building measures.</li>\r\n<li>Regulatory compliance- Ensure all corporate actions align with the Chhattisgarh Excise Act and State Government mandates.</li>\r\n<li>Inter-Departmental Liaison- Act as the primary point of contact between CSMCL and the Department of IT/ Finance.</li>\r\n<li>Performance Audits- Conduct periodic reviews of departmental KPIs and suggest corrective actions.</li>\r\n<li>Resource Optimization- Analyze budget utilization and suggest ways to reduce operational overheads.</li>\r\n<li>Crisis Management- Develop protocols for handling administrative or legal contingencies.</li>\r\n<li>CSR Framework- design and oversee the implementation of Corporate Social Responsibility initiatives.</li>\r\n<li>Board Support- Prepare strategic briefs and presentations for Board of Directors&rsquo; meetings.</li>\r\n</ol>',1,400000,0,0,18,864000,5,283200,5947200,0,NULL);
insert  into `eoi_request_detail`(`recordid`,`requestid`,`tierid`,`sectorid`,`positionid`,`role`,`experience`,`rateid`,`remunerationid`,`qualification`,`experiencelevel`,`temp_experiencelevel`,`temp_name`,`duration`,`employmenttype`,`budget`,`total`,`creationdate`,`resumes`,`name`,`mobilenumber`,`remark`,`isordered`,`remuneration`,`operating`,`operatingvalue`,`tax`,`taxvalue`,`admin`,`admincharge`,`grandtotal`,`isAdditional`,`change_refrence`) values (3743,151,1,1,2,'','(7+ years)',2,38,'<p>IT&nbsp;</p>',0,0,NULL,'12','FULL TIME',5097600,0,'2026-05-03 14:49:28',NULL,NULL,NULL,'<p>Focus- Enterprise Architecture and Technical Leadership</p>\r\n<ol>\r\n<li>IT Infrastructure Design- Architect the server, network, and loud environment for the entire corporation.</li>\r\n<li>Tech Stack Selection- Decide on the programming languages, databases, and frameworks for new software projects.</li>\r\n<li>Security Governance- Implement high-level data encryption and cyber security frameworks (ISO 2700 standards).</li>\r\n<li>System Integration-Ensure seamless communication between inventory systems, retails POS, and financial accounting software.</li>\r\n<li>Technical Budgeting- Prepare estimates for hardware procurement and software licensing.</li>\r\n<li>Disaster Recovery- Design a robust Business Continuity Plan (BCP) and off-site data backup strategy.</li>\r\n<li>Scalability Planning- Ensure IT systems can handle peak loads during festive seasons or expansion.</li>\r\n<li>Vendor Management- Lead technical evaluations of RFPs and oversee the performance of external IT agencies.</li>\r\n<li>Standardization- Set coding and documentation standards for all internal and outsourced IT projects.</li>\r\n<li>Emerging Tech Adoption- Explore the use of Blockchain for supply cain transparency or AI for demand forecasting.</li>\r\n</ol>',1,360000,0,0,18,777600,5,254880,5352480,0,NULL);
insert  into `eoi_request_detail`(`recordid`,`requestid`,`tierid`,`sectorid`,`positionid`,`role`,`experience`,`rateid`,`remunerationid`,`qualification`,`experiencelevel`,`temp_experiencelevel`,`temp_name`,`duration`,`employmenttype`,`budget`,`total`,`creationdate`,`resumes`,`name`,`mobilenumber`,`remark`,`isordered`,`remuneration`,`operating`,`operatingvalue`,`tax`,`taxvalue`,`admin`,`admincharge`,`grandtotal`,`isAdditional`,`change_refrence`) values (3744,151,1,1,3,'','(5+ years)',2,39,'<p>IT</p>',0,0,NULL,'12','FULL TIME',4531200,0,'2026-05-03 14:50:49',NULL,NULL,NULL,'<p>Focus- Project Management and Systems Implementation</p>\r\n<ol>\r\n<li>Project Lifecycle Management- Oversee daily progress of software modules from design to UAT (User Acceptance Testing).</li>\r\n<li>Database Management- Supervise the integrity and optimization of large-scale SQL/NoSQL databases.</li>\r\n<li>Software Quality Assurance- Establish rigorous testing protocols to eliminate bugs before system deployment.</li>\r\n<li>Dashboard Development- Create real-time MIS (Management Information System) dashboards for senior management.</li>\r\n<li>Supply Chain Digitization- Implement end-to-end tracking of stock from distilleries to retail outlets.</li>\r\n<li>API Management- Manage integrations with third-party payment gateways and bank systems.</li>\r\n<li>Hardware Maintenance- Oversee the upkeep of data centres, POS machines, and biometric systems.</li>\r\n<li>Incident Response- Lead the technical team in resolving server downtimes or system crashes.</li>\r\n<li>Data Migration- Supervise the secure the secure transfer of legacy data into new digital platforms.</li>\r\n<li>SLA Monitoring- Track Service Level Agreements of IT vendors to ensure 99.9% system uptime.</li>\r\n</ol>',1,320000,0,0,18,691200,5,226560,4757760,0,NULL);
insert  into `eoi_request_detail`(`recordid`,`requestid`,`tierid`,`sectorid`,`positionid`,`role`,`experience`,`rateid`,`remunerationid`,`qualification`,`experiencelevel`,`temp_experiencelevel`,`temp_name`,`duration`,`employmenttype`,`budget`,`total`,`creationdate`,`resumes`,`name`,`mobilenumber`,`remark`,`isordered`,`remuneration`,`operating`,`operatingvalue`,`tax`,`taxvalue`,`admin`,`admincharge`,`grandtotal`,`isAdditional`,`change_refrence`) values (3745,151,1,3,4,'','(3+ years)',2,50,'<p>Understanding of Excise / taxation/ Supply chain/ Government processes preferred.</p>',0,0,NULL,'12','FULL TIME',3894000,0,'2026-05-03 14:52:51',NULL,NULL,NULL,'<p>Focus- Operations, Documentation, and Implementation</p>\r\n<ol>\r\n<li>Operational Monitoring- Track the daily implementation of government schemes and corporate directives.</li>\r\n<li>Standard Operating Procedures (SOPs)- Create detailed manuals for retail shop operations and warehouse management.</li>\r\n<li>GrievanceRedressal- Manage the system for handling complaints from citizens or stakeholders.</li>\r\n<li>Field Coordination- Visit field offices/ retail points to ensure digital systems are being used correctly.</li>\r\n<li>Documentation &amp; reporting- Maintain all official files, meeting minutes, and progress reports for CHiPS.</li>\r\n<li>Training Coordination- Organize training sessions for ground staff on new digital apps and compliance tools.</li>\r\n<li>Data Validation- Verify the accuracy of data entered at the field before it reaches the main database.</li>\r\n<li>Transparency Initiatives- Ensure that all public-facing information is updated on the corporate portal regularly.</li>\r\n<li>Procurement Assistance- Help in the preparation of tender documents and technical specifications for office equipment.</li>\r\n<li>Administrative Coordination- Facilitate the logistical needs of the consulting team and liaison with the CEO&rsquo;s office.</li>\r\n</ol>',1,275000,0,0,18,594000,5,194700,4088700,0,NULL);
