insert  into `eoi_request_prebid_query`(`questionid`,`queryid`,`requestid`,`vendorid`,`clause_reference`,`clause_detail`,`queries_with_justification`,`creationdate`,`iseditable`,`answer`,`answeredon`,`subuserid`,`isprebid`) values (44,19,128,3,'<p>Clause 3.1 <br>Page no  5 </p>','<p>Baseline Assessment and Data Collection <br><br>Baseline Assessment and<br>Data Collection<br>- • Conduct a baseline<br>survey in the concerned<br>district through<br>appropriate<br>methodologies.<br>- • Engage with Gram<br>Sabhas, local bodies,<br>community<br>representatives, and<br>relevant<br>- stakeholders to identify<br>development gaps and<br>priority needs.<br>- • Review and utilize any<br>existing surveys,<br>studies, or reports<br>prepared by government<br>- departments, wherever<br>available.<br>- • Prepare a<br>comprehensive Needs<br>Assessment Report<br>highlighting key<br>development<br>- priorities and sectoral<br>gaps.</p>','<p>&nbsp;</p>\r\n<div class=\"ListContainerWrapper SCXW59839813 BCX8\">\r\n<ul class=\"BulletListStyle1 SCXW59839813 BCX8\" role=\"list\">\r\n<li class=\"OutlineElement Ltr SCXW59839813 BCX8\" role=\"listitem\" aria-setsize=\"-1\" data-leveltext=\"-\" data-font=\"EYInterstate Light\" data-listid=\"25\" data-list-defn-props=\"{&quot;335551671&quot;:8,&quot;335552541&quot;:1,&quot;335559685&quot;:360,&quot;335559991&quot;:360,&quot;469769226&quot;:&quot;EYInterstate Light&quot;,&quot;469769242&quot;:[8226],&quot;469777803&quot;:&quot;left&quot;,&quot;469777804&quot;:&quot;-&quot;,&quot;469777815&quot;:&quot;hybridMultilevel&quot;}\" data-aria-posinset=\"11\" data-aria-level=\"1\">\r\n<p class=\"Paragraph SCXW59839813 BCX8\"><span class=\"TextRun SCXW59839813 BCX8\" lang=\"EN-US\" xml:lang=\"EN-US\" data-contrast=\"auto\"><span class=\"NormalTextRun SCXW59839813 BCX8\">Please provide the list of Directly and Indirectly Affected Villages along with the number of households</span></span><span class=\"EOP SCXW59839813 BCX8\" data-ccp-props=\"{&quot;201341983&quot;:0,&quot;335559739&quot;:0,&quot;335559740&quot;:240}\">&nbsp;</span></p>\r\n</li>\r\n</ul>\r\n</div>\r\n<div class=\"ListContainerWrapper SCXW59839813 BCX8\">\r\n<ul class=\"BulletListStyle1 SCXW59839813 BCX8\" role=\"list\">\r\n<li class=\"OutlineElement Ltr SCXW59839813 BCX8\" role=\"listitem\" aria-setsize=\"-1\" data-leveltext=\"-\" data-font=\"EYInterstate Light\" data-listid=\"25\" data-list-defn-props=\"{&quot;335551671&quot;:8,&quot;335552541&quot;:1,&quot;335559685&quot;:360,&quot;335559991&quot;:360,&quot;469769226&quot;:&quot;EYInterstate Light&quot;,&quot;469769242&quot;:[8226],&quot;469777803&quot;:&quot;left&quot;,&quot;469777804&quot;:&quot;-&quot;,&quot;469777815&quot;:&quot;hybridMultilevel&quot;}\" data-aria-posinset=\"12\" data-aria-level=\"1\">\r\n<p class=\"Paragraph SCXW59839813 BCX8\"><span class=\"TextRun SCXW59839813 BCX8\" lang=\"EN-US\" xml:lang=\"EN-US\" data-contrast=\"auto\"><span class=\"NormalTextRun SCXW59839813 BCX8\">Please&nbsp;</span><span class=\"NormalTextRun SCXW59839813 BCX8\">indicate</span><span class=\"NormalTextRun SCXW59839813 BCX8\">&nbsp;sample size of the villages/HHs to be surveyed</span></span><span class=\"EOP SCXW59839813 BCX8\" data-ccp-props=\"{&quot;201341983&quot;:0,&quot;335559739&quot;:0,&quot;335559740&quot;:240}\">&nbsp;</span></p>\r\n</li>\r\n</ul>\r\n</div>\r\n<div class=\"ListContainerWrapper SCXW59839813 BCX8\">\r\n<ul class=\"BulletListStyle1 SCXW59839813 BCX8\" role=\"list\">\r\n<li class=\"OutlineElement Ltr SCXW59839813 BCX8\" role=\"listitem\" aria-setsize=\"-1\" data-leveltext=\"-\" data-font=\"EYInterstate Light\" data-listid=\"25\" data-list-defn-props=\"{&quot;335551671&quot;:8,&quot;335552541&quot;:1,&quot;335559685&quot;:360,&quot;335559991&quot;:360,&quot;469769226&quot;:&quot;EYInterstate Light&quot;,&quot;469769242&quot;:[8226],&quot;469777803&quot;:&quot;left&quot;,&quot;469777804&quot;:&quot;-&quot;,&quot;469777815&quot;:&quot;hybridMultilevel&quot;}\" data-aria-posinset=\"13\" data-aria-level=\"1\">\r\n<p class=\"Paragraph SCXW59839813 BCX8\"><span class=\"TextRun SCXW59839813 BCX8\" lang=\"EN-US\" xml:lang=\"EN-US\" data-contrast=\"auto\"><span class=\"NormalTextRun SCXW59839813 BCX8\">We assume that:</span></span> <span class=\"TextRun SCXW59839813 BCX8\" lang=\"EN-US\" xml:lang=\"EN-US\" data-contrast=\"auto\"><span class=\"NormalTextRun ContextualSpellingAndGrammarErrorV2Themed SCXW59839813 BCX8\">the</span><span class=\"NormalTextRun SCXW59839813 BCX8\">&nbsp;PMU&nbsp;</span><span class=\"NormalTextRun SCXW59839813 BCX8\">will&nbsp;</span><span class=\"NormalTextRun SCXW59839813 BCX8\">develop the survey instruments and prepare the report while the actual survey will be conducted by grassroot functionaries of the government</span><span class=\"NormalTextRun SCXW59839813 BCX8\">.</span><span class=\"NormalTextRun SCXW59839813 BCX8\">&nbsp;T</span><span class=\"NormalTextRun SCXW59839813 BCX8\">he PMU team will&nbsp;</span><span class=\"NormalTextRun SCXW59839813 BCX8\">not be&nbsp;</span><span class=\"NormalTextRun SCXW59839813 BCX8\">physically</span><span class=\"NormalTextRun SCXW59839813 BCX8\">&nbsp;</span><span class=\"NormalTextRun SCXW59839813 BCX8\">conduct</span><span class=\"NormalTextRun SCXW59839813 BCX8\">ing</span><span class=\"NormalTextRun SCXW59839813 BCX8\">&nbsp;door-to-door&nbsp;</span><span class=\"NormalTextRun ContextualSpellingAndGrammarErrorV2Themed SCXW59839813 BCX8\">survey</span><span class=\"NormalTextRun SCXW59839813 BCX8\">. Please confirm our understanding.</span></span><span class=\"EOP SCXW59839813 BCX8\" data-ccp-props=\"{&quot;201341983&quot;:0,&quot;335559739&quot;:0,&quot;335559740&quot;:240}\">&nbsp;</span></p>\r\n</li>\r\n</ul>\r\n</div>\r\n<div class=\"ListContainerWrapper SCXW59839813 BCX8\">\r\n<ul class=\"BulletListStyle2 SCXW59839813 BCX8\" role=\"list\">\r\n<li class=\"OutlineElement Ltr SCXW59839813 BCX8\" role=\"listitem\" aria-setsize=\"-1\" data-leveltext=\"o\" data-font=\"Courier New\" data-listid=\"25\" data-list-defn-props=\"{&quot;335552541&quot;:1,&quot;335559685&quot;:1080,&quot;335559991&quot;:360,&quot;469769226&quot;:&quot;Courier New&quot;,&quot;469769242&quot;:[9675],&quot;469777803&quot;:&quot;left&quot;,&quot;469777804&quot;:&quot;o&quot;,&quot;469777815&quot;:&quot;hybridMultilevel&quot;}\" data-aria-posinset=\"2\" data-aria-level=\"2\">\r\n<p class=\"Paragraph SCXW59839813 BCX8\"><span class=\"TextRun SCXW59839813 BCX8\" lang=\"EN-US\" xml:lang=\"EN-US\" data-contrast=\"auto\"><span class=\"NormalTextRun ContextualSpellingAndGrammarErrorV2Themed SCXW59839813 BCX8\">the</span><span class=\"NormalTextRun SCXW59839813 BCX8\">&nbsp;gap-analysis report&nbsp;</span><span class=\"NormalTextRun SCXW59839813 BCX8\">will&nbsp;</span><span class=\"NormalTextRun SCXW59839813 BCX8\">be prepared using secondary data available with various departments/ in Mission&nbsp;</span><span class=\"NormalTextRun SCXW59839813 BCX8\">Antyodaya</span><span class=\"NormalTextRun SCXW59839813 BCX8\">&nbsp;portal, etc.</span><span class=\"NormalTextRun SCXW59839813 BCX8\">&nbsp;</span><span class=\"NormalTextRun SCXW59839813 BCX8\">Please confirm our understanding.</span></span><span class=\"EOP SCXW59839813 BCX8\" data-ccp-props=\"{&quot;201341983&quot;:0,&quot;335559739&quot;:0,&quot;335559740&quot;:240}\">&nbsp;</span></p>\r\n</li>\r\n</ul>\r\n</div>','2026-03-20 16:44:53',1,'<p>All the work will be done by the consulting agency.</p>','2026-03-24 17:42:31',NULL,1);
insert  into `eoi_request_prebid_query`(`questionid`,`queryid`,`requestid`,`vendorid`,`clause_reference`,`clause_detail`,`queries_with_justification`,`creationdate`,`iseditable`,`answer`,`answeredon`,`subuserid`,`isprebid`) values (45,19,128,3,'<p>Clause ref : 3.3 <br>Page no 5</p>','<p>Sectoral Planning<br>- The perspective plan<br>shall cover priority<br>sectors, including but<br>not limited to:<br>- • Drinking Water<br>- • Health<br>- • Education<br>- • Women and Child<br>Welfare<br>- • Roads<br>- • Irrigation<br> • Other relevant<br>development sectors<br>- • Each sector shall<br>include specific<br>objectives, proposed<br>interventions, expected<br>outcomes,<br>- and estimated budgets.</p>','<p><span class=\"NormalTextRun SCXW186975766 BCX8\">We assume that&nbsp;</span><span class=\"NormalTextRun SCXW186975766 BCX8\">the respective line departments will&nbsp;</span><span class=\"NormalTextRun SCXW186975766 BCX8\">be responsible for</span><span class=\"NormalTextRun SCXW186975766 BCX8\">&nbsp;</span><span class=\"NormalTextRun SCXW186975766 BCX8\">finalizing</span><span class=\"NormalTextRun SCXW186975766 BCX8\"> the estimated budgets and timelines for the proposed projects in the <span class=\"TextRun SCXW186975766 BCX8\" lang=\"EN-IN\" xml:lang=\"EN-IN\" data-contrast=\"auto\">plan document.&nbsp;</span><span class=\"TextRun SCXW186975766 BCX8\" lang=\"EN-US\" xml:lang=\"EN-US\" data-contrast=\"auto\">Please confirm our understanding.</span></span></p>','2026-03-20 16:46:31',1,'<p>Yes</p>','2026-03-24 17:44:12',NULL,1);
insert  into `eoi_request_prebid_query`(`questionid`,`queryid`,`requestid`,`vendorid`,`clause_reference`,`clause_detail`,`queries_with_justification`,`creationdate`,`iseditable`,`answer`,`answeredon`,`subuserid`,`isprebid`) values (46,19,128,3,'<p> 3.5 &  6 </p>','<p>Stakeholder Consultation<br>and Validation<br>- • Facilitate consultations<br>with district<br>administration, line<br>departments, Gram<br>Sabhas, and<br>- other stakeholders<br>during plan preparation.<br>- • Incorporate feedback<br>received from<br>stakeholders to ensure<br>that the plans reflect<br>local<br>- development needs and<br>priorities.</p>','<p>&nbsp;<span class=\"TextRun SCXW129571218 BCX8\" lang=\"EN-US\" xml:lang=\"EN-US\" data-contrast=\"auto\"><span class=\"NormalTextRun SCXW129571218 BCX8\">We are assuming that the line departments will conduct the Gram Sabhas. PMU will&nbsp;</span><span class=\"NormalTextRun SCXW129571218 BCX8\">facilitate</span><span class=\"NormalTextRun SCXW129571218 BCX8\">&nbsp;and support the incorporation of feedback from various stakeholders for its effective reflection in the development plans.</span><span class=\"NormalTextRun SCXW129571218 BCX8\">&nbsp;</span><span class=\"NormalTextRun SCXW129571218 BCX8\">Please confirm our understanding.</span></span><span class=\"EOP SCXW129571218 BCX8\" data-ccp-props=\"{&quot;201341983&quot;:0,&quot;335559739&quot;:0,&quot;335559740&quot;:240}\">&nbsp;</span></p>','2026-03-20 16:47:34',1,'<p>Yes</p>','2026-03-24 17:45:13',NULL,1);
insert  into `eoi_request_prebid_query`(`questionid`,`queryid`,`requestid`,`vendorid`,`clause_reference`,`clause_detail`,`queries_with_justification`,`creationdate`,`iseditable`,`answer`,`answeredon`,`subuserid`,`isprebid`) values (47,19,128,3,'<p> 4.2 & 7</p>','<p>Consultant Governance Sector <br><br>Experience- Minimum 8<br>- years of relevant<br>- professional experience<br>- in governance, public<br>- sector programs,<br>- development projects,<br>or<br>- consultancy<br>- assignments.</p>','<p><span class=\"NormalTextRun SCXW34529045 BCX8\">Please clarify whether the required experience for the &lsquo;Consultant&rsquo; position is 8 years or 3 years, as per the experience criteria outlined in the&nbsp;</span><span class=\"NormalTextRun SCXW34529045 BCX8\">CHiPS</span><span class=\"NormalTextRun SCXW34529045 BCX8\">&nbsp;agreement</span></p>','2026-03-20 16:48:34',1,'<p class=\"MsoNormal\"><span style=\"font-size: 10.0pt; line-height: 107%; font-family: \'Segoe UI\',sans-serif; color: black; background: white;\">Consultant</span></p>\r\n<p class=\"MsoNormal\">Experience- Minimum 8 years of relevant professional experience in governance, public sector programs, development projects, or consultancy assignments.</p>','2026-03-24 17:46:13',NULL,1);
insert  into `eoi_request_prebid_query`(`questionid`,`queryid`,`requestid`,`vendorid`,`clause_reference`,`clause_detail`,`queries_with_justification`,`creationdate`,`iseditable`,`answer`,`answeredon`,`subuserid`,`isprebid`) values (48,19,128,3,'<p>6 & 8</p>','<p>Payment Terms <br><br>Payment to selected bidder<br>for the scope of work done<br>will be released as per the<br>following<br>- schedule.<br>- • The successful bidder<br>shall submit the invoice<br>for payment on man<br>month basis as per the<br>- agreed empanelment<br>terms.<br>- • For reasons beyond<br>the control of the<br>selected bidder or CHiPS, as the case may<br>be<br>selected bidder shall be<br>paid the requisite man<br>month payment in the<br>event that selected<br>bidder has performed on<br>its obligations in<br>compliance with the<br>terms of this contract.</p>','<div class=\"ListContainerWrapper SCXW9737282 BCX8\">\r\n<ul class=\"BulletListStyle1 SCXW9737282 BCX8\" role=\"list\">\r\n<li class=\"OutlineElement Ltr SCXW9737282 BCX8\" role=\"listitem\" aria-setsize=\"-1\" data-leveltext=\"-\" data-font=\"EYInterstate Light\" data-listid=\"25\" data-list-defn-props=\"{&quot;335551671&quot;:8,&quot;335552541&quot;:1,&quot;335559685&quot;:360,&quot;335559991&quot;:360,&quot;469769226&quot;:&quot;EYInterstate Light&quot;,&quot;469769242&quot;:[8226],&quot;469777803&quot;:&quot;left&quot;,&quot;469777804&quot;:&quot;-&quot;,&quot;469777815&quot;:&quot;hybridMultilevel&quot;}\" data-aria-posinset=\"17\" data-aria-level=\"1\">\r\n<p class=\"Paragraph SCXW9737282 BCX8\"><span class=\"TextRun SCXW9737282 BCX8\" lang=\"EN-US\" xml:lang=\"EN-US\" data-contrast=\"auto\"><span class=\"NormalTextRun SCXW9737282 BCX8\">Kindly confirm if official&nbsp;</span><span class=\"NormalTextRun ContextualSpellingAndGrammarErrorV2Themed SCXW9737282 BCX8\">vehicle</span><span class=\"NormalTextRun SCXW9737282 BCX8\">&nbsp;will be made available to the team for field visits, both for the survey and PMU operations.</span></span><span class=\"EOP SCXW9737282 BCX8\" data-ccp-props=\"{&quot;201341983&quot;:0,&quot;335559739&quot;:0,&quot;335559740&quot;:240}\">&nbsp;</span></p>\r\n</li>\r\n</ul>\r\n</div>\r\n<div class=\"ListContainerWrapper SCXW9737282 BCX8\">\r\n<ul class=\"BulletListStyle1 SCXW9737282 BCX8\" role=\"list\">\r\n<li class=\"OutlineElement Ltr SCXW9737282 BCX8\" role=\"listitem\" aria-setsize=\"-1\" data-leveltext=\"-\" data-font=\"EYInterstate Light\" data-listid=\"23\" data-list-defn-props=\"{&quot;335551671&quot;:8,&quot;335552541&quot;:1,&quot;335559685&quot;:360,&quot;335559991&quot;:360,&quot;469769226&quot;:&quot;EYInterstate Light&quot;,&quot;469769242&quot;:[8226],&quot;469777803&quot;:&quot;left&quot;,&quot;469777804&quot;:&quot;-&quot;,&quot;469777815&quot;:&quot;hybridMultilevel&quot;}\" data-aria-posinset=\"18\" data-aria-level=\"1\">\r\n<p class=\"Paragraph SCXW9737282 BCX8\"><span class=\"TextRun SCXW9737282 BCX8\" lang=\"EN-US\" xml:lang=\"EN-US\" data-contrast=\"auto\"><span class=\"NormalTextRun SCXW9737282 BCX8\">Kindly confirm whether the Out-of-Pocket expenses incurred by the PMU will be reimbursed as per actuals.</span></span><span class=\"EOP SCXW9737282 BCX8\" data-ccp-props=\"{&quot;201341983&quot;:0,&quot;335559739&quot;:0,&quot;335559740&quot;:240}\">&nbsp;</span></p>\r\n</li>\r\n</ul>\r\n</div>','2026-03-20 16:49:58',1,'<p>No</p>','2026-03-24 17:47:03',NULL,1);
insert  into `eoi_request_prebid_query`(`questionid`,`queryid`,`requestid`,`vendorid`,`clause_reference`,`clause_detail`,`queries_with_justification`,`creationdate`,`iseditable`,`answer`,`answeredon`,`subuserid`,`isprebid`) values (49,20,129,5,'<p>1. Factsheet, Page - 4</p>','<p>Last date of bid query: 19/03/2026</p>','<p>Request you to kindly confirm if there is any pre-bid meeting (either physical or VC) scheduled. If VC, please share meeting link.</p>','2026-03-24 15:36:29',1,'<p><span data-sheets-root=\"1\">As per EoI.</span></p>','2026-04-04 19:16:39',NULL,1);
insert  into `eoi_request_prebid_query`(`questionid`,`queryid`,`requestid`,`vendorid`,`clause_reference`,`clause_detail`,`queries_with_justification`,`creationdate`,`iseditable`,`answer`,`answeredon`,`subuserid`,`isprebid`) values (50,20,129,5,'<p>1. Factsheet, Page - 4</p>','<p>Last date (deadline) for submission of proposals: 03/04/2026</p>','<p>Request you to kindly provide atleast 2 more weeks for submission of proposal.</p>','2026-03-24 15:41:17',1,'<p><span data-sheets-root=\"1\">Revised last date for submission of proposals - 10-04-2026, 05:00 PM</span></p>','2026-04-04 19:17:01',NULL,1);
insert  into `eoi_request_prebid_query`(`questionid`,`queryid`,`requestid`,`vendorid`,`clause_reference`,`clause_detail`,`queries_with_justification`,`creationdate`,`iseditable`,`answer`,`answeredon`,`subuserid`,`isprebid`) values (51,20,129,5,'<p>3. Scope of Work, Page - 5</p>','<p>Should be able to take (integrate) structured/unstructured data from the CM helpline project database, apply ETL and generate insights, dashboards for the CMO, GG&amp;C, Secretaries etc. Or<br>any other analysis report as asked by the authority</p>','<p>We assume that CHIPS shall provide necessary tools, infrastructure, Software Licenses to carry out this activity. Please clarify whether our understanding is correct or not.</p>','2026-03-24 15:41:49',1,'<p><span data-sheets-root=\"1\">Will be discussed and finalised with the selected Consultant. However, Any license cost required for DA will be procured by GG&amp;C</span></p>','2026-04-04 19:17:18',NULL,1);
insert  into `eoi_request_prebid_query`(`questionid`,`queryid`,`requestid`,`vendorid`,`clause_reference`,`clause_detail`,`queries_with_justification`,`creationdate`,`iseditable`,`answer`,`answeredon`,`subuserid`,`isprebid`) values (52,20,129,5,'<p>3. Scope of Work, Page - 6</p>','<p>Build role‑specific dashboards covering call center operations, grievance movement, escalations, ageing, district and departmental performance, citizen feedback, and service timelines</p>','<p>We assume that CHIPS shall provide necessary tools, infrastructure, Software Licenses to carry out this activity. Please clarify whether our understanding is correct or not.</p>','2026-03-24 15:42:27',1,'<p><span data-sheets-root=\"1\">Will be discussed and finalised with the selected Consultant. However, Any license cost required for DA will be procured by GG&amp;C</span></p>','2026-04-04 19:17:37',NULL,1);
insert  into `eoi_request_prebid_query`(`questionid`,`queryid`,`requestid`,`vendorid`,`clause_reference`,`clause_detail`,`queries_with_justification`,`creationdate`,`iseditable`,`answer`,`answeredon`,`subuserid`,`isprebid`) values (53,20,129,5,'<p>3. Scope of Work, Page - 6</p>','<p>Ensure dashboards meet requirements such as trend analytics, SLA monitoring, departmental drill‑downs, and export options (PDF, PPT, XLS).</p>','<p>We assume that CHIPS shall provide necessary analytical tool which provides functionality to export dashboards and reports in PDF, PPT, XLS. Please clarify whether our understanding is correct or not.</p>','2026-03-24 15:42:52',1,'<p><span data-sheets-root=\"1\">Will be discussed and finalised with the selected Consultant. However, Any license cost required for DA will be procured by GG&amp;C.</span></p>','2026-04-04 19:18:00',NULL,1);
insert  into `eoi_request_prebid_query`(`questionid`,`queryid`,`requestid`,`vendorid`,`clause_reference`,`clause_detail`,`queries_with_justification`,`creationdate`,`iseditable`,`answer`,`answeredon`,`subuserid`,`isprebid`) values (54,20,129,5,'<p>3. Scope of Work, Page - 6</p>','<p>Standardize master data across departments (service categories, district codes, escalation levels, department names).</p>','<p>We assume that CHIPS shall provide Master Data Management tool to carry out this activity.</p>','2026-03-24 15:43:17',1,'<p><span data-sheets-root=\"1\">Will be discussed and finalised with the selected Consultant. However, Any license cost required for DA will be procured by GG&amp;C.</span></p>','2026-04-04 19:18:22',NULL,1);
insert  into `eoi_request_prebid_query`(`questionid`,`queryid`,`requestid`,`vendorid`,`clause_reference`,`clause_detail`,`queries_with_justification`,`creationdate`,`iseditable`,`answer`,`answeredon`,`subuserid`,`isprebid`) values (55,20,129,5,'<p>3. Scope of Work</p>','<p>NA</p>','<p>Request you to kindly provide following details which can help us prepare comprehensive solution:<br>1. Current Technology Stack (Application, Database, OS)<br>2. Volumetrics (Size of database)<br>3. No. of Dashboard Users (Role based users, concurrent users)<br>4. No. of Users for Training<br>5. No. of Departments integrated with CM Helpline project</p>','2026-03-24 15:43:43',1,'<p><span data-sheets-root=\"1\">As per EoI, agencies are also requested to study CM Helpline RFP for more details <a class=\"in-cell-link\" href=\"https://goodgovernance.cgstate.gov.in/en/reports-data\" target=\"_blank\" rel=\"noopener\">https://goodgovernance.cgstate.gov.in/en/reports-data<br></a></span></p>','2026-04-04 19:18:45',NULL,1);
insert  into `eoi_request_prebid_query`(`questionid`,`queryid`,`requestid`,`vendorid`,`clause_reference`,`clause_detail`,`queries_with_justification`,`creationdate`,`iseditable`,`answer`,`answeredon`,`subuserid`,`isprebid`) values (56,20,129,5,'<p>3. Scope of Work</p>','<p>NA</p>','<p>We assume that role of consultants are limited to data analytics. If there is any need to develop API to integrate with application, same shall be provided by CHIPS.</p>','2026-03-24 15:44:12',1,'<p><span data-sheets-root=\"1\">Any API that needs to be consumed by the dashboard team will be created by the relevant client or its SI. However, the required connector to connect will be done by the DA team.<br>Secondly, the DA team should also be able to share the API from the dashboard/analytics database with other teams.</span></p>','2026-04-04 19:19:12',NULL,1);
insert  into `eoi_request_prebid_query`(`questionid`,`queryid`,`requestid`,`vendorid`,`clause_reference`,`clause_detail`,`queries_with_justification`,`creationdate`,`iseditable`,`answer`,`answeredon`,`subuserid`,`isprebid`) values (57,20,129,5,'<p>4. Team Requirement&nbsp;</p>','<p>NA</p>','<p>Considering the quantum of work and duration of project, it is suggested to include 3-4 Senior Consultants or Consultants in the team</p>','2026-03-24 15:44:37',1,'<p><span data-sheets-root=\"1\">As per EoI.</span></p>','2026-04-04 19:19:34',NULL,1);
insert  into `eoi_request_prebid_query`(`questionid`,`queryid`,`requestid`,`vendorid`,`clause_reference`,`clause_detail`,`queries_with_justification`,`creationdate`,`iseditable`,`answer`,`answeredon`,`subuserid`,`isprebid`) values (58,20,129,5,'<p>3. Scope of Work, Page - 6</p>','<p>Train Department Officers, District officials, and PMU team members on using dashboards,<br>interpreting analytical insights, and understanding KPIs.</p>','<p>Please clarify the following:<br>1. How many trainings are to be conducted?&nbsp;<br>2. Training users &nbsp;<br>We assume that logistics (Training hall, travel, training equipment etc.) shall be arranged by CHIPS</p>','2026-03-24 15:45:08',1,'<p><span data-sheets-root=\"1\">As per EoI. Logistics if required will be borne by GG&amp;C and paid to selected consultant as per the empanelment agreement.</span></p>','2026-04-04 19:19:56',NULL,1);
insert  into `eoi_request_prebid_query`(`questionid`,`queryid`,`requestid`,`vendorid`,`clause_reference`,`clause_detail`,`queries_with_justification`,`creationdate`,`iseditable`,`answer`,`answeredon`,`subuserid`,`isprebid`) values (59,20,129,5,'<p>8. Evaluation Process, Page - 8</p>','<p>Further, any deviation from proposal and resource CV submitted as bid response to this EOI would not be considered and would be duly ruled as rejection. Therefore, it is instructed to bidders that the actual resource who will be deployed for assignment should be present for interview (in person/VC).</p>','<p>We request to consider deviation due to any delay or reasons beyond susbtantial control of the bidder.</p>','2026-03-24 15:45:31',1,'<p><span data-sheets-root=\"1\">As per EoI.</span></p>','2026-04-04 19:20:14',NULL,1);
insert  into `eoi_request_prebid_query`(`questionid`,`queryid`,`requestid`,`vendorid`,`clause_reference`,`clause_detail`,`queries_with_justification`,`creationdate`,`iseditable`,`answer`,`answeredon`,`subuserid`,`isprebid`) values (60,21,126,4,'<p>Scope of Work, Pg 6</p>','<p><span lang=\"EN-GB\" style=\"font-size: 10.0pt; line-height: 107%; font-family: \'Arial\',sans-serif; mso-fareast-font-family: Calibri; mso-fareast-theme-font: minor-latin; mso-ansi-language: EN-GB; mso-fareast-language: EN-US; mso-bidi-language: AR-SA;\">Conduct a baseline survey in the concerned district through appropriate methodologies </span></p>','<p><span lang=\"EN-GB\" style=\"font-size: 10.0pt; line-height: 107%; font-family: \'Arial\',sans-serif; mso-fareast-font-family: Calibri; mso-fareast-theme-font: minor-latin; mso-ansi-language: EN-GB; mso-fareast-language: EN-US; mso-bidi-language: AR-SA;\"><strong>Question:</strong> We request confirmation on the number of directly and indirectly affected villages to devise methodology.&nbsp;<br><br><strong>Justification: </strong>This information is essential to help us determine the appropriate sample size and estimate the cost of conducting the survey</span></p>','2026-03-24 16:03:38',1,'<p>No. of Direct affected Villages - 623</p>\n<p>No. of Indirect affected Villages - 80</p>','2026-03-30 13:50:07',NULL,1);
insert  into `eoi_request_prebid_query`(`questionid`,`queryid`,`requestid`,`vendorid`,`clause_reference`,`clause_detail`,`queries_with_justification`,`creationdate`,`iseditable`,`answer`,`answeredon`,`subuserid`,`isprebid`) values (61,21,126,4,'<p>Scope of Work, Pg. 6</p>','<p><span lang=\"EN-GB\" style=\"font-size: 10.0pt; line-height: 107%; font-family: \'Arial\',sans-serif; mso-fareast-font-family: Calibri; mso-fareast-theme-font: minor-latin; mso-ansi-language: EN-GB; mso-fareast-language: EN-US; mso-bidi-language: AR-SA;\">Conduct a baseline survey in the concerned district through appropriate methodologies</span></p>','<div style=\"mso-element: frame; mso-element-frame-hspace: 9.0pt; mso-element-wrap: around; mso-element-anchor-vertical: paragraph; mso-element-anchor-horizontal: margin; mso-element-left: -31.75pt; mso-element-top: 13.5pt; mso-height-rule: exactly;\">&nbsp;</div>\r\n<p class=\"MsoNormal\" style=\"mso-element: frame; mso-element-frame-hspace: 9.0pt; mso-element-wrap: around; mso-element-anchor-vertical: paragraph; mso-element-anchor-horizontal: margin; mso-element-left: -31.75pt; mso-element-top: 13.5pt; mso-height-rule: exactly;\"><span lang=\"EN-GB\" style=\"font-size: 10.0pt; line-height: 107%; font-family: \'Arial\',sans-serif;\"><strong>Question: </strong>As per the RFP requirement, a baseline survey in the concerned district is to be conducted using appropriate methodologies. We seek clarification on whether the ground-level survey is to be undertaken by the selected consulting agency, as this would involve additional survey-related costs.</span></p>\r\n<p class=\"MsoNormal\" style=\"mso-element: frame; mso-element-frame-hspace: 9.0pt; mso-element-wrap: around; mso-element-anchor-vertical: paragraph; mso-element-anchor-horizontal: margin; mso-element-left: -31.75pt; mso-element-top: 13.5pt; mso-height-rule: exactly;\"><span lang=\"EN-GB\" style=\"font-size: 10.0pt; line-height: 107%; font-family: \'Arial\',sans-serif;\">In this regard, we propose an alternative approach wherein the ground survey may be conducted using data and support from the State/District Government Planning Department, while the PMU/Consulting Agency undertakes survey designing, data analysis, validation, and preparation of the perspective plan.</span></p>\r\n<p><span lang=\"EN-GB\" style=\"font-size: 10.0pt; line-height: 107%; font-family: \'Arial\',sans-serif; mso-fareast-font-family: Calibri; mso-fareast-theme-font: minor-latin; mso-ansi-language: EN-GB; mso-fareast-language: EN-US; mso-bidi-language: AR-SA;\">Kindly confirm whether this approach would be acceptable to the Authority.<br><br><strong>Justification: </strong><span style=\"font-size: 10.0pt; line-height: 107%; font-family: \'Arial\',sans-serif; mso-fareast-font-family: Calibri; mso-fareast-theme-font: minor-latin; mso-ansi-language: EN-US; mso-fareast-language: EN-US; mso-bidi-language: AR-SA;\">To optimize project timelines by avoiding duplication of primary data collection while leveraging existing government-validated datasets and field mechanisms.</span></span></p>','2026-03-24 16:08:00',1,'<p>As per the intent of the RFP, the selected consulting agency, which will function as the Project Management Unit (PMU), is expected to undertake the baseline survey in the district using appropriate methodologies.</p>','2026-03-30 14:11:38',NULL,1);
insert  into `eoi_request_prebid_query`(`questionid`,`queryid`,`requestid`,`vendorid`,`clause_reference`,`clause_detail`,`queries_with_justification`,`creationdate`,`iseditable`,`answer`,`answeredon`,`subuserid`,`isprebid`) values (62,21,126,4,'<p><span lang=\"EN-GB\" style=\"font-size: 10.0pt; line-height: 107%; font-family: \'Arial\',sans-serif; mso-fareast-font-family: Calibri; mso-fareast-theme-font: minor-latin; mso-ansi-language: EN-GB; mso-fareast-language: EN-US; mso-bidi-language: AR-SA;\">Team Composition, Pg. 10</span></p>','<p>Procurement&nbsp;Expert&nbsp;(Associate&nbsp;Consultant&nbsp;- Financial&nbsp;&amp; Legal&nbsp;Sector)</p>','<p><span lang=\"EN-GB\" style=\"font-size: 10.0pt; line-height: 107%; font-family: \'Arial\',sans-serif; mso-fareast-font-family: Calibri; mso-fareast-theme-font: minor-latin; mso-ansi-language: EN-GB; mso-fareast-language: EN-US; mso-bidi-language: AR-SA;\"><strong>Question: </strong>The eligibility criteria specify &ldquo;master&rsquo;s degree in finance or Chartered Accountant (CA) or equivalent.&rdquo; We kindly request clarification on whether candidates holding a bachelor&rsquo;s degree in finance/commerce would also be considered eligible.<br><br><strong>Justification: </strong>This clarification is sought to ensure wider participation by qualified professionals with relevant academic backgrounds aligned to the role&rsquo;s competencies.</span></p>','2026-03-24 16:10:44',1,'<p>Given the critical nature of financial management under DMF and the need for sound financial oversight, the minimum eligibility criteria have been specified to ensure the required level of professional competence for the assignment. In this regard, candidates possessing a master&rsquo;s degree in finance or Chartered Accountant (CA) or equivalent qualification are considered essential.</p>','2026-03-30 14:16:15',NULL,1);
insert  into `eoi_request_prebid_query`(`questionid`,`queryid`,`requestid`,`vendorid`,`clause_reference`,`clause_detail`,`queries_with_justification`,`creationdate`,`iseditable`,`answer`,`answeredon`,`subuserid`,`isprebid`) values (63,22,133,5,'<p>Factsheet | Sec 01 | Page 04</p>','<p>Last Date of Bid Submission | 09/04/2026 ; 17:00 Hrs.</p>','<p>We request for providing an extension of the bid submission deadline by a minimum of three weeks from the date of the corrigendum or query response. As basis the credendum, we need sufficient time to completed internal legal/risk formalities for Participation in the bid.&nbsp;</p>','2026-03-24 16:13:56',1,'<p>As per EOI</p>','2026-03-27 16:28:40',NULL,1);
insert  into `eoi_request_prebid_query`(`questionid`,`queryid`,`requestid`,`vendorid`,`clause_reference`,`clause_detail`,`queries_with_justification`,`creationdate`,`iseditable`,`answer`,`answeredon`,`subuserid`,`isprebid`) values (64,22,133,5,'<p>Scope of Work | Sec 03 | Page 05</p>','<p>The scope covers wide range of activities like providing advisory support in Planning &amp; Implementation, DPR preparation, RFP preparation, Reviewing of Technical Architecture, Framework, Capacity Buidling including Training, Cyber Security Awareness initiatives, Assisting in Emerging Technology &amp; Tools, Cyber Threats etc.</p>','<p>The scope is very wide and covering multiple domain activities. &nbsp;To comprehensive understanding and deploye the &nbsp;most appropriate resource, we request you to share Current Cyber Security posture of Police HQ covering following details :<br>&nbsp;- Current Cyber Projects running by Police HQ along with Tools/Technology being used<br>- Upcoming Cyber Projects under pipeline ( with expected end results/Deliverables) &nbsp;where support are needed<br>- Coverage of Locations ( w.r.t Training/Capacity Building initiatives)<br>- List of Emerging Technoligies ( indicative) which are under consideration of Police HQ&nbsp;</p>','2026-03-24 16:15:18',1,'<p>As per EOI</p>','2026-03-27 16:28:59',NULL,1);
insert  into `eoi_request_prebid_query`(`questionid`,`queryid`,`requestid`,`vendorid`,`clause_reference`,`clause_detail`,`queries_with_justification`,`creationdate`,`iseditable`,`answer`,`answeredon`,`subuserid`,`isprebid`) values (65,22,133,5,'<p>Team Composition | Sec 04 | Page 06</p>','<p>Team Composition&nbsp;</p>','<p>As mentioned above, scope is very wide and covering Multiple domains. This requires multiple domain experts &amp; SMEs to deliver the various activties defined in this EOI. &nbsp;However, as per EOI, it is noticed that, &nbsp;only one Consultant has been considered for Project deployment. Given the multidimensional nature of these responsibilities, it may not be feasible or practical for considering only one resource under the Project.&nbsp;<br>In view of the above facts, May we request to increase the no. of resources to be deployed under this Engagements as under :<br>- 01 - Project Manager/Pricipal Consultant<br>- 02- &nbsp;SME- Expert in &nbsp;Cyber Technologies/Tools<br>- 01 - DPR/RFP Experts<br>- 01- Training experts</p>','2026-03-24 16:16:08',1,'<p>As per EOI</p>','2026-03-27 16:29:16',NULL,1);
insert  into `eoi_request_prebid_query`(`questionid`,`queryid`,`requestid`,`vendorid`,`clause_reference`,`clause_detail`,`queries_with_justification`,`creationdate`,`iseditable`,`answer`,`answeredon`,`subuserid`,`isprebid`) values (66,22,133,5,'<p>Duration of the Assignment | &nbsp;Sec 05 | Page 07</p>','<p>The Consultant shall be engaged initially for a period of five (05) months.</p>','<p>Considering the Scope defined in EOI mainly, involving in reviewing of Architecure, Assisting in Solution design basis new requirement, DPR prepareation, RFP preparation, Implementation support etc, the 05 months time looks very insufficient. &nbsp;Also, looking to the longer impact of such Projects, a long association of the resources are very essential to make success of said projects.&nbsp;</p>\r\n<p>In view of the said facts and looking to the requirement, May we request to increase the duration of period for minimum 01 years.&nbsp;</p>','2026-03-24 16:16:59',1,'<p>As per EOI</p>','2026-03-27 16:29:32',NULL,1);
insert  into `eoi_request_prebid_query`(`questionid`,`queryid`,`requestid`,`vendorid`,`clause_reference`,`clause_detail`,`queries_with_justification`,`creationdate`,`iseditable`,`answer`,`answeredon`,`subuserid`,`isprebid`) values (67,22,133,5,'<p>Miscellaneous</p>','<p>No Deliverables /Milestone mentioned in EOI</p>','<p>It is noticed that, EOI does not speciy any defined deliverables or Milestone assiciated with it alongwith time line. &nbsp;In this regard, we understood that, this is Loan Staffing engagement &nbsp;and there is no deliverables or Milestone liabilities on the Bidder\'s end. Please correct if this understanding is not right.&nbsp;</p>','2026-03-24 16:17:53',1,'<p>As per EOI</p>','2026-03-27 16:29:58',NULL,1);
insert  into `eoi_request_prebid_query`(`questionid`,`queryid`,`requestid`,`vendorid`,`clause_reference`,`clause_detail`,`queries_with_justification`,`creationdate`,`iseditable`,`answer`,`answeredon`,`subuserid`,`isprebid`) values (68,22,133,5,'<p>Miscellaneous</p>','<p>Payment Terms</p>','<p>It is mentioned that, Payment will be made on Monthly basis. However, there is no list of activities/Milestioned mentioned in EOI. May we know the criteria of performance analysis of Bidder and condition for releasing Payment monthly?&nbsp;</p>','2026-03-24 16:18:32',1,'<p>As per EOI and Agreement.</p>','2026-03-27 16:33:26',NULL,1);
insert  into `eoi_request_prebid_query`(`questionid`,`queryid`,`requestid`,`vendorid`,`clause_reference`,`clause_detail`,`queries_with_justification`,`creationdate`,`iseditable`,`answer`,`answeredon`,`subuserid`,`isprebid`) values (69,23,126,3,'<p>Clause: 3.1</p>\r\n<p>Page no: 5</p>','<p>Scope of Work</p>','<ul type=\"disc\">\r\n<li class=\"MsoNormal\">Please provide the list of Directly Affected Villages, along with the number of households</li>\r\n<li class=\"MsoNormal\">Please indicate sample size of Indirectly Affected Villages</li>\r\n<li class=\"MsoNormal\">We assume</li>\r\n<ul type=\"circle\">\r\n<li class=\"MsoNormal\">the PMU team will not &nbsp;physically have to conduct door-to-door survey</li>\r\n<li class=\"MsoNormal\">the PMU will develop the survey instruments and prepare the report while the actual survey will be conducted by grassroot functionaries of the government</li>\r\n<li class=\"MsoNormal\">the PMU will coordinate and work with the concerned line departments</li>\r\n<li class=\"MsoNormal\">the PMU may also prepare gap-analysis report using secondary data available with various departments/ in Mission Antyodaya portal, etc.&nbsp; &nbsp;</li>\r\n<li class=\"MsoNormal\">Please confirm</li>\r\n</ul>\r\n</ul>','2026-03-24 16:56:39',1,'<ul>\r\n<li data-section-id=\"1qu7ihw\" data-start=\"84\" data-end=\"297\">The list of Directly Affected Villages along with the number of households, and the indicative sample size for Indirectly Affected Villages, shall be shared with the selected agency/PMU at the appropriate stage.</li>\r\n<li data-section-id=\"1l1edft\" data-start=\"299\" data-end=\"556\">The selected consulting agency, functioning as the PMU, is expected to undertake the baseline survey, including field-level data collection, using appropriate methodologies. Accordingly, the responsibility of conducting the survey shall rest with the PMU.</li>\r\n<li data-section-id=\"1nmiuo8\" data-start=\"558\" data-end=\"708\">The PMU is also expected to closely coordinate with the concerned line departments and other stakeholders for effective execution of the assignment.</li>\r\n<li data-section-id=\"1pusbz9\" data-start=\"710\" data-end=\"962\">Further, the PMU may undertake gap analysis by utilizing both primary data collected through the survey as well as secondary data available with various departments, including platforms such as the Mission Antyodaya portal and other relevant sources.</li>\r\n</ul>','2026-03-30 14:20:07',NULL,1);
insert  into `eoi_request_prebid_query`(`questionid`,`queryid`,`requestid`,`vendorid`,`clause_reference`,`clause_detail`,`queries_with_justification`,`creationdate`,`iseditable`,`answer`,`answeredon`,`subuserid`,`isprebid`) values (70,23,126,3,'<p>Clause: 4</p>\r\n<p>Page 7</p>','<p>Team Composition</p>','<p>DMF requires engagement of subject matter experts with considerable experience. We request if all the team members can be Senior Consultants instead of current composition in the EoI -Consultant (for TL) and Associate Consultant for other team members. This will help us deploy senior professionals with considerable experience and work for DMF Korba</p>','2026-03-24 17:00:10',1,'<p data-start=\"0\" data-end=\"204\">As per the provisions of the EoI, the proposed team structure has been designed with due consideration to both the functional requirements of the assignment and optimal utilization of available resources.</p>\r\n<p data-start=\"206\" data-end=\"534\">While the importance of experienced professionals for effective implementation is duly acknowledged, the current composition&mdash;comprising a Team Leader at the Consultant level and other team members at the Associate Consultant level&mdash;has been kept in view of budgetary considerations and the need for efficient resource deployment.</p>','2026-03-30 14:23:03',NULL,1);
insert  into `eoi_request_prebid_query`(`questionid`,`queryid`,`requestid`,`vendorid`,`clause_reference`,`clause_detail`,`queries_with_justification`,`creationdate`,`iseditable`,`answer`,`answeredon`,`subuserid`,`isprebid`) values (71,23,126,3,'<p>Clause 4:</p>\r\n<p>Page :7</p>','<p>Team Composition</p>','<p>An MIS Expert may be added in the composition as Senior Consultant to take care of the Data Integration Activities</p>','2026-03-24 17:01:41',1,'<div class=\"flex flex-col text-sm pb-25\">\r\n<section class=\"text-token-text-primary w-full focus:outline-none [--shadow-height:45px] has-data-writing-block:pointer-events-none has-data-writing-block:-mt-(--shadow-height) has-data-writing-block:pt-(--shadow-height) [&amp;:has([data-writing-block])&gt;*]:pointer-events-auto scroll-mt-[calc(var(--header-height)+min(200px,max(70px,20svh)))]\" dir=\"auto\" data-turn-id=\"request-WEB:51d20e87-0e50-4f83-a8fd-802b640af9d2-6\" data-testid=\"conversation-turn-14\" data-scroll-anchor=\"true\" data-turn=\"assistant\">\r\n<div class=\"text-base my-auto mx-auto pb-10 [--thread-content-margin:var(--thread-content-margin-xs,calc(var(--spacing)*4))] @w-sm/main:[--thread-content-margin:var(--thread-content-margin-sm,calc(var(--spacing)*6))] @w-lg/main:[--thread-content-margin:var(--thread-content-margin-lg,calc(var(--spacing)*16))] px-(--thread-content-margin)\">\r\n<div class=\"[--thread-content-max-width:40rem] @w-lg/main:[--thread-content-max-width:48rem] mx-auto max-w-(--thread-content-max-width) flex-1 group/turn-messages focus-visible:outline-hidden relative flex w-full min-w-0 flex-col agent-turn\">\r\n<div class=\"flex max-w-full flex-col gap-4 grow\">\r\n<div class=\"min-h-8 text-message relative flex w-full flex-col items-end gap-2 text-start break-words whitespace-normal outline-none keyboard-focused:focus-ring [.text-message+&amp;]:mt-1\" dir=\"auto\" tabindex=\"0\" data-message-author-role=\"assistant\" data-message-id=\"d6dd0fc3-cd74-43d2-aa9e-d9baadcfa827\" data-message-model-slug=\"gpt-5-3\" data-turn-start-message=\"true\">\r\n<div class=\"flex w-full flex-col gap-1 empty:hidden\">\r\n<div class=\"markdown prose dark:prose-invert w-full wrap-break-word dark markdown-new-styling\">\r\n<p data-start=\"0\" data-end=\"161\">As per the current scope of the EoI, the team structure has been designed keeping in view the available budget and the need for optimal utilization of resources. It is proposed to continue with the existing team composition.&nbsp;</p>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</section>\r\n</div>','2026-03-30 14:30:59',NULL,1);
insert  into `eoi_request_prebid_query`(`questionid`,`queryid`,`requestid`,`vendorid`,`clause_reference`,`clause_detail`,`queries_with_justification`,`creationdate`,`iseditable`,`answer`,`answeredon`,`subuserid`,`isprebid`) values (72,24,133,3,'<p>Section 1, fact Sheet&nbsp;Point no. 6&nbsp;<br>Page no 4</p>','<p>Last date (deadline) for submission of proposals -  09/04/2026 ; 17:00 Hrs.</p>','<p>As we need to coordinate with multiple internal departments, therefore, requesting CHiPS to extend the bid submission by 1 weeks.</p>','2026-03-24 23:00:33',1,'<p>As per EOI</p>','2026-03-27 16:30:28',NULL,1);
insert  into `eoi_request_prebid_query`(`questionid`,`queryid`,`requestid`,`vendorid`,`clause_reference`,`clause_detail`,`queries_with_justification`,`creationdate`,`iseditable`,`answer`,`answeredon`,`subuserid`,`isprebid`) values (73,24,133,3,'<p>Section 3, Scope of work Point no. C&nbsp;<br>Page no 5</p>','<p>&nbsp;Provide advisory support in planning and implementation of technology-based initiatives related to cyber security</p>','<p>As per our undersatnding, bidder need to preparae roadmap for planning and implementation of technology-based initiatives related to cyber security , requesting CHiPS to kindly confirm.&nbsp;</p>','2026-03-24 23:01:58',1,'<p>As per EOI</p>','2026-03-27 16:30:46',NULL,1);
insert  into `eoi_request_prebid_query`(`questionid`,`queryid`,`requestid`,`vendorid`,`clause_reference`,`clause_detail`,`queries_with_justification`,`creationdate`,`iseditable`,`answer`,`answeredon`,`subuserid`,`isprebid`) values (74,24,133,3,'<p>Section 3, Scope of work Point no. d<br>Page no 5</p>','<p>Assist in preparation of Detailed Project reports 9DPRs), technical concept notes, and project proposals related to cyber security initiatives</p>','<p>May we request CHiPS to kinldy clarify, for which domain 9 DPRs needs to be prepared.</p>','2026-03-24 23:02:50',1,'<p>It\'s <strong>\"(DPRs)\" </strong>not<strong> \"9DPRs)</strong>\" i.e. clerical error. No such clause is there. <strong>\"9DPRs)\" be read as \"(DPRs)\"&nbsp;</strong></p>','2026-03-27 16:31:46',NULL,1);
insert  into `eoi_request_prebid_query`(`questionid`,`queryid`,`requestid`,`vendorid`,`clause_reference`,`clause_detail`,`queries_with_justification`,`creationdate`,`iseditable`,`answer`,`answeredon`,`subuserid`,`isprebid`) values (75,24,133,3,'<p>Section 3, Scope of work Point no. E</p>\r\n<p>Page no. 5</p>','<p>Assist in drafting Request for proposal (RFP) documents and technical specifications for new technology interventions&nbsp;</p>','<p>May we request CHiPS to kindly confirm how many RFPs needs to be prepared. Also, requesting CHiPS to share the domain for which RFP will be prepared.</p>','2026-03-24 23:04:04',1,'<p>As per EOI</p>','2026-03-27 16:34:10',NULL,1);
insert  into `eoi_request_prebid_query`(`questionid`,`queryid`,`requestid`,`vendorid`,`clause_reference`,`clause_detail`,`queries_with_justification`,`creationdate`,`iseditable`,`answer`,`answeredon`,`subuserid`,`isprebid`) values (76,24,133,3,'<p>Section 3, Scope of work Point no. F<br>Page no. 5</p>','<p>Support the departmental technical evaluation of bids and tenders relating to cyber security solutions</p>','<p>As per our understanding, bidder scope is limited to technical evalaution of the RFP which bidder will prepare. Also, bidder will not be involved in any pre-bid activities as well as financial evaluation.<br>Requesting CHiPS to confirm.</p>','2026-03-24 23:05:01',1,'<p>As per EOI.</p>','2026-03-27 16:34:45',NULL,1);
insert  into `eoi_request_prebid_query`(`questionid`,`queryid`,`requestid`,`vendorid`,`clause_reference`,`clause_detail`,`queries_with_justification`,`creationdate`,`iseditable`,`answer`,`answeredon`,`subuserid`,`isprebid`) values (77,24,133,3,'<p>Section 3, Scope of work Point G</p>\r\n<p>Page no. 5</p>','<p>Assist the department in reviewing technical architecture, system design, and technology frameworks</p>','<p>May we request CHiPS to confirm name of the framework in which bidder will assist CHiPS.</p>','2026-03-24 23:06:12',1,'<p>As per EOI.</p>','2026-03-27 16:34:59',NULL,1);
insert  into `eoi_request_prebid_query`(`questionid`,`queryid`,`requestid`,`vendorid`,`clause_reference`,`clause_detail`,`queries_with_justification`,`creationdate`,`iseditable`,`answer`,`answeredon`,`subuserid`,`isprebid`) values (78,24,133,3,'<p>Section 3, Scope of work Point J</p>\r\n<p>Page no. 5</p>','<p>&nbsp;Assist in capacity building initiatives including training programs, workshops, and technical sessions for departmental officials</p>','<p>As per our understanding, cost related to training , venue, material will be borne by CHiPS.<br>Requesting CHiPS to confirm.</p>','2026-03-24 23:07:24',1,'<p>Cost related to training, venue, material will be borne by the Department.</p>','2026-03-27 16:35:36',NULL,1);
insert  into `eoi_request_prebid_query`(`questionid`,`queryid`,`requestid`,`vendorid`,`clause_reference`,`clause_detail`,`queries_with_justification`,`creationdate`,`iseditable`,`answer`,`answeredon`,`subuserid`,`isprebid`) values (79,24,133,3,'<p>Section 3, Scope of work Point L</p>\r\n<p>Page no. 6</p>','<p>Provide technical assistance in reviewing emerging cyber threats and recommending mitigation strategies</p>','<p>Requesting CHiPS to kinldy confirm what tools and technologies are being used for threat monitoring, incident response, threat analysis. As per our understanding, bidder will assist CHiPS based on system generated report only.</p>','2026-03-24 23:08:21',1,'<p>As per EOI.</p>','2026-03-27 16:36:26',NULL,1);
insert  into `eoi_request_prebid_query`(`questionid`,`queryid`,`requestid`,`vendorid`,`clause_reference`,`clause_detail`,`queries_with_justification`,`creationdate`,`iseditable`,`answer`,`answeredon`,`subuserid`,`isprebid`) values (80,24,133,3,'<p>Section 3, Scope of work Point no. M</p>\r\n<p>Page no. 6</p>','<p>Perform any other work assigned by the department relating to cyber security and IT work</p>','<p>This is very broad statement, requesting CHiPS to kindly confirm what all activities will comes under bidder scope of work.</p>','2026-03-24 23:09:02',1,'<p>As per EOI.</p>','2026-03-27 16:36:43',NULL,1);
insert  into `eoi_request_prebid_query`(`questionid`,`queryid`,`requestid`,`vendorid`,`clause_reference`,`clause_detail`,`queries_with_justification`,`creationdate`,`iseditable`,`answer`,`answeredon`,`subuserid`,`isprebid`) values (81,24,133,3,'<p>Section 4, Team Composition Sl. no. 1</p>\r\n<p>Page no. 6</p>','<p>Consultant- Cyber Security Technology (IT Sector) - 1</p>','<p>Considering the scope of work , it will be very difficult to complete all task with one (1) resource, therefore, requesting CHiPS to increase the manpower from 1 to 4.</p>','2026-03-24 23:10:06',1,'<p>As per EOI.</p>','2026-03-27 16:36:56',NULL,1);
insert  into `eoi_request_prebid_query`(`questionid`,`queryid`,`requestid`,`vendorid`,`clause_reference`,`clause_detail`,`queries_with_justification`,`creationdate`,`iseditable`,`answer`,`answeredon`,`subuserid`,`isprebid`) values (82,24,133,3,'<p>Section 10, Key Evaluation Criteria, Point no 4</p>\r\n<p>Page no. 8</p>','<p>Prior exposure to implementing government projects in Bid&nbsp;<br>Management and Exit Management</p>','<p>As the scope of work consists of experience related to review/assessment/bid management/cyber security/GRC, therefore, request you to kindly modify this clause as below:<br>Prior exposure to cyber security review/assessment/audit/GRC/Bid Management and Exit Management in government projects</p>','2026-03-24 23:11:22',1,'<p>As per EOI.</p>','2026-03-27 16:37:08',NULL,1);
insert  into `eoi_request_prebid_query`(`questionid`,`queryid`,`requestid`,`vendorid`,`clause_reference`,`clause_detail`,`queries_with_justification`,`creationdate`,`iseditable`,`answer`,`answeredon`,`subuserid`,`isprebid`) values (83,25,127,4,'<p>Factsheet, Page 4</p>','<p>Last date (deadline) for&nbsp;<br>submission of proposals&nbsp;<br>06/03/2026, 05:00 PM&nbsp;</p>','<p>The email sent to us for inviting&nbsp;<br>proposals for the EoI&nbsp;<br>mentioned last date of&nbsp;<br>submission as on 06/04/2026,&nbsp;<br>however, the factsheet of the&nbsp;<br>EOI mentions 06/03/2026. We&nbsp;<br>request you to kindly provide&nbsp;<br>clarity on the last date of&nbsp;<br>submission of proposals for this&nbsp;<br>EOI. &nbsp;</p>','2026-03-26 21:18:03',1,'<p>Revised last date for submission of proposals: 08/04/2026 (Wednesday).</p>','2026-04-03 10:32:39',NULL,1);
insert  into `eoi_request_prebid_query`(`questionid`,`queryid`,`requestid`,`vendorid`,`clause_reference`,`clause_detail`,`queries_with_justification`,`creationdate`,`iseditable`,`answer`,`answeredon`,`subuserid`,`isprebid`) values (84,25,127,4,'<p>&nbsp;Factsheet, Page 4&nbsp;</p>','<p>Last date (deadline) for&nbsp;<br>submission of proposals&nbsp;</p>','<p>Given the extensive team&nbsp;<br>requirements outlined in the&nbsp;<br>EoI, we expect significant&nbsp;<br>efforts to identify and screen&nbsp;<br>most suitable candidates to&nbsp;<br>enable us to put forward a&nbsp;<br>strong team. We strongly&nbsp;<br>request you to consider an&nbsp;<br>extension of minimum 10 days&nbsp;<br>i.e till 16/04/2026 to ensure we&nbsp;<br>put forward best set of CVs and&nbsp;<br>fully compliant proposal.&nbsp;</p>','2026-03-26 21:19:58',1,'<p>Revised last date for submission of proposals: 08/04/2026 (Wednesday).</p>','2026-04-03 10:32:39',NULL,1);
insert  into `eoi_request_prebid_query`(`questionid`,`queryid`,`requestid`,`vendorid`,`clause_reference`,`clause_detail`,`queries_with_justification`,`creationdate`,`iseditable`,`answer`,`answeredon`,`subuserid`,`isprebid`) values (85,25,127,4,'<p>&nbsp;Section 4-Team&nbsp;<br>Requirements, Pages&nbsp;<br>9-11&nbsp;</p>','<p>Varied person month&nbsp;<br>requirements (6, 12, 24 months&nbsp;<br>etc.)&nbsp;</p>','<p>Please clarify whether all 19&nbsp;<br>resources are expected to be&nbsp;<br>deployed concurrently from&nbsp;<br>Day 1, or whether deployment&nbsp;<br>may be phased based on the&nbsp;<br>project requirements.&nbsp;</p>','2026-03-26 21:20:47',1,'<p>As per EoI.</p>','2026-04-03 10:32:39',NULL,1);
insert  into `eoi_request_prebid_query`(`questionid`,`queryid`,`requestid`,`vendorid`,`clause_reference`,`clause_detail`,`queries_with_justification`,`creationdate`,`iseditable`,`answer`,`answeredon`,`subuserid`,`isprebid`) values (86,25,127,4,'<p>Section 4-Team&nbsp;<br>Requirements-Project&nbsp;<br>Director, Page 9</p>','<p>Should be having a leadership&nbsp;<br>position like Partner/CEO/MD&nbsp;<br>of the organization</p>','<p>We seek an extension of the&nbsp;<br>requirement for the said&nbsp;<br>position with consideration of&nbsp;<br>similar &amp; equivalent&nbsp;<br>designations like Director/&nbsp;<br>Associate Director/COO/ GM&nbsp;<br>or equivalent Senior&nbsp;<br>Management role, to ensure&nbsp;<br>larger fitment and alignment&nbsp;<br>with the project objectives.&nbsp;</p>','2026-03-26 21:21:30',1,'<p>As per EoI.</p>','2026-04-03 10:32:39',NULL,1);
insert  into `eoi_request_prebid_query`(`questionid`,`queryid`,`requestid`,`vendorid`,`clause_reference`,`clause_detail`,`queries_with_justification`,`creationdate`,`iseditable`,`answer`,`answeredon`,`subuserid`,`isprebid`) values (87,25,127,4,'<p>Section 4-Team&nbsp;<br>Requirements-Team&nbsp;<br>Leader, Page 9</p>','<p>Experience of leading and&nbsp;<br>managing 2 projects in different&nbsp;<br>departments of government of&nbsp;<br>Chhattisgarh which involve&nbsp;<br>Project/policy formulation,&nbsp;<br>engagement with multiple&nbsp;<br>government/private&nbsp;<br>stakeholders, implementation&nbsp;<br>and monitoring or program.</p>','<p>We seek an extension of the&nbsp;<br>requirement for the said&nbsp;<br>position with consideration of&nbsp;<br>similar &amp; equivalent experience&nbsp;<br>across the Central or any State&nbsp;<br>government in India, to ensure&nbsp;<br>larger fitment and alignment&nbsp;<br>with the project objectives.&nbsp;</p>','2026-03-26 21:22:18',1,'<p>As per EoI.</p>','2026-04-03 10:32:39',NULL,1);
insert  into `eoi_request_prebid_query`(`questionid`,`queryid`,`requestid`,`vendorid`,`clause_reference`,`clause_detail`,`queries_with_justification`,`creationdate`,`iseditable`,`answer`,`answeredon`,`subuserid`,`isprebid`) values (88,25,127,4,'<p>&nbsp;Section 5-Duration and&nbsp;<br>Resource Deployment&nbsp;<br>Plan, Page 12&nbsp;</p>','<p>The working location of the&nbsp;<br>deployed resources will be&nbsp;<br>decided by the Department&nbsp;</p>','<p>We understand the PMU will be&nbsp;<br>based out of Raipur city. Please&nbsp;<br>clarify if there&rsquo;s any deployment&nbsp;<br>required at any&nbsp;<br>district/divisional level or only&nbsp;<br>field visits will be required. &nbsp;</p>','2026-03-26 21:23:00',1,'<p>As per EoI.</p>','2026-04-03 10:32:39',NULL,1);
insert  into `eoi_request_prebid_query`(`questionid`,`queryid`,`requestid`,`vendorid`,`clause_reference`,`clause_detail`,`queries_with_justification`,`creationdate`,`iseditable`,`answer`,`answeredon`,`subuserid`,`isprebid`) values (89,25,127,4,'<p>&nbsp;Section 5-Duration and&nbsp;<br>Resource Deployment&nbsp;<br>Plan, Page 12&nbsp;</p>','<p>The working location of the&nbsp;<br>deployed resources will be&nbsp;<br>decided by the Department.&nbsp;</p>','<p>We understand the position of&nbsp;<br>&ldquo;Project Director&rdquo; signifies a&nbsp;<br>Subject Matter expert role to&nbsp;<br>guide the team and drive the&nbsp;<br>project. We understand the&nbsp;<br>required 6 person-months will&nbsp;<br>be spread across 24 months&nbsp;<br>with part-time/intermittent&nbsp;<br>onsite availability. Kindly&nbsp;<br>confirm the requirement of the&nbsp;<br>deployment.&nbsp;</p>','2026-03-26 21:23:44',1,'<p>As per EoI.</p>','2026-04-03 10:32:39',NULL,1);
insert  into `eoi_request_prebid_query`(`questionid`,`queryid`,`requestid`,`vendorid`,`clause_reference`,`clause_detail`,`queries_with_justification`,`creationdate`,`iseditable`,`answer`,`answeredon`,`subuserid`,`isprebid`) values (90,25,127,4,'<p>Section 7-Evaluation&nbsp;<br>Process, Page 12</p>','<p>During the presentation by the&nbsp;<br>companies, the Evaluation&nbsp;<br>Committee will interview the&nbsp;<br>proposed candidates&nbsp;<br>(Physically/Via Video&nbsp;<br>Conference).&nbsp;</p>','<p>Kindly confirm whether all 19&nbsp;<br>resources need to undergo&nbsp;<br>interviews, or only key/lead&nbsp;<br>positions (Project Director,&nbsp;<br>Team Leader, Advisors, Senior&nbsp;<br>Consultants). &nbsp;</p>','2026-03-26 21:24:24',1,'<p>Interview for all 19 resources.</p>','2026-04-03 10:32:39',NULL,1);
insert  into `eoi_request_prebid_query`(`questionid`,`queryid`,`requestid`,`vendorid`,`clause_reference`,`clause_detail`,`queries_with_justification`,`creationdate`,`iseditable`,`answer`,`answeredon`,`subuserid`,`isprebid`) values (91,25,127,4,'<p>Section 7-Key&nbsp;<br>Evaluation Criteria,&nbsp;<br>Page 13</p>','<p>Prior exposure to implementing&nbsp;<br>government projects in Bid&nbsp;<br>Management and Exit&nbsp;<br>Management</p>','<p>Considering the scope of work&nbsp;<br>and required expertise, the&nbsp;<br>current evaluation criteria only&nbsp;<br>focuses on the Bid&nbsp;<br>Documentation &amp; Management&nbsp;<br>and doesn&rsquo;t cover other critical&nbsp;<br>components of the scope.</p>\r\n<p>The evaluation criteria must&nbsp;<br>consider the following&nbsp;<br>experience:&nbsp;<br>1) Ayushman Bharat as&nbsp;<br>significant component&nbsp;<br>under this project and&nbsp;<br>hence we request you&nbsp;<br>to kindly consider&nbsp;<br>addition of &ldquo;Experience&nbsp;<br>of implementing AB<br>PMJAY projects across&nbsp;<br>India&rdquo;.&nbsp;<br>2) PPP experience in&nbsp;<br>healthcare sector must&nbsp;<br>be considered&nbsp;<br>3) Healthcare&nbsp;<br>Infrastructure&nbsp;<br>development&nbsp;<br>(Hospitals, medical&nbsp;<br>colleges, etc.) must be&nbsp;<br>considered.&nbsp;</p>','2026-03-26 21:25:42',1,'<p>As per EoI.</p>','2026-04-03 10:32:39',NULL,1);
insert  into `eoi_request_prebid_query`(`questionid`,`queryid`,`requestid`,`vendorid`,`clause_reference`,`clause_detail`,`queries_with_justification`,`creationdate`,`iseditable`,`answer`,`answeredon`,`subuserid`,`isprebid`) values (92,25,127,4,'<p>&nbsp;Section 9-Documents&nbsp;<br>Required, Page 13&nbsp;</p>','<p>Resumes of resources that will&nbsp;<br>face the interview. The format&nbsp;<br>of resumes will be as per the&nbsp;<br>annexed format.</p>','<p>The annexed CV format is not&nbsp;<br>attached to the EOI. Kindly&nbsp;<br>provide the prescribed CV&nbsp;<br>format as mentioned in the&nbsp;<br>Section-9.&nbsp;</p>','2026-03-26 21:26:26',1,'<p>CV Format attached.</p>','2026-04-03 10:32:39',NULL,1);
insert  into `eoi_request_prebid_query`(`questionid`,`queryid`,`requestid`,`vendorid`,`clause_reference`,`clause_detail`,`queries_with_justification`,`creationdate`,`iseditable`,`answer`,`answeredon`,`subuserid`,`isprebid`) values (93,25,127,4,'<p>Section 5-Duration and&nbsp;<br>Resource Deployment&nbsp;<br>Plan, Page 12&nbsp;</p>','<p>24 Months contract</p>','<p>We understand the contract&nbsp;<br>would be for 24 months. Kindly&nbsp;<br>give us clarity if the work order&nbsp;<br>will be released for 24 months&nbsp;<br>or two separate work orders&nbsp;<br>after duration of 12 months.</p>','2026-03-26 21:50:52',1,'<p>To be informed later.</p>','2026-04-03 10:32:39',NULL,1);
insert  into `eoi_request_prebid_query`(`questionid`,`queryid`,`requestid`,`vendorid`,`clause_reference`,`clause_detail`,`queries_with_justification`,`creationdate`,`iseditable`,`answer`,`answeredon`,`subuserid`,`isprebid`) values (94,26,131,1,'<p>Clause: 3.6<br>Page: 4</p>','<p>The PMU will coordinate with the existing SI on system integrations, API integrations with nodal agencies (state/central), performance optimization, security protocols and access control requirements, and support interoperability and MIS-AMP integration for seamless data flow.</p>','<p>The EoI mentions coordination with the System Integrator for API integrations with nodal agencies and departmental MIS systems. Reqeust to kindly provide an indicative list of the major departmental systems proposed to be integrated with AMP and please clarify whether these integrations already exist or are expected to be developed during Phase-II.</p>','2026-03-27 14:45:12',1,'<p><span data-sheets-root=\"1\">The PMU needs to indetify schemes (central/state) which are yet to be onboarded on AMP and work to get required API from them. Post which the same needs to be shared with SI for integration with AMP.</span></p>','2026-04-07 20:11:42',NULL,1);
insert  into `eoi_request_prebid_query`(`questionid`,`queryid`,`requestid`,`vendorid`,`clause_reference`,`clause_detail`,`queries_with_justification`,`creationdate`,`iseditable`,`answer`,`answeredon`,`subuserid`,`isprebid`) values (95,26,131,1,'<p>Clause: 3.12<br>Page: 5</p>','<p>The PMU will conduct Unit, System and UAT testing of any new developed components/changes and submit reports accordingly; validate work milestone completion and recommend payments including for change requests issued to the SI and O&amp;M&nbsp;activities.</p>','<p>The EoI mentions that the PMU will validate work milestone completion and recommend payments for change requests issued to the System Integrator. We understand that the PMU&rsquo;s role will be limited to reviewing the deliverables against approved scope and providing recommendations on the basis of objective parameters, while the final approval for milestone acceptance and payment release will rest with the competent authority of Department of Good Governance and Convergence. Kindly clarify.</p>','2026-03-27 14:45:59',1,'<p><span data-sheets-root=\"1\">As per EoI.<br><br>The final acceptance and releasing of the payment will be done by GG&amp;C. However, PMU to review and recommend based on the objective of the work, SOW, Milestone deliverable and milestone payment.</span></p>','2026-04-07 20:11:53',NULL,1);
insert  into `eoi_request_prebid_query`(`questionid`,`queryid`,`requestid`,`vendorid`,`clause_reference`,`clause_detail`,`queries_with_justification`,`creationdate`,`iseditable`,`answer`,`answeredon`,`subuserid`,`isprebid`) values (96,26,131,1,'<p>Clause: 3.13<br>Page: 5</p>','<p>The PMU will coordinate and review the work given District governance data expert, validate their MPR&rsquo;s, invoices and put up with recommendation.</p>','<p>The EoI states that the PMU will coordinate and review the work undertaken by District Governance Data Experts and validate their MPRs and invoices with recommendations. It is understood that the PMU&rsquo;s role in this regard will be based on professional assessment and advisory inputs. Kindly confirm that the PMU&rsquo;s review and recommendations will be considered as objective in nature against pre-defined parameters, and the final decision regarding acceptance, approval, or any administrative action shall rest with the competent authority of the Department of Good Governance and Convergence. Kindly clarify.</p>','2026-03-27 14:47:45',1,'<p><span data-sheets-root=\"1\">As per EoI.<br><br>The final acceptance and releasing of the payment will be done by GG&amp;C. However, PMU to review and recommend based on the objective of the work, SOW, Milestone deliverable and milestone payment.</span></p>','2026-04-07 20:12:04',NULL,1);
insert  into `eoi_request_prebid_query`(`questionid`,`queryid`,`requestid`,`vendorid`,`clause_reference`,`clause_detail`,`queries_with_justification`,`creationdate`,`iseditable`,`answer`,`answeredon`,`subuserid`,`isprebid`) values (97,26,131,1,'<p>Clause: 3.8<br>Page: 5</p>','<p>The PMU will drive State-wide adoption of AMP by conducting structured trainings, demonstrations and capacity building programs, and provide ongoing user support and handholding to Departments and Districts for operational usage.</p>','<p>We understand that &nbsp;such trainings / capacity building programmes would be in \'train the trainer\' mode and we will not be requried to issue any certificate for such trainings. Kindly clarify.</p>','2026-03-27 14:48:49',1,'<p><span data-sheets-root=\"1\">As per EoI.<br><br>No certificate to be issued. Trainings and/or handholding and/or support is being done for users (secy, collector, department nodals, district nodals). In case te users face any challenges</span></p>','2026-04-07 20:12:15',NULL,1);
insert  into `eoi_request_prebid_query`(`questionid`,`queryid`,`requestid`,`vendorid`,`clause_reference`,`clause_detail`,`queries_with_justification`,`creationdate`,`iseditable`,`answer`,`answeredon`,`subuserid`,`isprebid`) values (98,26,131,1,'<p>Clause: 5.5<br>Page: 7</p>','<p>Minimum 2 years of relevant exposure on&nbsp;hands-on understanding of data analysis tools,&nbsp;dashboard development, data validation&nbsp;processes.</p>','<p>The EoI specifies that resources should have hands-on exposure to data analysis tools, dashboard development, and data validation processes. It is understood that any specific software tools or platforms required for data validation, data cleaning, or analytical processing within the AMP ecosystem will be made available by the client/authority. Kindly confirm the same.</p>','2026-03-27 14:49:29',1,'<p><span data-sheets-root=\"1\">Yes. In case if it required. However, in such situations PMU to also suggest which tool may be best suitable for the purpose.</span></p>','2026-04-07 20:12:27',NULL,1);
insert  into `eoi_request_prebid_query`(`questionid`,`queryid`,`requestid`,`vendorid`,`clause_reference`,`clause_detail`,`queries_with_justification`,`creationdate`,`iseditable`,`answer`,`answeredon`,`subuserid`,`isprebid`) values (99,27,131,4,'<p>5. Roles and Responsibility of Team Members (Page No 5,6)</p>','<p>Educational Qualification for<br>1. &nbsp;Team Lead (Managing Consultant)&nbsp;<br>2. Governance&nbsp;Reforms Specialist (Senior Consultant)<br>3. Monitoring Specialist (Senior Consultant)<br>4. Data Analyst&nbsp;(Consultant)</p>','<p>Request you to please allow resource with engineering and other bachelors degree with relevant domain experince to be evaluated for the respective positions</p>','2026-03-27 16:55:24',1,'<p><span data-sheets-root=\"1\">The EoI does states \"Any graduation\" and equivalent for Consultant position.</span></p>','2026-04-07 20:12:45',NULL,1);
insert  into `eoi_request_prebid_query`(`questionid`,`queryid`,`requestid`,`vendorid`,`clause_reference`,`clause_detail`,`queries_with_justification`,`creationdate`,`iseditable`,`answer`,`answeredon`,`subuserid`,`isprebid`) values (100,27,131,4,'<p>3. Scope of Work (page no 4)</p>','<p>The PMU will function in the following activities:</p>','<p>Request you to please add scope of monitoring the infrastructure and licenses, also the integration of various infrastructure of the various departments</p>','2026-03-27 17:01:27',1,'<p><span data-sheets-root=\"1\">As per EoI.</span></p>','2026-04-07 20:12:56',NULL,1);
insert  into `eoi_request_prebid_query`(`questionid`,`queryid`,`requestid`,`vendorid`,`clause_reference`,`clause_detail`,`queries_with_justification`,`creationdate`,`iseditable`,`answer`,`answeredon`,`subuserid`,`isprebid`) values (101,28,143,5,'<p>5.4 (Note d), 12</p>','<p>The Consultant proposed team shall be deployed within 90 days of the issuance of the Letter of Award/ Work Order.</p>','<p>Clarification is requested on the definition of deployed. Does this imply full-time physical presence in Raipur for all four consultants?</p>','2026-04-28 18:16:34',1,'<p>Yes, all 4 resources to be deployed physically for the project duration at Raipur/ Naya Raipur.</p>','2026-05-06 15:31:29',NULL,1);
insert  into `eoi_request_prebid_query`(`questionid`,`queryid`,`requestid`,`vendorid`,`clause_reference`,`clause_detail`,`queries_with_justification`,`creationdate`,`iseditable`,`answer`,`answeredon`,`subuserid`,`isprebid`) values (102,28,143,5,'<p>4.3, 7</p>','<p>Data Lab Enablement at Education Institutions: Point 5 - Develop digital platforms for data collection, labeling, and utilization</p>','<p>It is requested that the clause be refined to - Propose an approach for data collection, pre-processing, and labelling. <br>Rationale: The current PMU team composition is designed for strategic oversight. If there is a requirement for implementation, resources like AI or Data Engineers may be added later upon mutual agreement between the bidder and CHiPS.</p>','2026-04-28 18:17:01',1,'<p>Point 5 Changed as- Propose the approach and support the Development of digital platforms for data collection, labeling, and utilization</p>','2026-05-06 15:31:53',NULL,1);
insert  into `eoi_request_prebid_query`(`questionid`,`queryid`,`requestid`,`vendorid`,`clause_reference`,`clause_detail`,`queries_with_justification`,`creationdate`,`iseditable`,`answer`,`answeredon`,`subuserid`,`isprebid`) values (103,28,143,5,'<p>7.6.2, 15</p>','<p>Reimbursement - The inter-city/state conveyance charges for any official travel for Authority related work or to cover the work as per scope of RFP would be borne by the Authority subjected to prior approval.</p>','<p>It is requested to add in this clause that in the event prior approval for official travel is not accorded, the PMU shall be permitted to reschedule or modify the travel plans accordingly or work in remote coordination. The bidder shall not be liable for travel-related expenditures for tasks falling within the Authority\'s scope of work.</p>','2026-04-28 18:20:23',1,'<p>As the per the empanelment agreement conditions</p>','2026-05-06 15:32:04',NULL,1);
insert  into `eoi_request_prebid_query`(`questionid`,`queryid`,`requestid`,`vendorid`,`clause_reference`,`clause_detail`,`queries_with_justification`,`creationdate`,`iseditable`,`answer`,`answeredon`,`subuserid`,`isprebid`) values (104,28,143,5,'<p>10, 17</p>','<p>Evaluation Process - Prior experience of Consultancy/ Advisory with Central or State government in AI-led governance and innovation, Startup ecosystem development as per TOR.</p>','<p>It is requested that the evaluation criterion be amended to proven experience in providing consultancy and implementation services for Artificial Intelligence (AI) projects within Government. This will ensure a comprehensive approach for evaluating the bidders. Further, it is requested that the evaluation criteria be amended to incorporate a weighted preference for bidders possessin experience in the end-to-end implementation of Data and AI platform in direct collaboration with MeitY. Rationale: As per Clause 4.5, the PMU is mandated to act as the nodal interface with MeitY, therefore, it is submitted that a bidder with direct implementation experience at the MeitY level will possess the requisite technical depth to prepare an effective AI policy which is grounded with implementation experience.</p>','2026-04-28 18:21:19',1,'<p>As per EoI terms and conditions</p>','2026-05-06 15:32:24',NULL,1);
insert  into `eoi_request_prebid_query`(`questionid`,`queryid`,`requestid`,`vendorid`,`clause_reference`,`clause_detail`,`queries_with_justification`,`creationdate`,`iseditable`,`answer`,`answeredon`,`subuserid`,`isprebid`) values (105,28,143,5,'<p>5.2, 5.3 and 5.4, 9-11</p>','<p>5.2 Senior AI &amp; Technology Consultant - IT Sector (1 Position) &nbsp;- Advise on cybersecurity, data privacy, and ethical AI&nbsp;<br>5.3 Data &amp; Innovation Consultant - IT Sector (1 Position) - Design and implement data infrastructure and Develop datasets and data pipelines&nbsp;<br>5.4 Policy, Partnerships &amp; Coordination Consultant - IT Sector (1 Position) - Support legal, contractual, and regulatory aspects&nbsp;</p>','<p>5.2 Senior AI &amp; Technology Consultant - IT Sector (1 Position) &nbsp;- Request to edit this clause from \"Advise on cybersecurity, data privacy, and ethical AI\" to \"Advise on ethical AI\"<br>5.3 Data &amp; Innovation Consultant - IT Sector (1 Position) - Request to remove these clauses \" Design and implement data infrastructure and Develop datasets and data pipelines\"&nbsp;<br>5.4 Policy, Partnerships &amp; Coordination Consultant - IT Sector (1 Position) - Request to edit this clause from \"Support legal, contractual, and regulatory aspects \" to \"Support regulatory aspects</p>\r\n<p>These revisions are requested to align the scope of work with AI advisory and to exclude technical implementation, and broader legal responsibilities that fall outside such advisory services.</p>','2026-04-28 18:23:00',1,'<p>Point 5.3 Changed as -Propose the approach and support for Designing and implementing data infrastructure and Developing datasets and data pipelines</p>','2026-05-06 15:32:45',NULL,1);
insert  into `eoi_request_prebid_query`(`questionid`,`queryid`,`requestid`,`vendorid`,`clause_reference`,`clause_detail`,`queries_with_justification`,`creationdate`,`iseditable`,`answer`,`answeredon`,`subuserid`,`isprebid`) values (106,28,143,5,'<p>5.1, 5.2, 5.3 and 5.4, 9</p>','<p>Qualification and Experience:<br>5.1 Principal Consultant-&nbsp;<br>Minimum 12&ndash;15 years of experience<br>At least 5&ndash;7 years in managing large government/digital transformation programs<br>5.2 Senior AI and Technology Consultant-<br>8&ndash;12 years of experience in AI/technology projects<br>5.3 Data &amp; Innovation Consultant-IT Sector<br>5&ndash;8 years of experience in data analytics, innovation, or startup ecosystem<br>5.4 Policy, Partnerships &amp; Coordination Consultant - IT Sector<br>5&ndash;8 years of experience in policy, governance, or advisory roles</p>','<p>Clarification is requested as in the signed empanelment agreement between CHiPS and Deloitte,the qualification and experimence required are mentioned as:<br>5.1 Principal Consultant- 7+ years of relevant experience and minimum 2 years of experience in managing relevant project are required.<br>5.2 Senior Consultant- 5+ years of relevant experience<br>5.3 &amp; 5.4 Consultant- 3+ years of relevant experience</p>','2026-04-28 18:24:21',1,'<p>As per EoI terms and conditions.</p>','2026-05-06 15:33:04',NULL,1);
insert  into `eoi_request_prebid_query`(`questionid`,`queryid`,`requestid`,`vendorid`,`clause_reference`,`clause_detail`,`queries_with_justification`,`creationdate`,`iseditable`,`answer`,`answeredon`,`subuserid`,`isprebid`) values (107,29,143,4,'<p><span style=\"font-size: 11.0pt; line-height: 107%; font-family: \'Aptos\',sans-serif; mso-ascii-theme-font: minor-latin; mso-fareast-font-family: Aptos; mso-fareast-theme-font: minor-latin; mso-hansi-theme-font: minor-latin; mso-bidi-font-family: Mangal; mso-bidi-theme-font: minor-bidi; color: #0e2841; mso-themecolor: text2; mso-ansi-language: EN-US; mso-fareast-language: EN-US; mso-bidi-language: AR-SA;\">Clause 4.2 &ndash; Centre of Excellence in AI</span></p>','<p><span style=\"font-size: 11.0pt; line-height: 107%; font-family: \'Aptos\',sans-serif; mso-ascii-theme-font: minor-latin; mso-fareast-font-family: Aptos; mso-fareast-theme-font: minor-latin; mso-hansi-theme-font: minor-latin; mso-bidi-font-family: Mangal; mso-bidi-theme-font: minor-bidi; color: #0e2841; mso-themecolor: text2; mso-ansi-language: EN-US; mso-fareast-language: EN-US; mso-bidi-language: AR-SA;\">Support conceptualization and operationalization of CoE</span></p>','<p><span style=\"font-size: 11.0pt; line-height: 107%; font-family: \'Aptos\',sans-serif; mso-ascii-theme-font: minor-latin; mso-fareast-font-family: Aptos; mso-fareast-theme-font: minor-latin; mso-hansi-theme-font: minor-latin; mso-bidi-font-family: Mangal; mso-bidi-theme-font: minor-bidi; color: #0e2841; mso-themecolor: text2; mso-ansi-language: EN-US; mso-fareast-language: EN-US; mso-bidi-language: AR-SA;\">Kindly clarify whether the PMU is required to support procurement of hardware/software or implementation agencies, or whether its role is limited to support the planning, advisory support, and partner identification activities.</span></p>','2026-04-29 16:25:10',1,'<p>PMU will provide the support as per the scope of work mentioned in EoI</p>','2026-05-06 15:36:38',NULL,1);
insert  into `eoi_request_prebid_query`(`questionid`,`queryid`,`requestid`,`vendorid`,`clause_reference`,`clause_detail`,`queries_with_justification`,`creationdate`,`iseditable`,`answer`,`answeredon`,`subuserid`,`isprebid`) values (108,29,143,4,'<p><span style=\"font-size: 11.0pt; line-height: 107%; font-family: \'Aptos\',sans-serif; mso-ascii-theme-font: minor-latin; mso-fareast-font-family: Aptos; mso-fareast-theme-font: minor-latin; mso-hansi-theme-font: minor-latin; mso-bidi-font-family: Mangal; mso-bidi-theme-font: minor-bidi; color: #0e2841; mso-themecolor: text2; mso-ansi-language: EN-US; mso-fareast-language: EN-US; mso-bidi-language: AR-SA;\">Clause 4.2 &ndash; Onboarding Partners</span></p>','<p><span style=\"font-size: 11.0pt; line-height: 107%; font-family: \'Aptos\',sans-serif; mso-ascii-theme-font: minor-latin; mso-fareast-font-family: Aptos; mso-fareast-theme-font: minor-latin; mso-hansi-theme-font: minor-latin; mso-bidi-font-family: Mangal; mso-bidi-theme-font: minor-bidi; color: #0e2841; mso-themecolor: text2; mso-ansi-language: EN-US; mso-fareast-language: EN-US; mso-bidi-language: AR-SA;\">Identify and onboard technology partners, academia, research bodies</span></p>','<p><span style=\"font-size: 11.0pt; line-height: 107%; font-family: \'Aptos\',sans-serif; mso-ascii-theme-font: minor-latin; mso-fareast-font-family: Aptos; mso-fareast-theme-font: minor-latin; mso-hansi-theme-font: minor-latin; mso-bidi-font-family: Mangal; mso-bidi-theme-font: minor-bidi; color: #0e2841; mso-themecolor: text2; mso-ansi-language: EN-US; mso-fareast-language: EN-US; mso-bidi-language: AR-SA;\">Please clarify whether partner onboarding will follow a separate procurement/selection process by CHiPS, and whether PMU responsibility to also support the bid process if required.</span></p>','2026-04-29 16:25:57',1,'<p class=\"p1\">Changed as- Identify and support onboarding of<span class=\"Apple-converted-space\">&nbsp; </span>technology partners, academic institutions, and research bodies</p>','2026-05-06 15:38:10',NULL,1);
insert  into `eoi_request_prebid_query`(`questionid`,`queryid`,`requestid`,`vendorid`,`clause_reference`,`clause_detail`,`queries_with_justification`,`creationdate`,`iseditable`,`answer`,`answeredon`,`subuserid`,`isprebid`) values (109,29,143,4,'<p><span style=\"font-size: 11.0pt; line-height: 107%; font-family: \'Aptos\',sans-serif; mso-ascii-theme-font: minor-latin; mso-fareast-font-family: Aptos; mso-fareast-theme-font: minor-latin; mso-hansi-theme-font: minor-latin; mso-bidi-font-family: Mangal; mso-bidi-theme-font: minor-bidi; color: #0e2841; mso-themecolor: text2; mso-ansi-language: EN-US; mso-fareast-language: EN-US; mso-bidi-language: AR-SA;\">Clause 4.3 &ndash; Data Lab Enablement</span></p>','<p><span style=\"font-size: 11.0pt; line-height: 107%; font-family: \'Aptos\',sans-serif; mso-ascii-theme-font: minor-latin; mso-fareast-font-family: Aptos; mso-fareast-theme-font: minor-latin; mso-hansi-theme-font: minor-latin; mso-bidi-font-family: Mangal; mso-bidi-theme-font: minor-bidi; color: #0e2841; mso-themecolor: text2; mso-ansi-language: EN-US; mso-fareast-language: EN-US; mso-bidi-language: AR-SA;\">Design data infrastructure and AI labs</span></p>','<p><span style=\"font-size: 11.0pt; line-height: 107%; font-family: \'Aptos\',sans-serif; mso-ascii-theme-font: minor-latin; mso-fareast-font-family: Aptos; mso-fareast-theme-font: minor-latin; mso-hansi-theme-font: minor-latin; mso-bidi-font-family: Mangal; mso-bidi-theme-font: minor-bidi; color: #0e2841; mso-themecolor: text2; mso-ansi-language: EN-US; mso-fareast-language: EN-US; mso-bidi-language: AR-SA;\">Kindly confirm whether PMU is expected only to provide design standards, specifications, bid process and implementation monitoring support.</span></p>','2026-04-29 16:34:45',1,'<p>Yes</p>','2026-05-06 15:39:47',NULL,1);
insert  into `eoi_request_prebid_query`(`questionid`,`queryid`,`requestid`,`vendorid`,`clause_reference`,`clause_detail`,`queries_with_justification`,`creationdate`,`iseditable`,`answer`,`answeredon`,`subuserid`,`isprebid`) values (110,29,143,4,'<p><span style=\"font-size: 11.0pt; line-height: 107%; font-family: \'Aptos\',sans-serif; mso-ascii-theme-font: minor-latin; mso-fareast-font-family: Aptos; mso-fareast-theme-font: minor-latin; mso-hansi-theme-font: minor-latin; mso-bidi-font-family: Mangal; mso-bidi-theme-font: minor-bidi; color: #0e2841; mso-themecolor: text2; mso-ansi-language: EN-US; mso-fareast-language: EN-US; mso-bidi-language: AR-SA;\">Clause 4.4 &ndash; Startup Incubation</span></p>','<p><span style=\"font-size: 11.0pt; line-height: 107%; font-family: \'Aptos\',sans-serif; mso-ascii-theme-font: minor-latin; mso-fareast-font-family: Aptos; mso-fareast-theme-font: minor-latin; mso-hansi-theme-font: minor-latin; mso-bidi-font-family: Mangal; mso-bidi-theme-font: minor-bidi; color: #0e2841; mso-themecolor: text2; mso-ansi-language: EN-US; mso-fareast-language: EN-US; mso-bidi-language: AR-SA;\">Facilitate access to compute, datasets, mentors</span></p>','<p><span style=\"font-size: 11.0pt; line-height: 107%; font-family: \'Aptos\',sans-serif; mso-ascii-theme-font: minor-latin; mso-fareast-font-family: Aptos; mso-fareast-theme-font: minor-latin; mso-hansi-theme-font: minor-latin; mso-bidi-font-family: Mangal; mso-bidi-theme-font: minor-bidi; color: #0e2841; mso-themecolor: text2; mso-ansi-language: EN-US; mso-fareast-language: EN-US; mso-bidi-language: AR-SA;\">Kindly confirm whether PMU is expected only to provide design standards, specifications, bid process and implementation monitoring support.</span></p>','2026-04-29 16:35:17',1,'<p>Yes</p>','2026-05-06 15:40:05',NULL,1);
insert  into `eoi_request_prebid_query`(`questionid`,`queryid`,`requestid`,`vendorid`,`clause_reference`,`clause_detail`,`queries_with_justification`,`creationdate`,`iseditable`,`answer`,`answeredon`,`subuserid`,`isprebid`) values (111,29,143,4,'<p>clause 5.1, 5.2,5.3,5.4</p>','<p>Profile and Desired of following Consultants&nbsp;<br>1. &nbsp; &nbsp;Principal Consultant - IT Sector (Team Lead)<br>2. &nbsp; &nbsp;Senior AI &amp; Technology Consultant - IT Sector (1 Position)<br>3. &nbsp; &nbsp;Data &amp; Innovation Consultant - IT Sector<br>4. &nbsp; &nbsp;Policy, Partnerships &amp; Coordination Consultant - IT Sector</p>','<p>M/s KPMG Advisory Services Pvt Ltd.<br>Queries with justification<br>Kindly clarify whether the PMU is required to support procurement of hardware/software or implementation agencies, or whether its role is limited to support the planning, advisory support, and partner identification activities.<br>Please clarify whether partner onboarding will follow a separate procurement/selection process by CHiPS, and whether PMU responsibility to also support the bid process if required.<br>Kindly confirm whether PMU is expected only to provide design standards, specifications, bid process and implementation monitoring support.<br>Kindly confirm whether PMU is expected only to provide design standards, specifications, bid process and implementation monitoring support.<br>A. Clarification on AI Experience Requirements&nbsp;<br>Artificial Intelligence is a relatively new and rapidly evolving domain, with large scale enterprise and government adoption largely occurring over the last 5&ndash;7 years. In this context, experience requirements of 12&ndash;15 years, especially including 5&ndash;7 years of government program management, may not fully align with current AI talent market realities and could unintentionally restrict access to high quality AI professionals.<br>It is observed that AI expertise in the market spans multiple categories, including core AI technology building, applied AI for service delivery, data and analytics, and program/policy roles with AI exposure. Deep AI capability is typically demonstrated through recent, hands on experience and successful implementations, rather than long overall tenure.<br>Clarification requested:<br>&bull; &nbsp; &nbsp;Will equivalent industry or large scale enterprise AI program experience be considered in lieu of mandatory government program management experience?<br>&bull; &nbsp; &nbsp;Can greater emphasis be placed on demonstrated AI capability, leadership in AI initiatives, and implementation outcomes, rather than total years of experience alone?<br>B. Request for Revision of Role Titles<br>To better reflect the nature of responsibilities, seniority, and CHiPS empanelment experience requirements, the following revisions to role titles are requested:<br>&bull; &nbsp; &nbsp;Clause 5.1<br>Revise: &nbsp;Principal Consultant &ndash; IT Sector (Team Lead) to Management Consultant &ndash; IT Sector (Team Lead)<br>&bull; &nbsp; &nbsp;Clause 5.2<br>Senior AI &amp; Technology Consultant &ndash; IT Sector<br>(Retained as is)<br>&bull; &nbsp; &nbsp;Clause 5.3<br>Revise<br>Data &amp; Innovation Consultant &ndash; IT Sector<br>to Data &amp; Innovation Senior Consultant &ndash; IT Sector<br>&bull; &nbsp; &nbsp;Clause 5.4<br>Revise<br>Policy, Partnerships &amp; Coordination Consultant &ndash; IT Sector to Policy, Partnerships &amp; Coordination Senior Consultant &ndash; IT Sector</p>','2026-04-29 16:37:08',1,'<p class=\"p1\">PMU will provide the support as per the scope of work mentioned in EoI.</p>\r\n<p class=\"p1\">PMU resources will be supporting CHIPS/ Nodal Agancy in drafting and evaluating<span class=\"Apple-converted-space\">&nbsp; </span>RFP/EoI etc.&nbsp;</p>','2026-05-06 15:41:11',NULL,1);
insert  into `eoi_request_prebid_query`(`questionid`,`queryid`,`requestid`,`vendorid`,`clause_reference`,`clause_detail`,`queries_with_justification`,`creationdate`,`iseditable`,`answer`,`answeredon`,`subuserid`,`isprebid`) values (112,29,143,4,'<p><span style=\"font-size: 11.0pt; line-height: 107%; font-family: \'Aptos\',sans-serif; mso-ascii-theme-font: minor-latin; mso-fareast-font-family: Aptos; mso-fareast-theme-font: minor-latin; mso-hansi-theme-font: minor-latin; mso-bidi-font-family: Mangal; mso-bidi-theme-font: minor-bidi; color: #0e2841; mso-themecolor: text2; mso-ansi-language: EN-US; mso-fareast-language: EN-US; mso-bidi-language: AR-SA;\">Section 7.3.3 &ndash; Performance Evaluation</span></p>','<p>Evaluations will be based on predefined key performance indicators (KPIs) and deliverables.&nbsp;<br>Continuous performance below expectations may lead to termination of the contract.&nbsp;</p>','<p>Kindly predefined key performance indicators (KPIs) and deliverables.</p>\r\n<p>Kindly clarify whether termination will be resource specific or can result in termination of the entire contract with the firm.</p>','2026-04-29 16:37:39',1,'<p class=\"p1\">As per the EoI terms and conditions</p>','2026-05-06 15:41:43',NULL,1);
insert  into `eoi_request_prebid_query`(`questionid`,`queryid`,`requestid`,`vendorid`,`clause_reference`,`clause_detail`,`queries_with_justification`,`creationdate`,`iseditable`,`answer`,`answeredon`,`subuserid`,`isprebid`) values (113,29,143,4,'<p>5.4 Detailed Roles &amp; Responsibilities</p>','<p>&bull; &nbsp; &nbsp;Support legal, contractual, and regulatory aspect&nbsp;</p>','<p>We would like to inform you that&nbsp;</p>\r\n<p>&bull; &nbsp; &nbsp;We are not permitted to provide any direct or indirect legal serivce<br>&bull; &nbsp; &nbsp;&ldquo;Notwithstanding anything to the contrary, kindly note that we do not provide any legal services directly or indirectly since we are not permitted to provide the same.&nbsp;<br>&bull; &nbsp; &nbsp;Our scope is limited to technical/commercial aspect and our services will not include provision of any legal services or legal advice. No work performed by our employees shall be construed as legal service/legal advice.&rdquo;</p>','2026-04-29 16:38:13',1,'<p class=\"p1\">As per the EoI terms and conditions</p>','2026-05-06 15:42:15',NULL,1);
insert  into `eoi_request_prebid_query`(`questionid`,`queryid`,`requestid`,`vendorid`,`clause_reference`,`clause_detail`,`queries_with_justification`,`creationdate`,`iseditable`,`answer`,`answeredon`,`subuserid`,`isprebid`) values (114,29,143,4,'<p>4.3&nbsp;Data Lab Enablement at Education Institutions</p>','<p>&bull; &nbsp; &nbsp;Develop curriculum for AI/data-related training programs&nbsp;</p>','<p>Consulting firm can support the design of the curriculum including pathways for beginner/intermediate/advance courses. However, content development is to be done by the content providers.&nbsp;</p>','2026-04-29 16:38:52',1,'<p>Yes</p>','2026-05-06 15:43:04',NULL,1);
insert  into `eoi_request_prebid_query`(`questionid`,`queryid`,`requestid`,`vendorid`,`clause_reference`,`clause_detail`,`queries_with_justification`,`creationdate`,`iseditable`,`answer`,`answeredon`,`subuserid`,`isprebid`) values (115,29,143,4,'<p>4.3&nbsp;Data Lab Enablement at Education Institutions</p>','<p>Facilitate partnerships with industry for internships and placements&nbsp;</p>','<p>PMU can work towards developing relationships with industry for internships and placements. However, there are specialized firms that provide placement support.&nbsp;<br>Please specify the role of PMU in placement support and internship program.&nbsp;</p>','2026-04-29 16:39:27',1,'<p class=\"p1\">EoI clause in this regard is clear</p>','2026-05-06 15:43:30',NULL,1);
insert  into `eoi_request_prebid_query`(`questionid`,`queryid`,`requestid`,`vendorid`,`clause_reference`,`clause_detail`,`queries_with_justification`,`creationdate`,`iseditable`,`answer`,`answeredon`,`subuserid`,`isprebid`) values (116,29,143,4,'<p>4.3&nbsp;Data Lab Enablement at Education Institutions</p>','<p>&bull; &nbsp; &nbsp; Develop digital platforms for data collection, labeling, and utilization&nbsp;</p>','<p>Work of designing digital data platform including data pipelines and infrastructure is intensive. We believe that scope for Data and Innovation Consultant is huge and designing such a platform will require additional manpower.&nbsp;</p>','2026-04-29 16:40:17',1,'<p class=\"p1\">Changed as- Propose the approach and support the Development of digital platforms for data collection, labeling, and utilization</p>','2026-05-06 15:44:09',NULL,1);
insert  into `eoi_request_prebid_query`(`questionid`,`queryid`,`requestid`,`vendorid`,`clause_reference`,`clause_detail`,`queries_with_justification`,`creationdate`,`iseditable`,`answer`,`answeredon`,`subuserid`,`isprebid`) values (117,29,143,4,'<p>5.2 Senior AI &amp; Technology Consultant - IT Sector (1 Position)</p>','<p>&bull; &nbsp; &nbsp;Advise on cybersecurity, data privacy, and ethical AI</p>','<p>Cyber security is a specialized domain which differs from AI and IT Consultant. Considering the project would require huge amount of data transfer and storage and the recent publication of DPDP rules, we request to consider the specialized position of Cyber Security Expert for limited time.&nbsp;</p>','2026-04-29 16:40:52',1,'<p class=\"p1\">As per the EoI terms and conditions</p>','2026-05-06 15:44:47',NULL,1);
insert  into `eoi_request_prebid_query`(`questionid`,`queryid`,`requestid`,`vendorid`,`clause_reference`,`clause_detail`,`queries_with_justification`,`creationdate`,`iseditable`,`answer`,`answeredon`,`subuserid`,`isprebid`) values (118,29,143,4,'<p>5.3&nbsp;Data &amp; Innovation Consultant - IT Sector (1 Position)</p>','<p>&bull; &nbsp; &nbsp;Detailed Roles &amp; Responsibilities</p>','<p>Role description of Data &amp; Innovation Consultant is a mix of data architect and start up incubation expert. Request to break up the role into two different profiles.&nbsp;</p>','2026-04-29 16:41:23',1,'<p class=\"p1\">As per the EoI terms and conditions</p>','2026-05-06 15:45:09',NULL,1);
insert  into `eoi_request_prebid_query`(`questionid`,`queryid`,`requestid`,`vendorid`,`clause_reference`,`clause_detail`,`queries_with_justification`,`creationdate`,`iseditable`,`answer`,`answeredon`,`subuserid`,`isprebid`) values (119,29,143,4,'<p><span style=\"font-size: 11.0pt; line-height: 107%; font-family: \'Aptos\',sans-serif; mso-ascii-theme-font: minor-latin; mso-fareast-font-family: Aptos; mso-fareast-theme-font: minor-latin; mso-hansi-theme-font: minor-latin; mso-bidi-font-family: Mangal; mso-bidi-theme-font: minor-bidi; color: #0e2841; mso-themecolor: text2; mso-ansi-language: EN-US; mso-fareast-language: EN-US; mso-bidi-language: AR-SA;\">4.8 Capacity Building &amp; Awareness </span></p>','<p><span style=\"font-size: 11.0pt; line-height: 107%; font-family: \'Aptos\',sans-serif; mso-ascii-theme-font: minor-latin; mso-fareast-font-family: Aptos; mso-fareast-theme-font: minor-latin; mso-hansi-theme-font: minor-latin; mso-bidi-font-family: Mangal; mso-bidi-theme-font: minor-bidi; color: #0e2841; mso-themecolor: text2; mso-ansi-language: EN-US; mso-fareast-language: EN-US; mso-bidi-language: AR-SA;\">Conduct workshops, seminars, and awareness campaigns </span></p>','<p><span style=\"font-size: 11.0pt; line-height: 107%; font-family: \'Aptos\',sans-serif; mso-ascii-theme-font: minor-latin; mso-fareast-font-family: Aptos; mso-fareast-theme-font: minor-latin; mso-hansi-theme-font: minor-latin; mso-bidi-font-family: Mangal; mso-bidi-theme-font: minor-bidi; color: #0e2841; mso-themecolor: text2; mso-ansi-language: EN-US; mso-fareast-language: EN-US; mso-bidi-language: AR-SA;\">We understand that the envisaged Scope is limited to conceptualizing the workshops, seminars and awareness campaigns and there would be a separate Agency to conduct the same. Kindly confirm in case of any deviation in understanding.</span></p>','2026-04-29 16:41:46',1,'<p class=\"p1\">The number training program will be decided at a later stage, however the responsibilities of conducting such program is not in scope of consultants<span class=\"Apple-converted-space\">&nbsp; </span>only manpower deployed will be engaged for such programs</p>','2026-05-06 15:45:39',NULL,1);
insert  into `eoi_request_prebid_query`(`questionid`,`queryid`,`requestid`,`vendorid`,`clause_reference`,`clause_detail`,`queries_with_justification`,`creationdate`,`iseditable`,`answer`,`answeredon`,`subuserid`,`isprebid`) values (120,29,143,4,'<p>4.3 Data Lab Enablement at Education Institutions</p>','<p>&bull; &nbsp; &nbsp;Develop digital platforms for data collection, labeling, and utilization</p>','<p>We understand that the PMU would only develop data collection labelling and utilization framework and not develop any software for undertaking the same. Kindly confirm in case of any deviation in understanding.</p>','2026-04-29 16:42:21',1,'<p class=\"p1\">Changed as- Propose the approach and support the Development of digital platforms for data collection, labeling, and utilization</p>','2026-05-06 15:46:03',NULL,1);
insert  into `eoi_request_prebid_query`(`questionid`,`queryid`,`requestid`,`vendorid`,`clause_reference`,`clause_detail`,`queries_with_justification`,`creationdate`,`iseditable`,`answer`,`answeredon`,`subuserid`,`isprebid`) values (121,29,143,4,'<p>4.4 Startup Incubation Centre</p>','<p>&bull; &nbsp; &nbsp;Organize hackathons, innovation challenges, and accelerator programs</p>','<p>We understand that the envisaged Scope is limited to conceptualizing the hackathons, innovation challenges, and accelerator programs there would be a separate Agency to organize the same. Kindly confirm in case of any deviation in understanding.</p>','2026-04-29 16:42:50',1,'<p>Yes</p>','2026-05-06 15:46:30',NULL,1);
insert  into `eoi_request_prebid_query`(`questionid`,`queryid`,`requestid`,`vendorid`,`clause_reference`,`clause_detail`,`queries_with_justification`,`creationdate`,`iseditable`,`answer`,`answeredon`,`subuserid`,`isprebid`) values (122,29,143,4,'<p>7.7 Additional Responsibilities </p>','<p>&bull; &nbsp; &nbsp;Client shall provide sitting space, office furniture and wifi access to the consultants, however, arranging the IT assets like the Laptop/computer and auxiliary hardware and software required for performing the services shall be arranged by the consulting firm&nbsp;</p>','<p>We understand that the Consultant shall arrange the Laptop required for the project. However, the Client shall provide specialized or licensed software for AI as required for the project. Kindly confirm in case of any deviation in understanding.</p>','2026-04-29 16:43:16',1,'<p>Yes</p>','2026-05-06 15:46:46',NULL,1);
insert  into `eoi_request_prebid_query`(`questionid`,`queryid`,`requestid`,`vendorid`,`clause_reference`,`clause_detail`,`queries_with_justification`,`creationdate`,`iseditable`,`answer`,`answeredon`,`subuserid`,`isprebid`) values (123,28,143,5,'<p>4.2, 6</p>','<p>Identify and onboard technology partners, academic institutions, and research bodies</p>','<p>It is requested to redefine this clause as- Identify technology partners, academic institutions and research bodies for onboarding<br>Rationale: We can identify the partners and the modes, but the onboarding is to be done by the department, based on the discussions with that party.</p>','2026-04-29 17:16:52',1,'<p class=\"p1\">Changed as- Identify and support onboarding of technology partners, academic institutions, and research bodies</p>','2026-05-06 15:47:18',NULL,1);
insert  into `eoi_request_prebid_query`(`questionid`,`queryid`,`requestid`,`vendorid`,`clause_reference`,`clause_detail`,`queries_with_justification`,`creationdate`,`iseditable`,`answer`,`answeredon`,`subuserid`,`isprebid`) values (124,28,143,5,'<p>4.8, 8</p>','<p>Conduct workshops, seminars, and awareness campaigns</p>','<p>It is requested to mention how many such trainning programmes to be conducted and at what frequency</p>','2026-04-29 17:18:11',1,'<p class=\"p1\">The number training program will be decided at a later stage, however the responsibilities of conducting such program is not in scope of consultants<span class=\"Apple-converted-space\">&nbsp; </span>only manpower deployed will be engaged for such programs</p>','2026-05-06 15:47:47',NULL,1);
insert  into `eoi_request_prebid_query`(`questionid`,`queryid`,`requestid`,`vendorid`,`clause_reference`,`clause_detail`,`queries_with_justification`,`creationdate`,`iseditable`,`answer`,`answeredon`,`subuserid`,`isprebid`) values (125,28,143,5,'<p>6, 12</p>','<p>Initial Contract Period for the project shall be 12 months which is extendable for next 12 Months on mutual consent. However, based on the performance of the consultant and approval from the competent authority, the contract duration may be extended further for 12 months or beyond based on the mutual agreement.</p>','<p>Request confirmation if revised rates as per the empanelment be considered if the contract is extended beyond 12 months</p>','2026-04-29 17:20:03',1,'<p class=\"p1\">As the per the empanelment agreement conditions</p>','2026-05-06 15:48:08',NULL,1);
insert  into `eoi_request_prebid_query`(`questionid`,`queryid`,`requestid`,`vendorid`,`clause_reference`,`clause_detail`,`queries_with_justification`,`creationdate`,`iseditable`,`answer`,`answeredon`,`subuserid`,`isprebid`) values (126,28,143,5,'<p>7.4.3, 14</p>','<p>1. Any intellectual property created during the course of employment will be owned by CHiPS, Government of Chhattisgarh.<br>2. Consultants must agree to transfer all intellectual property rights to CHiPS, Government of Chhattisgarh upon creation.</p>','<p>Request to add this clause - Upon expiration of this Agreement / Contract or sooner upon written request of the Client, all Confidential Information in the possession of the Consultant/ Vendor/ Bidder/ Contractor shall be returned to the Client or destroyed under conditions which preserve the confidentiality of the Confidential Information, at the option and instruction of the Client. &nbsp;Pre-existing of the Consultant/ Vendor/ Bidder/ Contractor&rsquo;s IPR in the deliverables will still vest with the Consultant/ Vendor/ Bidder/ Contractor. &nbsp; Notwithstanding the foregoing, the Consultant/ Vendor/ Bidder/ Contractor retains all rights in the Deliverables and work product, and in any software, materials, know-how and/or methodologies that the Consultant/ Vendor/ Bidder/ Contractor may use or develop in connection with this Contract. The Consultant/ Vendor/ Bidder/ Contractor is not responsible if the client infringes the IPR by modifying the deliverables submitted by the Consultant/ Vendor/ Bidder/ Contractor.</p>','2026-04-29 17:22:11',1,'<p class=\"p1\">As per the EoI terms and conditions</p>','2026-05-06 15:48:34',NULL,1);
insert  into `eoi_request_prebid_query`(`questionid`,`queryid`,`requestid`,`vendorid`,`clause_reference`,`clause_detail`,`queries_with_justification`,`creationdate`,`iseditable`,`answer`,`answeredon`,`subuserid`,`isprebid`) values (127,28,143,5,'<p>7.5.3, 14</p>','<p>1. Consultants are expected to participate in ongoing capacity-building programs and training sessions to enhance their skills and knowledge.<br>2. CHiPS, Government of Chhattisgarh will provide necessary resources and opportunities for professional development.</p>','<p>As per the comment from our risk team, request to modify this clause as Consultants may be assigned additional responsibilities related to day-to-day operations, provided that such responsibilities are reasonable, directly related to the project, and remain within the agreed scope of work.</p>','2026-04-29 17:49:23',1,'<p class=\"p1\">As per the EoI terms and conditions</p>','2026-05-06 15:49:05',NULL,1);
insert  into `eoi_request_prebid_query`(`questionid`,`queryid`,`requestid`,`vendorid`,`clause_reference`,`clause_detail`,`queries_with_justification`,`creationdate`,`iseditable`,`answer`,`answeredon`,`subuserid`,`isprebid`) values (128,28,143,5,'<p>7.7, 15</p>','<p>The consultants shall verify the correctness of the data/ information provided by the client and satisfy them about the accuracy of data/ information / material before these are used. Data/ information /material provided to the consultants shall remain the property of the originating agency and shall be provided solely for the purpose of the work to be done under this contract. All such borrowed material shall be returned to the client upon completion of the study.</p>','<p>As per the comment from our risk team, request to modify this clause as - The consultants shall utilize the data/information/material provided by the client on an &lsquo;as-is&rsquo; basis. While reasonable care shall be exercised in its use, the consultants shall not be held responsible for the accuracy, completeness, or reliability of such data provided by the client. All such data/information/material shall remain the property of the originating agency and shall be used solely for the purposes of this contract, and returned upon completion of the assignment.</p>','2026-04-29 18:04:13',1,'<p class=\"p1\">As per the EoI terms and conditions</p>','2026-05-06 15:49:24',NULL,1);
insert  into `eoi_request_prebid_query`(`questionid`,`queryid`,`requestid`,`vendorid`,`clause_reference`,`clause_detail`,`queries_with_justification`,`creationdate`,`iseditable`,`answer`,`answeredon`,`subuserid`,`isprebid`) values (129,30,146,1,'<p class=\"MsoNormal\" style=\"text-align: left; text-indent: 0in; margin: 0in 0in 14.75pt 0in;\" align=\"left\">Factsheet&nbsp;</p>\n<p class=\"MsoNormal\" style=\"text-align: left; text-indent: 0in; margin: 0in 0in 14.75pt 0in;\" align=\"left\"><span style=\"font-size: 10.0pt; mso-bidi-font-size: 12.0pt; line-height: 107%; font-family: \'Arial\',sans-serif; mso-fareast-font-family: Arial; color: black; mso-ansi-language: EN-US; mso-fareast-language: EN-US; mso-bidi-language: AR-SA;\">Page no-04&nbsp;</span></p>','<p class=\"MsoNormal\" style=\"text-align: left; text-indent: 0in; margin: 0in 0in 14.75pt 0in;\" align=\"left\">Last date of Bid query is 18/05/2026, 17:00 Hrs.</p>\r\n<p><span style=\"font-size: 10.0pt; mso-bidi-font-size: 12.0pt; line-height: 107%; font-family: \'Arial\',sans-serif; mso-fareast-font-family: Arial; color: black; mso-ansi-language: EN-US; mso-fareast-language: EN-US; mso-bidi-language: AR-SA;\">Last date of Proposal submission is 02/06/2026, 17:00 Hrs. </span></p>','<p style=\"text-align: justify;\"><span style=\"font-size: 10.0pt; mso-bidi-font-size: 12.0pt; line-height: 107%; font-family: \'Arial\',sans-serif; mso-fareast-font-family: Arial; color: black; mso-ansi-language: EN-US; mso-fareast-language: EN-US; mso-bidi-language: AR-SA;\">The tentative expected date and time for issuance of responses to the bid queries is not mentioned. As the clarifications issued in response to pre-bid queries may necessitate corresponding amendments in the technical proposal and team composition, we kindly request the department to consider granting an extension of 15 days from the date of issuance of responses to these queries for submission of final proposals. This will ensure adequate time for comprehensive and compliant proposal submission. </span></p>','2026-05-18 14:50:46',1,'<p>The district appreciates the concern raised. However, due to the immediacy of the project timelines and the need to adhere to the overall schedule, it will not be possible to grant an extension of 15 days for submission of proposals. Bidders are requested to prepare their submissions based on the clarifications that will be issued, within the originally stipulated timeframe.</p>','2026-05-29 13:53:30',NULL,1);
insert  into `eoi_request_prebid_query`(`questionid`,`queryid`,`requestid`,`vendorid`,`clause_reference`,`clause_detail`,`queries_with_justification`,`creationdate`,`iseditable`,`answer`,`answeredon`,`subuserid`,`isprebid`) values (130,30,146,1,'<p class=\"MsoNormal\" style=\"text-align: left; text-indent: 0in; margin: 0in 0in .8pt 0in;\" align=\"left\">Team</p>\r\n<p class=\"MsoNormal\" style=\"text-align: left; text-indent: 0in; margin: 0in 0in 14.75pt 0in;\" align=\"left\">Composition</p>\r\n<p><span style=\"font-size: 10.0pt; mso-bidi-font-size: 12.0pt; line-height: 107%; font-family: \'Arial\',sans-serif; mso-fareast-font-family: Arial; color: black; mso-ansi-language: EN-US; mso-fareast-language: EN-US; mso-bidi-language: AR-SA;\">Page no-10 </span></p>','<p class=\"MsoNormal\" style=\"text-align: left; text-indent: 0in; line-height: 115%; margin: 0in 52.9pt 13.9pt 0in;\" align=\"left\">Associate Consultant-Governance sector<span style=\"mso-spacerun: yes;\">&nbsp; </span>- Agriculture and Allied Specialist<span style=\"mso-spacerun: yes;\">&nbsp; </span></p>\r\n<p class=\"MsoNormal\" style=\"text-align: left; text-indent: 0in; margin: 0in 0in .8pt 0in;\" align=\"left\"><span style=\"mso-spacerun: yes;\">&nbsp;</span></p>\r\n<p class=\"MsoNormal\" style=\"text-align: left; text-indent: 0in; margin: 0in 0in .75pt 0in;\" align=\"left\"><strong style=\"mso-bidi-font-weight: normal;\">Qualification: -</strong> Master&rsquo;s in agriculture/ /Agribusiness <span style=\"font-size: 10.0pt; mso-bidi-font-size: 12.0pt; line-height: 107%; font-family: \'Arial\',sans-serif; mso-fareast-font-family: Arial; color: black; mso-ansi-language: EN-US; mso-fareast-language: EN-US; mso-bidi-language: AR-SA;\">Management from a recognize University<span style=\"mso-spacerun: yes;\">&nbsp; </span></span></p>','<p class=\"MsoNormal\" style=\"text-indent: 0in; line-height: 115%; margin: 0in 0in 13.95pt; text-align: justify;\" align=\"left\">The EoI mandate master&rsquo;s in agriculture/ /Agribusiness Management from a recognize University</p>\r\n<p style=\"text-align: justify;\"><span style=\"font-size: 10.0pt; mso-bidi-font-size: 12.0pt; line-height: 107%; font-family: \'Arial\',sans-serif; mso-fareast-font-family: Arial; color: black; mso-ansi-language: EN-US; mso-fareast-language: EN-US; mso-bidi-language: AR-SA;\">We kindly request that the eligibility <strong style=\"mso-bidi-font-weight: normal;\">criteria be revised to also include</strong> Masters in Rural Management / M. Sc. Agriculture/ MSW/ master\'s in social sciences/PGDFM/PGDRDM or related field education qualification. This modification will help ensure a wider range of participation from qualified professionals while maintaining the quality expected for the assignment. </span></p>','2026-05-18 14:51:47',1,'<p>The district acknowledges the suggestion and agrees that broadening the eligibility criteria will encourage wider participation while maintaining the quality standards required for the assignment. Accordingly, the qualification requirement will be revised to also include Master&rsquo;s in Rural Management, M.Sc. Agriculture, MSW, Master&rsquo;s in Social Sciences, PGDFM, PGDRDM, or other related fields from a recognized university.</p>','2026-05-29 13:53:54',NULL,1);
insert  into `eoi_request_prebid_query`(`questionid`,`queryid`,`requestid`,`vendorid`,`clause_reference`,`clause_detail`,`queries_with_justification`,`creationdate`,`iseditable`,`answer`,`answeredon`,`subuserid`,`isprebid`) values (131,30,146,1,'<p class=\"MsoNormal\" style=\"text-align: left; text-indent: 0in; margin: 0in 0in .9pt 0in;\" align=\"left\">Team</p>\r\n<p class=\"MsoNormal\" style=\"text-align: left; text-indent: 0in; margin: 0in 0in 14.7pt 0in;\" align=\"left\">Composition</p>\r\n<p><span style=\"font-size: 10.0pt; mso-bidi-font-size: 12.0pt; line-height: 107%; font-family: \'Arial\',sans-serif; mso-fareast-font-family: Arial; color: black; mso-ansi-language: EN-US; mso-fareast-language: EN-US; mso-bidi-language: AR-SA;\">Page no-12</span></p>','<p class=\"MsoNormal\" style=\"text-align: left; text-indent: 0in; margin: 0in 0in .9pt 0in;\" align=\"left\"><strong style=\"mso-bidi-font-weight: normal;\">Associate Consultant_ Social sector </strong></p>\r\n<p class=\"MsoNormal\" style=\"text-align: left; text-indent: 0in; margin: 0in 0in 14.75pt 0in;\" align=\"left\">- Health Cum Education Consultant</p>\r\n<p class=\"MsoNormal\" style=\"text-align: left; text-indent: 0in; margin: 0in 0in 14.75pt 0in;\" align=\"left\"><strong style=\"mso-bidi-font-weight: normal;\">Qualification: -<span style=\"mso-spacerun: yes;\">&nbsp; </span></strong></p>\r\n<p class=\"MsoNormal\" style=\"text-align: left; text-indent: 0in; margin: 0in 0in .75pt 0in;\" align=\"left\">Masters in Community Health / Health Management/</p>\r\n<p><span style=\"font-size: 10.0pt; mso-bidi-font-size: 12.0pt; line-height: 107%; font-family: \'Arial\',sans-serif; mso-fareast-font-family: Arial; color: black; mso-ansi-language: EN-US; mso-fareast-language: EN-US; mso-bidi-language: AR-SA;\">Education / Education Planning / Social Sciences/&nbsp;</span>Rural Development / Development Studies / Social Work.<span style=\"mso-spacerun: yes;\">&nbsp; </span></p>','<p class=\"MsoNormal\" style=\"text-indent: 0in; margin: 0in 0in 0.8pt; text-align: justify;\" align=\"left\">The EoI mandate Masters in Community</p>\r\n<p class=\"MsoNormal\" style=\"text-indent: 0in; margin: 0in 0in 0.75pt; text-align: justify;\" align=\"left\">Health / Health Management/ Education /</p>\r\n<p class=\"MsoNormal\" style=\"text-indent: 0in; line-height: 115%; margin: 0in 0in 13.85pt; text-align: justify;\" align=\"left\">Education Planning / Social Sciences/ Rural Development / Development Studies / Social Work.<span style=\"mso-spacerun: yes;\">&nbsp; </span></p>\r\n<p style=\"text-align: justify;\"><span style=\"font-size: 10.0pt; mso-bidi-font-size: 12.0pt; line-height: 107%; font-family: \'Arial\',sans-serif; mso-fareast-font-family: Arial; color: black; mso-ansi-language: EN-US; mso-fareast-language: EN-US; mso-bidi-language: AR-SA;\">We kindly request that the eligibility <strong style=\"mso-bidi-font-weight: normal;\">criteria be revised to also include </strong></span>master&rsquo;s in human resource management /Diploma in Health&nbsp;Management/PGDFM/PGDRDM/Post</p>\r\n<p style=\"text-align: justify;\"><span style=\"font-size: 10.0pt; mso-bidi-font-size: 12.0pt; line-height: 107%; font-family: \'Arial\',sans-serif; mso-fareast-font-family: Arial; color: black; mso-ansi-language: EN-US; mso-fareast-language: EN-US; mso-bidi-language: AR-SA;\"><strong style=\"mso-bidi-font-weight: normal;\">Graduate Diploma or related field qualification. This modification will help ensure a wider range of participation from qualified professionals while maintaining the quality expected for the assignment.&nbsp;</strong></span></p>','2026-05-18 14:53:33',1,'<p>The eligibility criteria can be revised to also include Master&rsquo;s in Human Resource Management, Diploma in Health Management, PGDFM, PGDRDM, Post Graduate Diploma, or related fields.&nbsp;</p>','2026-05-29 13:55:54',NULL,1);
insert  into `eoi_request_prebid_query`(`questionid`,`queryid`,`requestid`,`vendorid`,`clause_reference`,`clause_detail`,`queries_with_justification`,`creationdate`,`iseditable`,`answer`,`answeredon`,`subuserid`,`isprebid`) values (132,30,146,1,'<p class=\"MsoNormal\" style=\"text-align: left; text-indent: 0in; margin: 0in 0in .8pt 5.4pt;\" align=\"left\">Evaluation</p>\n<p class=\"MsoNormal\" style=\"text-align: left; text-indent: 0in; margin: 0in 0in 14.75pt 5.4pt;\" align=\"left\">Process</p>\n<p class=\"MsoNormal\" style=\"text-align: left; text-indent: 0in; margin: 0in 0in 4.8pt 5.4pt;\" align=\"left\">Page no-16-<span style=\"font-size: 10.0pt; mso-bidi-font-size: 12.0pt; line-height: 107%; font-family: \'Arial\',sans-serif; mso-fareast-font-family: Arial; color: black; mso-ansi-language: EN-US; mso-fareast-language: EN-US; mso-bidi-language: AR-SA;\">17 </span></p>','<table class=\"TableGrid\" style=\"width: 200.05pt; margin-left: 20pt; border-collapse: collapse; height: 477.625px; border-spacing: 0px; border: 0px solid rgb(0, 0, 0);\" border=\"1\" width=\"732\" cellspacing=\"0\" cellpadding=\"0\">\n<tbody>\n<tr style=\"height: 42px;\">\n<td style=\"width: 129.917px; border: 1pt solid rgb(0, 0, 0); padding: 2.1pt 0.1pt 2pt 0in; height: 42px; text-align: center;\" valign=\"top\" width=\"160\">\n<p class=\"MsoNormal\" style=\"text-align: left; text-indent: 0in; margin: 0in 0in 0in 5.4pt;\" align=\"left\"><strong>Bidder presentation </strong></p>\n</td>\n<td style=\"width: 132.562px; border-width: 1pt 1pt 1pt medium; border-style: solid solid solid none; border-color: rgb(0, 0, 0); border-image: initial; padding: 2.1pt 0.1pt 2pt 0in; height: 42px; text-align: center;\" valign=\"top\" width=\"162\">\n<p class=\"MsoNormal\" style=\"text-align: left; text-indent: 0in; margin: 0in 0in 0in 5.4pt;\" align=\"left\"><strong>Candidate Interview </strong></p>\n</td>\n</tr>\n<tr style=\"height: 36.9271px;\">\n<td style=\"width: 129.917px; border-width: medium 1pt 1pt; border-style: none solid solid; border-color: rgb(0, 0, 0); border-image: initial; padding: 2.1pt 0.1pt 2pt 0in; height: 36.9271px;\" valign=\"top\" width=\"160\">\n<p class=\"MsoNormal\" style=\"text-align: left; text-indent: 0in; margin: 0in 0in 0in 5.4pt;\" align=\"left\"><strong style=\"mso-bidi-font-weight: normal;\">50 </strong></p>\n</td>\n<td style=\"width: 132.562px; border-width: medium 1pt 1pt medium; border-style: none solid solid none; border-color: rgb(0, 0, 0); padding: 2.1pt 0.1pt 2pt 0in; height: 36.9271px;\" valign=\"top\" width=\"162\">\n<p class=\"MsoNormal\" style=\"text-align: left; text-indent: 0in; margin: 0in 0in 0in 5.4pt;\" align=\"left\"><strong style=\"mso-bidi-font-weight: normal;\">50 </strong></p>\n</td>\n</tr>\n<tr style=\"height: 398.698px;\">\n<td style=\"width: 129.917px; border-width: medium 1pt 1pt; border-style: none solid solid; border-color: rgb(0, 0, 0); border-image: initial; padding: 2.1pt 0.1pt 2pt 0in; height: 398.698px;\" valign=\"top\" width=\"160\">\n<p class=\"MsoNormal\" style=\"text-align: left; text-indent: -.25in; line-height: 117%; mso-list: l0 level1 lfo1; margin: 0in 0in 1.3pt 19.4pt;\" align=\"left\"><!-- [if !supportLists]--><span style=\"mso-bidi-font-size: 10.0pt; line-height: 117%;\"><span style=\"mso-list: Ignore;\">&bull;<span style=\"font: 7.0pt \'Times New Roman\';\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></span></span><!--[endif]-->Approach and Methodology</p>\n<p class=\"MsoNormal\" style=\"text-align: left; text-indent: -.25in; line-height: 117%; mso-list: l0 level1 lfo1; margin: 0in 0in 1.3pt 19.4pt;\" align=\"left\"><!-- [if !supportLists]--><span style=\"mso-bidi-font-size: 10.0pt; line-height: 117%;\"><span style=\"mso-list: Ignore;\">&bull;<span style=\"font: 7.0pt \'Times New Roman\';\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></span></span><!--[endif]-->Understanding of the Project</p>\n<p class=\"MsoNormal\" style=\"text-align: left; text-indent: -.25in; line-height: 115%; mso-list: l0 level1 lfo1; margin: 0in 0in 1.5pt 19.4pt;\" align=\"left\"><!-- [if !supportLists]--><span style=\"mso-bidi-font-size: 10.0pt; line-height: 115%;\"><span style=\"mso-list: Ignore;\">&bull;<span style=\"font: 7.0pt \'Times New Roman\';\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></span></span><!--[endif]-->Quality of proposed methodology for such specific kind of a project</p>\n<p class=\"MsoNormal\" style=\"text-align: left; text-indent: -.25in; line-height: 115%; mso-list: l0 level1 lfo1; margin: 0in 0in 0in 19.4pt;\" align=\"left\"><!-- [if !supportLists]--><span style=\"mso-bidi-font-size: 10.0pt; line-height: 115%;\"><span style=\"mso-list: Ignore;\">&bull;<span style=\"font: 7.0pt \'Times New Roman\';\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></span></span><!--[endif]-->Prior exposure to implementing government projects in Bid Management and Exit</p>\n<p class=\"MsoNormal\" style=\"text-align: left; text-indent: 0in; margin: 0in 0in 2.45pt 19.35pt;\" align=\"left\">Management</p>\n<p class=\"MsoNormal\" style=\"text-align: left; text-indent: -.25in; mso-list: l0 level1 lfo1; margin: 0in 0in 0in 19.4pt;\" align=\"left\"><!-- [if !supportLists]--><span style=\"mso-bidi-font-size: 10.0pt; line-height: 107%;\"><span style=\"mso-list: Ignore;\">&bull;<span style=\"font: 7.0pt \'Times New Roman\';\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></span></span><!--[endif]-->Understanding of key SLAs for the project management<span style=\"mso-spacerun: yes;\">&nbsp; </span></p>\n</td>\n<td style=\"width: 132.562px; border-width: medium 1pt 1pt medium; border-style: none solid solid none; border-color: rgb(0, 0, 0); padding: 2.1pt 0.1pt 2pt 0in; height: 398.698px;\" valign=\"top\" width=\"162\">\n<p class=\"MsoNormal\" style=\"text-align: left; text-indent: -.25in; mso-list: l1 level1 lfo2; margin: 0in 0in .75pt 18.4pt;\" align=\"left\"><!-- [if !supportLists]--><span style=\"mso-bidi-font-size: 10.0pt; line-height: 107%;\"><span style=\"mso-list: Ignore;\">&bull;<span style=\"font: 7.0pt \'Times New Roman\';\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></span></span><!--[endif]-->Suitability of profile</p>\n<p class=\"MsoNormal\" style=\"text-align: left; text-indent: -.25in; mso-list: l1 level1 lfo2; margin: 0in 0in 0in 18.4pt;\" align=\"left\"><!-- [if !supportLists]--><span style=\"mso-bidi-font-size: 10.0pt; line-height: 107%;\"><span style=\"mso-list: Ignore;\">&bull;<span style=\"font: 7.0pt \'Times New Roman\';\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></span></span><!--[endif]-->Educational</p>\n<p class=\"MsoNormal\" style=\"text-align: left; text-indent: 0in; margin: 0in 0in 2.45pt 18.4pt;\" align=\"left\">Qualification</p>\n<p class=\"MsoNormal\" style=\"text-align: left; text-indent: -.25in; line-height: 116%; mso-list: l1 level1 lfo2; margin: 0in 0in 1.45pt 18.4pt;\" align=\"left\"><!-- [if !supportLists]--><span style=\"mso-bidi-font-size: 10.0pt; line-height: 116%;\"><span style=\"mso-list: Ignore;\">&bull;<span style=\"font: 7.0pt \'Times New Roman\';\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></span></span><!--[endif]-->Years of relevant experience</p>\n<p class=\"MsoNormal\" style=\"text-align: left; text-indent: -.25in; mso-list: l1 level1 lfo2; margin: 0in 0in 0in 18.4pt;\" align=\"left\"><!-- [if !supportLists]--><span style=\"mso-bidi-font-size: 10.0pt; line-height: 107%;\"><span style=\"mso-list: Ignore;\">&bull;<span style=\"font: 7.0pt \'Times New Roman\';\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></span></span><!--[endif]-->Good understanding</p>\n<p class=\"MsoNormal\" style=\"text-align: left; text-indent: 0in; margin: 0in 0in 2.45pt 18.4pt;\" align=\"left\">of scope of work<span style=\"mso-spacerun: yes;\">&nbsp; </span></p>\n<p class=\"MsoNormal\" style=\"text-align: left; text-indent: -.25in; line-height: 115%; mso-list: l1 level1 lfo2; margin: 0in 0in 1.5pt 18.4pt;\" align=\"left\"><!-- [if !supportLists]--><span style=\"mso-bidi-font-size: 10.0pt; line-height: 115%;\"><span style=\"mso-list: Ignore;\">&bull;<span style=\"font: 7.0pt \'Times New Roman\';\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></span></span><!--[endif]-->Strong ability to understand and deliberate and report</p>\n<p class=\"MsoNormal\" style=\"text-align: left; text-indent: -.25in; line-height: 117%; mso-list: l1 level1 lfo2; margin: 0in 0in 0in 18.4pt;\" align=\"left\"><!-- [if !supportLists]--><span style=\"mso-bidi-font-size: 10.0pt; line-height: 117%;\"><span style=\"mso-list: Ignore;\">&bull;<span style=\"font: 7.0pt \'Times New Roman\';\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></span></span><!--[endif]-->Excellent communication</p>\n<p class=\"MsoNormal\" style=\"text-align: left; text-indent: 0in; margin: 0in 0in 2.45pt 18.4pt;\" align=\"left\">abilities</p>\n<p class=\"MsoNormal\" style=\"text-align: left; text-indent: -.25in; mso-list: l1 level1 lfo2; margin: 0in 0in 0in 18.4pt;\" align=\"left\"><!-- [if !supportLists]--><span style=\"mso-bidi-font-size: 10.0pt; line-height: 107%;\"><span style=\"mso-list: Ignore;\">&bull;<span style=\"font: 7.0pt \'Times New Roman\';\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></span></span><!--[endif]-->Experience of</p>\n<p class=\"MsoNormal\" style=\"text-align: left; text-indent: 0in; margin: 0in 0in .8pt 18.4pt;\" align=\"left\">Working in</p>\n<p class=\"MsoNormal\" style=\"text-indent: 0in; margin: 0in 0in 0in 18.4pt; text-align: justify;\" align=\"left\">Government Projects<span style=\"mso-spacerun: yes;\">&nbsp; </span></p>\n</td>\n</tr>\n</tbody>\n</table>','<p style=\"text-align: justify;\"><span style=\"font-size: 10.0pt; mso-bidi-font-size: 12.0pt; line-height: 107%; font-family: \'Arial\',sans-serif; mso-fareast-font-family: Arial; color: black; mso-ansi-language: EN-US; mso-fareast-language: EN-US; mso-bidi-language: AR-SA;\">The evaluation process provides 50 marks for bidder presentation and 50 marks for candidate interview, along with broad evaluation criteria. In the interest of transparency and to enable bidders to prepare their proposals appropriately, we kindly request the department to provide a detailed breakup of the marking scheme under each evaluation subsection. For example, the 50 marks allocated to the candidates’ interview may kindly be further distributed profile-wise across all six proposed positions, with clear sub-criteria such as educational qualification, relevant experience, domain understanding, communication skills, and other competencies. Similarly, for the bidder presentation component, a detailed criterion-wise mark allocation may also please be shared. This clarification will help ensure uniform understanding of the evaluation framework among all participating bidders. </span></p>','2026-05-18 14:55:15',1,'<p>A detailed breakup of the marking scheme under each evaluation subsection cannot be provided. The broad criteria already shared are intended to ensure flexibility in assessing bidders and candidates holistically, based on both presentation and interview performance. This approach allows the evaluation committee to exercise professional judgment while maintaining fairness and transparency across all participants.</p>','2026-05-29 13:59:42',NULL,1);
insert  into `eoi_request_prebid_query`(`questionid`,`queryid`,`requestid`,`vendorid`,`clause_reference`,`clause_detail`,`queries_with_justification`,`creationdate`,`iseditable`,`answer`,`answeredon`,`subuserid`,`isprebid`) values (133,30,146,1,'<p class=\"MsoNormal\" style=\"text-align: left; text-indent: 0in; margin: 0in 0in .75pt 5.4pt;\" align=\"left\">Payment</p>\r\n<p class=\"MsoNormal\" style=\"text-align: left; text-indent: 0in; margin: 0in 0in .75pt 5.4pt;\" align=\"left\">Terms</p>\r\n<p><span style=\"font-size: 10.0pt; mso-bidi-font-size: 12.0pt; line-height: 107%; font-family: \'Arial\',sans-serif; mso-fareast-font-family: Arial; color: black; mso-ansi-language: EN-US; mso-fareast-language: EN-US; mso-bidi-language: AR-SA;\">Page no-17 </span></p>','<p class=\"MsoNormal\" style=\"text-align: left; line-height: 115%; mso-list: l0 level1 lfo1; margin: 0in 0in 1.5pt 21.4pt;\" align=\"left\"><!-- [if !supportLists]--><span style=\"mso-bidi-font-size: 10.0pt; line-height: 115%;\"><span style=\"mso-list: Ignore;\">&bull;<span style=\"font: 7.0pt \'Times New Roman\';\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></span></span><!--[endif]-->Payment will be made monthly on submission of invoice in duplicate to the employer as per the agreed manpower services engaged for the project.</p>\r\n<p class=\"MsoNormal\" style=\"text-align: left; line-height: 115%; mso-list: l0 level1 lfo1; margin: 0in 0in 1.5pt 21.4pt;\" align=\"left\"><!-- [if !supportLists]--><span style=\"mso-bidi-font-size: 10.0pt; line-height: 115%;\"><span style=\"mso-list: Ignore;\">&bull;<span style=\"font: 7.0pt \'Times New Roman\';\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></span></span><!--[endif]-->For reasons beyond the control of the selected bidder or CHiPS, as the case may be, selected bidder shall be paid the requisite man month payment in the event that selected bidder has performed on its obligation in compliance with the terms of this contract.</p>\r\n<p class=\"MsoNormal\" style=\"text-align: left; mso-list: l0 level1 lfo1; margin: 0in 0in 0in 21.4pt;\" align=\"left\"><!-- [if !supportLists]--><span style=\"mso-bidi-font-size: 10.0pt; line-height: 107%;\"><span style=\"mso-list: Ignore;\">&bull;<span style=\"font: 7.0pt \'Times New Roman\';\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></span></span><!--[endif]-->The payment shall be payable after review of <span style=\"font-size: 10.0pt; mso-bidi-font-size: 12.0pt; line-height: 107%; font-family: \'Arial\',sans-serif; mso-fareast-font-family: Arial; color: black; mso-ansi-language: EN-US; mso-fareast-language: EN-US; mso-bidi-language: AR-SA;\">Project Review Committee </span></p>','<ul>\r\n<li class=\"MsoNormal\" style=\"text-align: left; line-height: 116%;\"><!-- [if !supportLists]-->We seek clarification as to whether the review by the Project Review&nbsp;Committee will be conducted for each monthly invoice submitted or on some other periodic basis. Understanding the review cycle will help ensure timely invoicing and payment processing.</li>\r\n<li><span style=\"font-size: 10.0pt; mso-bidi-font-size: 12.0pt; line-height: 107%; font-family: \'Arial\',sans-serif; mso-fareast-font-family: Arial; color: black; mso-ansi-language: EN-US; mso-fareast-language: EN-US; mso-bidi-language: AR-SA;\">Kindly clarify the deliverable review and approval mechanism, including the competent approving authority, indicative review timelines, and whether deemed approval will apply if comments are not received within a specified period.<span style=\"font-size: 10.0pt; mso-bidi-font-size: 12.0pt; line-height: 107%; font-family: \'Aptos\',sans-serif; mso-fareast-font-family: Aptos; mso-bidi-font-family: Aptos; color: black; mso-ansi-language: EN-US; mso-fareast-language: EN-US; mso-bidi-language: AR-SA;\"> </span></span></li>\r\n</ul>','2026-05-18 14:56:41',1,'<p>The deliverable review will be conducted on a periodic basis, which may be monthly or quarterly, depending on the nature of engagements and deliverables. The Project Review Committee will serve as the competent approving authority, and the review timelines will follow a flexible approach to accommodate the contextual requirements of the assignment. This mechanism ensures that invoicing and approvals remain aligned with the dynamic nature of project activities.</p>','2026-05-29 14:05:11',NULL,1);
insert  into `eoi_request_prebid_query`(`questionid`,`queryid`,`requestid`,`vendorid`,`clause_reference`,`clause_detail`,`queries_with_justification`,`creationdate`,`iseditable`,`answer`,`answeredon`,`subuserid`,`isprebid`) values (134,30,146,1,'<p class=\"MsoNormal\" style=\"text-align: left; text-indent: 0in; line-height: 115%; margin: 0in 0in 13.95pt 2.0pt;\" align=\"left\">Documents required as response to the EOI</p>\r\n<p><span style=\"font-size: 10.0pt; mso-bidi-font-size: 12.0pt; line-height: 107%; font-family: \'Arial\',sans-serif; mso-fareast-font-family: Arial; color: black; mso-ansi-language: EN-US; mso-fareast-language: EN-US; mso-bidi-language: AR-SA;\">Page no-17 </span></p>','<p class=\"MsoNormal\" style=\"text-align: left; mso-list: l0 level1 lfo1; margin: 0in 0in .7pt .25in;\" align=\"left\"><!-- [if !supportLists]--><span style=\"mso-bidi-font-size: 10.0pt; line-height: 107%;\"><span style=\"mso-list: Ignore;\">&bull;<span style=\"font: 7.0pt \'Times New Roman\';\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></span></span><!--[endif]-->Signed copy of this EoI<span style=\"mso-spacerun: yes;\">&nbsp; </span></p>\r\n<p class=\"MsoNormal\" style=\"text-align: left; mso-list: l0 level1 lfo1; margin: 0in 0in .65pt .25in;\" align=\"left\"><!-- [if !supportLists]--><span style=\"mso-bidi-font-size: 10.0pt; line-height: 107%;\"><span style=\"mso-list: Ignore;\">&bull;<span style=\"font: 7.0pt \'Times New Roman\';\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></span></span><!--[endif]-->Copy of Approach and methodology presentation<span style=\"mso-spacerun: yes;\">&nbsp; </span></p>\r\n<p class=\"MsoNormal\" style=\"text-align: left; mso-list: l0 level1 lfo1; margin: 0in 0in 0in .25in;\" align=\"left\"><!-- [if !supportLists]--><span style=\"mso-bidi-font-size: 10.0pt; line-height: 107%;\"><span style=\"mso-list: Ignore;\">&bull;<span style=\"font: 7.0pt \'Times New Roman\';\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></span></span><!--[endif]-->Resumes of the proposed resources.</p>','<p style=\"text-align: justify;\"><span style=\"font-size: 10.0pt; mso-bidi-font-size: 12.0pt; line-height: 107%; font-family: \'Arial\',sans-serif; mso-fareast-font-family: Arial; color: black; mso-ansi-language: EN-US; mso-fareast-language: EN-US; mso-bidi-language: AR-SA;\">We would like to seek clarification on whether there is any page limitation or format specification for the Approach &amp; Methodology presentation to be submitted. Additionally, as the EOI does not specify the required format for resource CV submissions, we request confirmation whether the World Bank standard CV format will be acceptable for this purpose. This will facilitate the preparation of compliant and standardized documentation. </span></p>','2026-05-18 14:57:17',1,'<p>There is no page limitation prescribed for the Approach &amp; Methodology presentation; however, it should be clear, concise, and demonstrate a sound understanding of the functioning and contextual clarity. For resource CV submissions, no specific format has been mandated, and the World Bank standard CV format will be acceptable.</p>','2026-05-29 14:07:46',NULL,1);
insert  into `eoi_request_prebid_query`(`questionid`,`queryid`,`requestid`,`vendorid`,`clause_reference`,`clause_detail`,`queries_with_justification`,`creationdate`,`iseditable`,`answer`,`answeredon`,`subuserid`,`isprebid`) values (135,30,146,1,'<p><span style=\"font-size: 10.0pt; mso-bidi-font-size: 12.0pt; line-height: 107%; font-family: \'Arial\',sans-serif; mso-fareast-font-family: Arial; color: black; mso-ansi-language: EN-US; mso-fareast-language: EN-US; mso-bidi-language: AR-SA;\">Others </span></p>','<ul>\r\n<li class=\"MsoNormal\" style=\"text-align: left;\"><span style=\"mso-bidi-font-size: 10.0pt; line-height: 107%;\"><span style=\"mso-list: Ignore;\"><span style=\"font: 7.0pt \'Times New Roman\';\">&nbsp;</span></span></span><!--[endif]-->Provision of Office Space for PMU Personnel</li>\r\n<li><span style=\"font-size: 10.0pt; mso-bidi-font-size: 12.0pt; line-height: 107%; font-family: \'Arial\',sans-serif; mso-fareast-font-family: Arial; color: black; mso-ansi-language: EN-US; mso-fareast-language: EN-US; mso-bidi-language: AR-SA;\">Project related Travel and Expense reimbursements for Project Deliverables (In &amp; Out of the State) </span></li>\r\n</ul>','<ul>\r\n<li class=\"MsoNormal\" style=\"text-align: left; line-height: 115%;\"><!-- [if !supportLists]-->Kindly clarify whether all proposed resources are required to be physically deployed full-time at Kanker district, or whether any positions may be deployed in a hybrid/need-based mode.</li>\r\n<li class=\"MsoNormal\" style=\"text-align: left; line-height: 115%;\"><!-- [if !supportLists]-->Kindly clarify whether office space, seating arrangements, internet, electricity, and basic office infrastructure for the PMU team will be provided by the DMFT, or whether the same is to be arranged by the selected agency.</li>\r\n<li class=\"MsoNormal\" style=\"text-align: left; line-height: 115%;\"><span style=\"font-size: 10.0pt; mso-bidi-font-size: 12.0pt; line-height: 107%; font-family: \'Arial\',sans-serif; mso-fareast-font-family: Arial; color: black; mso-ansi-language: EN-US; mso-fareast-language: EN-US; mso-bidi-language: AR-SA;\">Kindly clarify whether travel, local conveyance, lodging, and field visit expenses for the deployed team are to be included in the bidder&rsquo;s quote, or whether these will be reimbursed separately by the DMFT.&nbsp;</span></li>\r\n</ul>','2026-05-18 14:58:38',1,'<ol>\r\n<li>All proposed resources are required to be physically deployed full-time at Kanker district.&nbsp;</li>\r\n<li>Basic office seating and arrangements will be provided.&nbsp;</li>\r\n<li>Travel, local conveyance, lodging, and field visit expenses for the deployed team are to be included in the bidder&rsquo;s quote and will not be reimbursed separately.</li>\r\n</ol>','2026-05-29 14:16:11',NULL,1);
insert  into `eoi_request_prebid_query`(`questionid`,`queryid`,`requestid`,`vendorid`,`clause_reference`,`clause_detail`,`queries_with_justification`,`creationdate`,`iseditable`,`answer`,`answeredon`,`subuserid`,`isprebid`) values (136,30,146,1,'<p><span style=\"font-size: 10.0pt; mso-bidi-font-size: 12.0pt; line-height: 107%; font-family: \'Arial\',sans-serif; mso-fareast-font-family: Arial; color: black; mso-ansi-language: EN-US; mso-fareast-language: EN-US; mso-bidi-language: AR-SA;\">Scope of work, Page no-07 </span></p>','<p><span style=\"font-size: 10.0pt; mso-bidi-font-size: 12.0pt; line-height: 107%; font-family: \'Arial\',sans-serif; mso-fareast-font-family: Arial; color: black; mso-ansi-language: EN-US; mso-fareast-language: EN-US; mso-bidi-language: AR-SA;\">Survey sample size and coverage </span></p>','<p class=\"MsoNormal\" style=\"text-align: left; text-indent: 0in; line-height: 115%; margin: 0in 0in 1.6pt 2.0pt;\" align=\"left\">The agency is required to conduct a study in the mining-affected blocks of Kanker during the inception phase. We request to kindly clarify the expected survey/study coverage, including:</p>\r\n<ul>\r\n<li class=\"MsoNormal\" style=\"text-align: left; text-indent: 0in; line-height: 115%;\"><span style=\"font-size: 10.0pt; mso-bidi-font-size: 12.0pt; line-height: 107%; font-family: \'Arial\',sans-serif; mso-fareast-font-family: Arial; color: black; mso-ansi-language: EN-US; mso-fareast-language: EN-US; mso-bidi-language: AR-SA;\">The list of mining-affected blocks/villages to be covered under the assignment, to enable accurate planning of field activities and estimation of effort.&nbsp;</span></li>\r\n<li class=\"MsoNormal\" style=\"text-align: left; text-indent: 0in; line-height: 115%;\"><!-- [if !supportLists]-->The expected number of pilot clusters, their indicative geography/sector focus, and whether implementation costs at cluster level are part of the PMU scope or to be separately borne by the DMFT.</li>\r\n<li class=\"MsoNormal\" style=\"text-align: left; text-indent: 0in; line-height: 115%;\"><span style=\"mso-bidi-font-size: 10.0pt; line-height: 107%;\"><span style=\"mso-list: Ignore;\"><span style=\"font: 7.0pt \'Times New Roman\';\">&nbsp;</span></span></span><!--[endif]-->Number of blocks/areas to be covered,</li>\r\n<li class=\"MsoNormal\" style=\"text-align: left; text-indent: 0in; line-height: 115%;\"><span style=\"mso-bidi-font-size: 10.0pt; line-height: 107%;\"><span style=\"mso-list: Ignore;\"><span style=\"font: 7.0pt \'Times New Roman\';\">&nbsp;</span></span></span><!--[endif]-->Number of villages to be covered,</li>\r\n<li class=\"MsoNormal\" style=\"text-align: left; text-indent: 0in; line-height: 115%;\">Indicative number of households/respondents to be surveyed, and</li>\r\n<li class=\"MsoNormal\" style=\"text-align: left; text-indent: 0in; line-height: 115%;\"><span style=\"font-size: 10.0pt; mso-bidi-font-size: 12.0pt; line-height: 107%; font-family: \'Arial\',sans-serif; mso-fareast-font-family: Arial; color: black; mso-ansi-language: EN-US; mso-fareast-language: EN-US; mso-bidi-language: AR-SA;\">Estimated population universe to be considered, so that bidders may appropriately assess the level of effort and resource requirement.&nbsp;</span></li>\r\n</ul>','2026-05-18 15:00:41',1,'<ol>\r\n<li>The study during the inception phase will cover approximately 531 mining-affected villages (directly and indirectly impacted) across 4 blocks.</li>\r\n<li>Implementation costs at the cluster level will form part of the PMU scope.</li>\r\n<li>The coverage will extend to all households within these geographies, amounting to an estimated 2.6 lakh population.</li>\r\n</ol>','2026-05-29 14:58:40',NULL,1);
insert  into `eoi_request_prebid_query`(`questionid`,`queryid`,`requestid`,`vendorid`,`clause_reference`,`clause_detail`,`queries_with_justification`,`creationdate`,`iseditable`,`answer`,`answeredon`,`subuserid`,`isprebid`) values (137,30,146,1,'<p><span style=\"font-size: 10.0pt; mso-bidi-font-size: 12.0pt; line-height: 107%; font-family: \'Arial\',sans-serif; mso-fareast-font-family: Arial; color: black; mso-ansi-language: EN-US; mso-fareast-language: EN-US; mso-bidi-language: AR-SA;\">Scope of work, Page no-08</span><span style=\"font-size: 10.0pt; mso-bidi-font-size: 12.0pt; line-height: 107%; font-family: \'Aptos\',sans-serif; mso-fareast-font-family: Aptos; mso-bidi-font-family: Aptos; color: black; mso-ansi-language: EN-US; mso-fareast-language: EN-US; mso-bidi-language: AR-SA;\"> </span></p>','<p><span style=\"font-size: 10.0pt; mso-bidi-font-size: 12.0pt; line-height: 107%; font-family: \'Arial\',sans-serif; mso-fareast-font-family: Arial; color: black; mso-ansi-language: EN-US; mso-fareast-language: EN-US; mso-bidi-language: AR-SA;\">Survey methodology and tool-related expenditure</span><span style=\"font-size: 10.0pt; mso-bidi-font-size: 12.0pt; line-height: 107%; font-family: \'Aptos\',sans-serif; mso-fareast-font-family: Aptos; mso-bidi-font-family: Aptos; color: black; mso-ansi-language: EN-US; mso-fareast-language: EN-US; mso-bidi-language: AR-SA;\"> </span></p>','<p class=\"MsoNormal\" style=\"text-indent: 0in; line-height: 114%; margin: 0in 0in 0in 1.15pt; text-align: justify;\" align=\"left\">As per the given scope of work the agency is<span style=\"mso-spacerun: yes;\">&nbsp; </span>requires to do diagnostic study, mapping, gap analysis, need assessment, and consultations in mining-affected areas. In this regard, please clarify whether the cost of survey tools, questionnaires, data collection formats, tablets/mobile-based applications, travel for field enumeration, and data processing/analysis is to be included within the bidder&rsquo;s quoted PMU cost, or whether any separate&nbsp;budget/support shall be provided by the <span style=\"font-size: 10.0pt; mso-bidi-font-size: 12.0pt; line-height: 107%; font-family: \'Arial\',sans-serif; mso-fareast-font-family: Arial; color: black; mso-ansi-language: EN-US; mso-fareast-language: EN-US; mso-bidi-language: AR-SA;\">DMFT</span><span style=\"font-size: 10.0pt; mso-bidi-font-size: 12.0pt; line-height: 107%; font-family: \'Aptos\',sans-serif; mso-fareast-font-family: Aptos; mso-bidi-font-family: Aptos; color: black; mso-ansi-language: EN-US; mso-fareast-language: EN-US; mso-bidi-language: AR-SA;\"> </span></p>','2026-05-18 15:01:17',1,'<p>The cost of survey tools, questionnaires, data collection formats, tablets/mobile-based applications, travel for field enumeration, and data processing/analysis is to be included within the bidder&rsquo;s quoted PMU cost. No separate budget will be provided by the DMFT for these activities.</p>','2026-05-29 14:26:30',NULL,1);
insert  into `eoi_request_prebid_query`(`questionid`,`queryid`,`requestid`,`vendorid`,`clause_reference`,`clause_detail`,`queries_with_justification`,`creationdate`,`iseditable`,`answer`,`answeredon`,`subuserid`,`isprebid`) values (138,30,146,1,'<p><span style=\"font-size: 10.0pt; mso-bidi-font-size: 12.0pt; line-height: 107%; font-family: \'Arial\',sans-serif; mso-fareast-font-family: Arial; color: black; mso-ansi-language: EN-US; mso-fareast-language: EN-US; mso-bidi-language: AR-SA;\">Scope of work, Page no-08 </span></p>','<p class=\"MsoNormal\" style=\"text-align: left; text-indent: 0in; margin: 0in 0in .8pt 1.15pt;\" align=\"left\">FPO strengthening scope</p>','<p><span style=\"font-size: 10.0pt; mso-bidi-font-size: 12.0pt; line-height: 107%; font-family: \'Arial\',sans-serif; mso-fareast-font-family: Arial; color: black; mso-ansi-language: EN-US; mso-fareast-language: EN-US; mso-bidi-language: AR-SA;\">Kindly clarify the number of existing/proposed FPOs or producer groups expected to be supported under this assignment, and whether any direct financial support to such institutions will be managed separately by DMFT.</span></p>','2026-05-18 15:01:49',1,'<p>At present, support is envisaged for approximately two Farmer Producer Organizations (FPOs) under this assignment. However, given the increasing government focus on strengthening producer institutions, there is scope for additional FPOs or producer groups to be included during the course of implementation.</p>','2026-05-29 15:13:25',NULL,1);
insert  into `eoi_request_prebid_query`(`questionid`,`queryid`,`requestid`,`vendorid`,`clause_reference`,`clause_detail`,`queries_with_justification`,`creationdate`,`iseditable`,`answer`,`answeredon`,`subuserid`,`isprebid`) values (139,30,146,1,'<p><span style=\"font-size: 10.0pt; mso-bidi-font-size: 12.0pt; line-height: 107%; font-family: \'Arial\',sans-serif; mso-fareast-font-family: Arial; color: black; mso-ansi-language: EN-US; mso-fareast-language: EN-US; mso-bidi-language: AR-SA;\">Scope of work, Page no-08 </span></p>','<p class=\"MsoNormal\" style=\"text-align: left; text-indent: 0in; margin: 0in 0in .8pt 1.15pt;\" align=\"left\">Data access and departmental support</p>','<p style=\"text-align: justify;\"><span style=\"font-size: 10.0pt; mso-bidi-font-size: 12.0pt; line-height: 107%; font-family: \'Arial\',sans-serif; mso-fareast-font-family: Arial; color: black; mso-ansi-language: EN-US; mso-fareast-language: EN-US; mso-bidi-language: AR-SA;\">Kindly clarify whether the DMFT will facilitate access to departmental data, scheme records, village-level information, and coordination with line departments for smooth execution of the assignment. </span></p>','2026-05-18 15:02:36',1,'<p>The DMFT will extend necessary facilitation for smooth execution of the assignment. This includes access to departmental data, scheme records, and village-level information, as well as coordination support with line departments wherever required</p>','2026-05-29 14:31:47',NULL,1);
insert  into `eoi_request_prebid_query`(`questionid`,`queryid`,`requestid`,`vendorid`,`clause_reference`,`clause_detail`,`queries_with_justification`,`creationdate`,`iseditable`,`answer`,`answeredon`,`subuserid`,`isprebid`) values (140,30,146,1,'<p><span style=\"font-size: 10.0pt; mso-bidi-font-size: 12.0pt; line-height: 107%; font-family: \'Arial\',sans-serif; mso-fareast-font-family: Arial; color: black; mso-ansi-language: EN-US; mso-fareast-language: EN-US; mso-bidi-language: AR-SA;\">Scope of work, Page no-08 </span></p>','<p class=\"MsoNormal\" style=\"text-align: left; text-indent: 0in; margin: 0in 0in .8pt 1.15pt;\" align=\"left\">Scope of implementation support for flagship schemes</p>','<p class=\"MsoNormal\" style=\"text-indent: 0in; line-height: 115%; margin: 0in 0in 0in 1.15pt; text-align: justify;\" align=\"left\">Kindly specify which major flagship schemes are envisaged under this scope, and whether the selected PMU agency is <span style=\"font-size: 10.0pt; mso-bidi-font-size: 12.0pt; line-height: 107%; font-family: \'Arial\',sans-serif; mso-fareast-font-family: Arial; color: black; mso-ansi-language: EN-US; mso-fareast-language: EN-US; mso-bidi-language: AR-SA;\">expected to provide only coordination/advisory support or also onground implementation assistance.&nbsp;</span></p>','2026-05-18 15:03:49',1,'<p>The scope of work will encompass major flagship programs of both the Central and State Governments, covering areas such as livelihoods, rural development, agriculture, health, and social welfare. The selected PMU agency will primarily provide coordination and advisory support; however, in certain cases, on-ground assistance may also be required depending on the contextual needs of the assignment.</p>','2026-05-29 14:36:37',NULL,1);
insert  into `eoi_request_prebid_query`(`questionid`,`queryid`,`requestid`,`vendorid`,`clause_reference`,`clause_detail`,`queries_with_justification`,`creationdate`,`iseditable`,`answer`,`answeredon`,`subuserid`,`isprebid`) values (141,30,146,1,'<p><span style=\"font-size: 10.0pt; mso-bidi-font-size: 12.0pt; line-height: 107%; font-family: \'Arial\',sans-serif; mso-fareast-font-family: Arial; color: black; mso-ansi-language: EN-US; mso-fareast-language: EN-US; mso-bidi-language: AR-SA;\">Scope of work, Page no-08 </span></p>','<p><span style=\"font-size: 10.0pt; mso-bidi-font-size: 12.0pt; line-height: 107%; font-family: \'Arial\',sans-serif; mso-fareast-font-family: Arial; color: black; mso-ansi-language: EN-US; mso-fareast-language: EN-US; mso-bidi-language: AR-SA;\">Subcontracting / engagement of third-party agency for survey </span></p>','<ul>\r\n<li class=\"MsoNormal\" style=\"text-align: left; line-height: 115%;\">Please clarify whether the agency may subcontract/engage a specialized field survey agency for conducting largescale primary surveys, if required. If subcontracting is permitted, kindly specify the applicable conditions, approval process, and whether such cost would be reimbursable or borne within the bidder&rsquo;s overall contract value. <strong style=\"mso-bidi-font-weight: normal;\"><span style=\"font-size: 12.0pt; line-height: 115%; font-family: \'Aptos\',sans-serif; mso-fareast-font-family: Aptos; mso-bidi-font-family: Aptos;\">Or</span></strong><span style=\"font-size: 12.0pt; line-height: 115%; font-family: \'Aptos\',sans-serif; mso-fareast-font-family: Aptos; mso-bidi-font-family: Aptos;\"> </span></li>\r\n<li class=\"MsoNormal\" style=\"text-align: left; line-height: 117%;\">Whether the survey/study is expected to be undertaken directly by the selected PMU agency <strong style=\"mso-bidi-font-weight: normal;\">Or</strong><span style=\"font-size: 12.0pt; line-height: 117%; font-family: \'Aptos\',sans-serif; mso-fareast-font-family: Aptos; mso-bidi-font-family: Aptos;\">&nbsp;</span></li>\r\n<li class=\"MsoNormal\" style=\"text-align: left; line-height: 117%;\"><!-- [if !supportLists]-->Whether a separate agency will be appointed by the client/DMFT for field survey execution, and<span style=\"font-size: 12.0pt; line-height: 117%; font-family: \'Aptos\',sans-serif; mso-fareast-font-family: Aptos; mso-bidi-font-family: Aptos;\"> </span></li>\r\n<li><span style=\"font-size: 10.0pt; mso-bidi-font-size: 12.0pt; line-height: 107%; font-family: \'Arial\',sans-serif; mso-fareast-font-family: Arial; color: black; mso-ansi-language: EN-US; mso-fareast-language: EN-US; mso-bidi-language: AR-SA;\">If the PMU agency is required to undertake the survey directly, whether the DMFT will provide additional financial support for field investigation and enumeration beyond the PMU manpower cost.</span><span style=\"font-size: 12.0pt; line-height: 107%; font-family: \'Aptos\',sans-serif; mso-fareast-font-family: Aptos; mso-bidi-font-family: Aptos; color: black; mso-ansi-language: EN-US; mso-fareast-language: EN-US; mso-bidi-language: AR-SA;\"> </span></li>\r\n</ul>','2026-05-18 15:05:12',1,'<ol>\r\n<li>The responsibility for completing the survey/study will lie entirely with the selected agency. The agency will remain fully accountable for ensuring that the process is credible, and that no confidential or sensitive information is compromised at any stage.&nbsp; </li>\r\n<li>The DMFT will not provide additional financial support for field investigation and enumeration beyond the PMU manpower cost. The responsibility for managing such activities and associated expenses will lie with the selected agency under the overall contract value.</li>\r\n</ol>','2026-05-29 15:34:41',NULL,1);
insert  into `eoi_request_prebid_query`(`questionid`,`queryid`,`requestid`,`vendorid`,`clause_reference`,`clause_detail`,`queries_with_justification`,`creationdate`,`iseditable`,`answer`,`answeredon`,`subuserid`,`isprebid`) values (142,30,146,1,'<p><span style=\"font-size: 10.0pt; mso-bidi-font-size: 12.0pt; line-height: 107%; font-family: \'Arial\',sans-serif; mso-fareast-font-family: Arial; color: black; mso-ansi-language: EN-US; mso-fareast-language: EN-US; mso-bidi-language: AR-SA;\">Scope of work, Page no-08 </span></p>','<p><span style=\"font-size: 10.0pt; mso-bidi-font-size: 12.0pt; line-height: 107%; font-family: \'Arial\',sans-serif; mso-fareast-font-family: Arial; color: black; mso-ansi-language: EN-US; mso-fareast-language: EN-US; mso-bidi-language: AR-SA;\">Exposure visits, webinars, and capacity-building workshops </span></p>','<p class=\"MsoNormal\" style=\"text-indent: 0in; line-height: 115%; margin: 0in 0in 15.5pt 5.4pt; text-align: justify;\" align=\"left\">The scope of work includes conducting webinars and online capacity-building workshops with organizations and practitioners of national/state repute, and also covers training and capacity-building responsibilities under the proposed team structure . In this context, we kindly request clarification on the following:</p>\r\n<ul>\r\n<li class=\"MsoNormal\" style=\"text-align: left;\"><!-- [if !supportLists]-->The indicative number of exposure&nbsp;visits, if any, to be organized&nbsp;during the contract period;</li>\r\n<li class=\"MsoNormal\" style=\"text-align: left; line-height: 100%;\"><!-- [if !supportLists]-->The expected number of capacitybuilding workshops/trainings to be held at district, block, and village levels; and</li>\r\n<li class=\"MsoNormal\" style=\"text-indent: 0in; line-height: 115%; text-align: justify;\"><span style=\"font-size: 10.0pt; mso-bidi-font-size: 12.0pt; line-height: 107%; font-family: \'Arial\',sans-serif; mso-fareast-font-family: Arial; color: black; mso-ansi-language: EN-US; mso-fareast-language: EN-US; mso-bidi-language: AR-SA;\">Whether the related costs, including venue, logistics, travel, accommodation, honorarium/resource persons, training materials, and digital platform charges, are to be borne by the selected bidder or will be separately provided/reimbursed by the client/DMFT.<span style=\"font-size: 11.0pt; mso-bidi-font-size: 12.0pt; line-height: 107%; font-family: \'Aptos\',sans-serif; mso-fareast-font-family: Aptos; mso-bidi-font-family: Aptos; color: black; mso-ansi-language: EN-US; mso-fareast-language: EN-US; mso-bidi-language: AR-SA;\"> </span></span></li>\r\n</ul>','2026-05-18 15:06:58',1,'<p>The number of exposure visits, capacity-building workshops, and trainings to be organized during the contract period will be determined based on the evolving needs of the project and the contextual requirements at district, block, and village levels. The Project Review Committee may advise on the frequency and scale of such activities as the assignment progresses. Related costs, logistics, travel, accommodation, honorarium for resource persons, training materials, and digital platform charges, are expected to be managed within the bidder&rsquo;s quoted PMU cost. A flexible approach will be adopted to ensure that the activities remain relevant and responsive to the objectives of the engagement.</p>\r\n<div>&nbsp;</div>','2026-05-29 15:00:03',NULL,1);
insert  into `eoi_request_prebid_query`(`questionid`,`queryid`,`requestid`,`vendorid`,`clause_reference`,`clause_detail`,`queries_with_justification`,`creationdate`,`iseditable`,`answer`,`answeredon`,`subuserid`,`isprebid`) values (143,30,146,1,'<p><span style=\"font-size: 10.0pt; mso-bidi-font-size: 12.0pt; line-height: 107%; font-family: \'Arial\',sans-serif; mso-fareast-font-family: Arial; color: black; mso-ansi-language: EN-US; mso-fareast-language: EN-US; mso-bidi-language: AR-SA;\">Scope of work, Page no-08 </span></p>','<p><span style=\"font-size: 10.0pt; mso-bidi-font-size: 12.0pt; line-height: 107%; font-family: \'Arial\',sans-serif; mso-fareast-font-family: Arial; color: black; mso-ansi-language: EN-US; mso-fareast-language: EN-US; mso-bidi-language: AR-SA;\">Clarification on MIS scope and cost responsibility </span></p>','<p class=\"MsoNormal\" style=\"text-align: left; text-indent: 0in; line-height: 115%; margin: 0in 0in 15.5pt 0in;\" align=\"left\">EOI explicitly includes &ldquo;Develop and operationalize a robust Management Information System (MIS)&rdquo; under Monitoring, MIS, and Sustainability and also provides for an MIS Expert role responsible for digital data capture, MIS reporting, and database maintenance. We request to kindly clarify whether:</p>\r\n<p class=\"MsoNormal\" style=\"text-align: left; text-indent: 0in; line-height: 115%; margin: 0in 0in 15.5pt 0in;\" align=\"left\">&nbsp;</p>\r\n<p class=\"MsoNormal\" style=\"text-align: left; line-height: 115%; mso-list: l0 level1 lfo1; margin: 0in 0in 15.5pt .5in;\" align=\"left\"><!-- [if !supportLists]--><span style=\"mso-bidi-font-size: 10.0pt; line-height: 115%;\"><span style=\"mso-list: Ignore;\">&bull;<span style=\"font: 7.0pt \'Times New Roman\';\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></span></span><!--[endif]-->The selected PMU agency is expected only to provide advisory/functional support for MIS design, reporting formats, and monitoring framework, or</p>\r\n<p class=\"MsoNormal\" style=\"text-align: left; line-height: 115%; mso-list: l0 level1 lfo1; margin: 0in 0in 13.8pt .5in;\" align=\"left\"><!-- [if !supportLists]--><span style=\"mso-bidi-font-size: 10.0pt; line-height: 115%;\"><span style=\"mso-list: Ignore;\">&bull;<span style=\"font: 7.0pt \'Times New Roman\';\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></span></span><!--[endif]-->The selected PMU agency is also expected to undertake end-to-end development, deployment, hosting, and maintenance of the MIS platform/software.</p>\r\n<p class=\"MsoNormal\" style=\"line-height: 115%; margin: 0in 0in 13.8pt 0.5in; text-align: justify;\" align=\"left\"><span style=\"font-size: 10.0pt; mso-bidi-font-size: 12.0pt; line-height: 107%; font-family: \'Arial\',sans-serif; mso-fareast-font-family: Arial; color: black; mso-ansi-language: EN-US; mso-fareast-language: EN-US; mso-bidi-language: AR-SA;\">Further, in case the PMU agency is required to develop and operationalize the MIS platform, kindly clarify whether the full cost of software development, licensing, hosting, maintenance, and related IT infrastructure will be separately borne by the DMFT, since such costs may not be covered under standard PMU manpowerbased payments described in the EOI.&nbsp;</span></p>','2026-05-18 15:08:27',1,'<p>The selected PMU agency will be expected to support the development and operationalization of the MIS as outlined in the scope of work. The extent of responsibilities, whether advisory or end‑to‑end technical execution, will depend on project requirements as they evolve. Costs related to software, hosting, and IT infrastructure are generally to be managed within the overall assignment framework, with specific modalities clarified during implementation.</p>','2026-05-29 15:02:43',NULL,1);
insert  into `eoi_request_prebid_query`(`questionid`,`queryid`,`requestid`,`vendorid`,`clause_reference`,`clause_detail`,`queries_with_justification`,`creationdate`,`iseditable`,`answer`,`answeredon`,`subuserid`,`isprebid`) values (144,30,146,1,'<p><span style=\"font-size: 10.0pt; mso-bidi-font-size: 12.0pt; line-height: 107%; font-family: \'Arial\',sans-serif; mso-fareast-font-family: Arial; color: black; mso-ansi-language: EN-US; mso-fareast-language: EN-US; mso-bidi-language: AR-SA;\">Scope of work, Page no-08 </span></p>','<p><span style=\"font-size: 10.0pt; mso-bidi-font-size: 12.0pt; line-height: 107%; font-family: \'Arial\',sans-serif; mso-fareast-font-family: Arial; color: black; mso-ansi-language: EN-US; mso-fareast-language: EN-US; mso-bidi-language: AR-SA;\">Clarification on nature of assignment </span></p>','<p class=\"MsoNormal\" style=\"text-indent: 0in; line-height: 114%; margin: 0in 0in 0.05pt; text-align: justify;\" align=\"left\">EOI states that the PMU shall support/assist the department in conceptualizing, designing, and <span style=\"font-size: 10.0pt; mso-bidi-font-size: 12.0pt; line-height: 107%; font-family: \'Arial\',sans-serif; mso-fareast-font-family: Arial; color: black; mso-ansi-language: EN-US; mso-fareast-language: EN-US; mso-bidi-language: AR-SA;\">implementation of strategies and initiatives </span><span style=\"font-size: 10.0pt; mso-bidi-font-size: 12.0pt; line-height: 107%; font-family: \'Aptos\',sans-serif; mso-fareast-font-family: Aptos; mso-bidi-font-family: Aptos; color: black; mso-ansi-language: EN-US; mso-fareast-language: EN-US; mso-bidi-language: AR-SA;\">and</span><span style=\"font-size: 10.0pt; mso-bidi-font-size: 12.0pt; line-height: 107%; font-family: \'Arial\',sans-serif; mso-fareast-font-family: Arial; color: black; mso-ansi-language: EN-US; mso-fareast-language: EN-US; mso-bidi-language: AR-SA;\"> the team roles largely indicate planning, coordination, advisory, convergence, training, and reporting responsibilities. We request clarification on whether the selected agency&rsquo;s role is intended to remain primarily advisory/PMUoriented, or whether it will also be responsible for direct implementation of activities such as survey execution, MIS platform development, trainings, exposure visits, and other operational components. This clarification will help bidders estimate scope, staffing, and costing accurately.&nbsp;</span></p>','2026-05-18 15:09:57',1,'<p>The role of the selected agency will remain primarily advisory and PMU‑oriented, focusing on planning, coordination, convergence, training, and reporting responsibilities. However, where survey execution or similar activities form an integral part of the planning process, the agency will also be responsible for undertaking such implementation directly. Operational components like surveys, trainings, exposure visits, or MIS support may therefore be required as part of the PMU&rsquo;s scope, depending on project needs.</p>\r\n<div>&nbsp;</div>','2026-05-29 15:05:49',NULL,1);
insert  into `eoi_request_prebid_query`(`questionid`,`queryid`,`requestid`,`vendorid`,`clause_reference`,`clause_detail`,`queries_with_justification`,`creationdate`,`iseditable`,`answer`,`answeredon`,`subuserid`,`isprebid`) values (145,30,146,1,'<p><span style=\"font-size: 10.0pt; mso-bidi-font-size: 12.0pt; line-height: 107%; font-family: \'Arial\',sans-serif; mso-fareast-font-family: Arial; color: black; mso-ansi-language: EN-US; mso-fareast-language: EN-US; mso-bidi-language: AR-SA;\">Scope of work, Page no-08 </span></p>','<p class=\"MsoNormal\" style=\"text-align: left; text-indent: 0in; margin: 0in 0in .75pt 0in;\" align=\"left\"><strong style=\"mso-bidi-font-weight: normal;\">Deliverable approval mechanism </strong></p>','<p style=\"text-align: justify;\"><span style=\"font-size: 10.0pt; mso-bidi-font-size: 12.0pt; line-height: 107%; font-family: \'Arial\',sans-serif; mso-fareast-font-family: Arial; color: black; mso-ansi-language: EN-US; mso-fareast-language: EN-US; mso-bidi-language: AR-SA;\">Kindly clarify the deliverable review and approval mechanism, including the competent approving authority, indicative review timelines, and whether deemed approval will apply if comments are not received within a specified period.</span></p>','2026-05-18 15:10:42',1,'<p>Deliverables will be reviewed and approved by the Project Monitoring Committee. The review timelines and process will be guided by project requirements and may vary depending on the nature of the deliverable.</p>','2026-05-29 15:07:14',NULL,1);
insert  into `eoi_request_prebid_query`(`questionid`,`queryid`,`requestid`,`vendorid`,`clause_reference`,`clause_detail`,`queries_with_justification`,`creationdate`,`iseditable`,`answer`,`answeredon`,`subuserid`,`isprebid`) values (146,31,146,2,'<p>Clause:6, page number: 11 as per document serial number chronology.</p>','<p>Duration and Resource Deployment Plan for the Assignment: Initial Contract Period for the project shall be 12 months extendable (if required) further for two years with mutual consent.</p>','<p>We are requesting to please consider at least two years initial duration with possible extension of one more year. It will help in mobilising quality resources and also ensure longer statibilty to the proposed resources.</p>','2026-05-18 15:31:14',1,'<p>The request for an initial duration of two years, with the possibility of extension by one additional year, is acknowledged and accepted.</p>','2026-05-29 15:08:32',NULL,1);
insert  into `eoi_request_prebid_query`(`questionid`,`queryid`,`requestid`,`vendorid`,`clause_reference`,`clause_detail`,`queries_with_justification`,`creationdate`,`iseditable`,`answer`,`answeredon`,`subuserid`,`isprebid`) values (147,32,144,2,'<p><span style=\"font-size: 10.0pt; font-family: \'Arial\',sans-serif; mso-ascii-theme-font: minor-latin; mso-fareast-font-family: \'Times New Roman\'; mso-hansi-theme-font: minor-latin; mso-bidi-theme-font: minor-latin; mso-ansi-language: #1000; mso-fareast-language: EN-US; mso-bidi-language: AR-SA;\">Section 3.1 &ndash; Scope of Work, Pg. 5&ndash;6</span></p>','<p><span style=\"font-size: 10.0pt; font-family: \'Arial\',sans-serif; mso-ascii-theme-font: minor-latin; mso-fareast-font-family: \'Times New Roman\'; mso-hansi-theme-font: minor-latin; mso-bidi-theme-font: minor-latin; mso-ansi-language: #1000; mso-fareast-language: EN-US; mso-bidi-language: AR-SA;\">Preparation of Ramsar Information Sheets (RIS) and Integrated Management Plans for at least 5 wetlands</span></p>','<p><span style=\"font-size: 10.0pt; font-family: \'Arial\',sans-serif; mso-ascii-theme-font: minor-latin; mso-fareast-font-family: \'Times New Roman\'; mso-hansi-theme-font: minor-latin; mso-bidi-theme-font: minor-latin; mso-ansi-language: #1000; mso-fareast-language: EN-US; mso-bidi-language: AR-SA;\">Please confirm whether these wetlands are pre-identified by the Authority or need to be identified by the consultant. This is critical to understand scope boundaries and effort estimation.</span></p>','2026-05-18 16:30:23',1,'<p>The information related to these wetlands is preidentified by the Authority.</p>','2026-05-25 17:14:10',NULL,1);
insert  into `eoi_request_prebid_query`(`questionid`,`queryid`,`requestid`,`vendorid`,`clause_reference`,`clause_detail`,`queries_with_justification`,`creationdate`,`iseditable`,`answer`,`answeredon`,`subuserid`,`isprebid`) values (148,32,144,2,'<p><span style=\"font-size: 10.0pt; font-family: \'Arial\',sans-serif; mso-ascii-theme-font: minor-latin; mso-fareast-font-family: \'Times New Roman\'; mso-hansi-theme-font: minor-latin; mso-bidi-theme-font: minor-latin; mso-ansi-language: #1000; mso-fareast-language: EN-US; mso-bidi-language: AR-SA;\">Section 3.1 &ndash; Scope of Work, Pg. 6</span></p>','<p><span style=\"font-size: 10.0pt; font-family: \'Arial\',sans-serif; mso-ascii-theme-font: minor-latin; mso-fareast-font-family: \'Times New Roman\'; mso-hansi-theme-font: minor-latin; mso-bidi-theme-font: minor-latin; mso-ansi-language: #1000; mso-fareast-language: EN-US; mso-bidi-language: AR-SA;\">Capacity building and training (Wetland Mitras, eco-guides)</span></p>','<p><span style=\"font-size: 10.0pt; font-family: \'Arial\',sans-serif; mso-ascii-theme-font: minor-latin; mso-fareast-font-family: \'Times New Roman\'; mso-hansi-theme-font: minor-latin; mso-bidi-theme-font: minor-latin; mso-ansi-language: #1000; mso-fareast-language: EN-US; mso-bidi-language: AR-SA;\">For training and capacity building (Wetland Mitras, eco-guides, etc.), is there any defined number of trainings expected under the assignment? Please clarify whether the consultant is expected to budget for the logistical requirements (e.g. Venue, food, etc) in their financial proposal.</span></p>','2026-05-18 16:30:47',1,'<div class=\"qMYqUG_convSearchResultHighlightRoot\">\r\n<div class=\"\" data-turn-id-container=\"request-WEB:187976b7-a9dc-4c62-8b9d-399c2c15c65f-0\" data-is-intersecting=\"true\">\r\n<section class=\"text-token-text-primary w-full focus:outline-none has-data-writing-block:pointer-events-none [&amp;:has([data-writing-block])&gt;*]:pointer-events-auto R6Vx5W_threadScrollVars scroll-mb-[calc(var(--scroll-root-safe-area-inset-bottom,0px)+var(--thread-response-height))] scroll-mt-[calc(var(--header-height)+min(200px,max(70px,20svh)))]\" dir=\"auto\" data-turn-id=\"request-WEB:187976b7-a9dc-4c62-8b9d-399c2c15c65f-0\" data-turn-id-container=\"request-WEB:187976b7-a9dc-4c62-8b9d-399c2c15c65f-0\" data-testid=\"conversation-turn-2\" data-scroll-anchor=\"false\" data-turn=\"assistant\">\r\n<div class=\"text-base my-auto mx-auto pb-10 [--thread-content-margin:var(--thread-content-margin-xs,calc(var(--spacing)*4))] @w-sm/main:[--thread-content-margin:var(--thread-content-margin-sm,calc(var(--spacing)*6))] @w-lg/main:[--thread-content-margin:var(--thread-content-margin-lg,calc(var(--spacing)*16))] px-(--thread-content-margin)\">\r\n<div class=\"[--thread-content-max-width:40rem] @w-lg/main:[--thread-content-max-width:48rem] mx-auto max-w-(--thread-content-max-width) flex-1 group/turn-messages focus-visible:outline-hidden relative flex w-full min-w-0 flex-col agent-turn\">\r\n<div class=\"flex max-w-full flex-col gap-4 grow\">\r\n<div class=\"min-h-8 text-message relative flex w-full flex-col items-end gap-2 text-start break-words whitespace-normal outline-none keyboard-focused:focus-ring [.text-message+&amp;]:mt-1\" dir=\"auto\" tabindex=\"0\" data-message-author-role=\"assistant\" data-message-id=\"d1388950-4a25-448e-b5da-c9c42310dee7\" data-message-model-slug=\"gpt-5-5\" data-turn-start-message=\"true\">\r\n<div class=\"flex w-full flex-col gap-1 empty:hidden\">\r\n<div class=\"markdown prose dark:prose-invert wrap-break-word w-full light markdown-new-styling\">\r\n<p data-start=\"0\" data-end=\"137\" data-is-last-node=\"\" data-is-only-node=\"\">There is no fixed number of trainings; they will be conducted based on need. The Authority will provide all necessary logistical support.</p>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n<div class=\"z-0 flex min-h-[46px] justify-start\">&nbsp;</div>\r\n</div>\r\n</div>\r\n</section>\r\n</div>\r\n</div>\r\n<div class=\"pointer-events-none -mt-px h-px translate-y-[calc(var(--scroll-root-safe-area-inset-bottom)-14*var(--spacing))]\" aria-hidden=\"true\">&nbsp;</div>','2026-05-26 16:43:55',NULL,1);
insert  into `eoi_request_prebid_query`(`questionid`,`queryid`,`requestid`,`vendorid`,`clause_reference`,`clause_detail`,`queries_with_justification`,`creationdate`,`iseditable`,`answer`,`answeredon`,`subuserid`,`isprebid`) values (149,32,144,2,'<p><span style=\"font-size: 10.0pt; font-family: \'Arial\',sans-serif; mso-ascii-theme-font: minor-latin; mso-fareast-font-family: \'Times New Roman\'; mso-hansi-theme-font: minor-latin; mso-bidi-theme-font: minor-latin; mso-ansi-language: #1000; mso-fareast-language: EN-US; mso-bidi-language: AR-SA;\">Section 3 &ndash; Scope of Work, Pg. 6</span></p>','<p><span style=\"font-size: 10.0pt; font-family: \'Arial\',sans-serif; mso-ascii-theme-font: minor-latin; mso-fareast-font-family: \'Times New Roman\'; mso-hansi-theme-font: minor-latin; mso-bidi-theme-font: minor-latin; mso-ansi-language: #1000; mso-fareast-language: EN-US; mso-bidi-language: AR-SA;\">Preparation of LBSAPs at Panchayat level</span></p>','<p><span style=\"font-size: 10.0pt; font-family: \'Arial\',sans-serif; mso-ascii-theme-font: minor-latin; mso-fareast-font-family: \'Times New Roman\'; mso-hansi-theme-font: minor-latin; mso-bidi-theme-font: minor-latin; mso-ansi-language: #1000; mso-fareast-language: EN-US; mso-bidi-language: AR-SA;\">For preparation of Local Biodiversity Strategy and Action Plans (LBSAPs) at Panchayat level, please clarify the expected number of Panchayats/BMCs to be covered.</span></p>','2026-05-18 16:31:12',1,'<p>At least 5 BMCs should be selected in each forest Division of Chhattisgarh for the Local Biodiversity Strategy and Action Plan. Total Forest Division in C.G. is 33.</p>','2026-05-25 17:23:35',NULL,1);
insert  into `eoi_request_prebid_query`(`questionid`,`queryid`,`requestid`,`vendorid`,`clause_reference`,`clause_detail`,`queries_with_justification`,`creationdate`,`iseditable`,`answer`,`answeredon`,`subuserid`,`isprebid`) values (150,32,144,2,'<p><span style=\"font-size: 10.0pt; font-family: \'Arial\',sans-serif; mso-ascii-theme-font: minor-latin; mso-fareast-font-family: \'Times New Roman\'; mso-hansi-theme-font: minor-latin; mso-bidi-theme-font: minor-latin; mso-ansi-language: #1000; mso-fareast-language: EN-US; mso-bidi-language: AR-SA;\">Section 4 &ndash; Team Composition, Pg. 6&ndash;8</span></p>','<p><span style=\"font-size: 10.0pt; font-family: \'Arial\',sans-serif; mso-ascii-theme-font: minor-latin; mso-fareast-font-family: \'Times New Roman\'; mso-hansi-theme-font: minor-latin; mso-bidi-theme-font: minor-latin; mso-ansi-language: #1000; mso-fareast-language: EN-US; mso-bidi-language: AR-SA;\">Team deployment (12 months, 4 experts)</span></p>','<p><span style=\"font-size: 10.0pt; font-family: \'Arial\',sans-serif; mso-ascii-theme-font: minor-latin; mso-fareast-font-family: \'Times New Roman\'; mso-hansi-theme-font: minor-latin; mso-bidi-theme-font: minor-latin; mso-ansi-language: #1000; mso-fareast-language: EN-US; mso-bidi-language: AR-SA;\">Please confirm whether all proposed experts are required to be deployed full-time in Chhattisgarh for the entire 12-month duration or if intermittent/need-based deployment is acceptable.</span></p>','2026-05-18 16:31:34',1,'<p>All the experts are required to be deployed full-time in Chhattisgarh for the entire 12-month duration.</p>','2026-05-25 17:25:38',NULL,1);
insert  into `eoi_request_prebid_query`(`questionid`,`queryid`,`requestid`,`vendorid`,`clause_reference`,`clause_detail`,`queries_with_justification`,`creationdate`,`iseditable`,`answer`,`answeredon`,`subuserid`,`isprebid`) values (151,33,144,3,'<p>3.1. Proposed Scope of<br>Work (Wetlands) &amp; Page no: 5</p>','<p>Linking hydrology with<br>ecosystem service assessments<br>and management planning skills<br>in advanced spatial analysis,<br>hydrological-hydrodynamic<br>modeling, and climate scenario<br>integration</p>','<p>We understand that the client shall provide access to spatial datasets<br>(e.g., satellite imagery, topographic maps), Kindly Confirm.<br>Alternatively, if the PMU shall be required to procure these data sets,<br>then shall these costs be reimbursed to the PMU?</p>','2026-05-18 16:32:29',1,'<p>As per the need, the data will be provided by the authority. The data available in the public domain or that can be obtained without any financial cost is expected to be arranged by the PMU.</p>','2026-05-26 16:47:24',NULL,1);
insert  into `eoi_request_prebid_query`(`questionid`,`queryid`,`requestid`,`vendorid`,`clause_reference`,`clause_detail`,`queries_with_justification`,`creationdate`,`iseditable`,`answer`,`answeredon`,`subuserid`,`isprebid`) values (152,33,144,3,'<p>3.1. Proposed Scope of<br>Work (Wetlands) &amp; Page no: 5</p>','<p>Concept, formulation, and<br>implementation of technical<br>design for soil and water<br>conservation<br>Formulation and<br>implementation of technical<br>design for planning,<br>implementation, and<br>monitoring related to field<br>erosion, water quality,<br>sedimentation, and<br>microplastics in wetlands<br>Design and deliver technical<br>capacity-building<br>programmes</p>','<p>We understand that the PMU shall be responsible to provide advisory<br>guidance/inputs rather than take up detailed engineering design and<br>execution responsibilities for activities pertaining to technical design<br>and implementation for soil and water conservation, erosion control,<br>and wetland management.<br>Kindly confirm this understanding.</p>','2026-05-18 16:33:32',1,'<p>PMW shall be responsible for all technical and engineering design for wetlands, soil and water conservation, and will not be in charge of execution duties.</p>','2026-05-26 17:03:24',NULL,1);
insert  into `eoi_request_prebid_query`(`questionid`,`queryid`,`requestid`,`vendorid`,`clause_reference`,`clause_detail`,`queries_with_justification`,`creationdate`,`iseditable`,`answer`,`answeredon`,`subuserid`,`isprebid`) values (153,33,144,3,'<p>3.2.Perspective &amp; Action<br>Plans &amp; Page no: 6</p>','<p>To identify and evaluate potential<br>products for Geographical<br>Indication (GI) registration in<br>Chhattisgarh, and to provide<br>comprehensive technical<br>assistance for securing new GI<br>tags.</p>','<p>We request the client to please clarify the scope of technical<br>assistance expected for GI registration ?</p>','2026-05-18 16:34:27',1,'<p>From identifying the potential products to preparing a concept note for making an application, and then getting the registration done.</p>','2026-05-25 18:33:02',NULL,1);
insert  into `eoi_request_prebid_query`(`questionid`,`queryid`,`requestid`,`vendorid`,`clause_reference`,`clause_detail`,`queries_with_justification`,`creationdate`,`iseditable`,`answer`,`answeredon`,`subuserid`,`isprebid`) values (154,33,144,3,'<p>Team Composition &amp; Page no: 6</p>','<p>Column # 3 of the table:<br>Experience requirements stated<br>as \"preferable\" vs. CHIPS<br>empanelment mapping</p>','<p>There appears to be a discrepancy between the &lsquo;preferred&rsquo; experience<br>outlined in the EOI and the experience benchmarks associated with<br>each position as per the CHIPS empanelment. This may lead to ambiguity&nbsp;for bidders in determining the appropriate profiles to be<br>proposed.<br>For instance, for Position 1 (Principal Consultant), the CHIPS<br>empanelment specifies a minimum experience of 7+ years, whereas<br>the subsequent level (Managing Consultant) requires 10+ years.<br>However, the EOI indicates a preference for a Principal Consultant<br>while suggesting an experience range more aligned with the Managing<br>Consultant level.<br>In view of the above, we request the client to confirm that the<br>experience requirements for all positions shall be aligned with the<br>CHIPS empanelment norms</p>','2026-05-18 16:37:29',1,'<div class=\"qMYqUG_convSearchResultHighlightRoot\">\r\n<div class=\"\" data-turn-id-container=\"request-WEB:c7209562-462d-4929-93ec-85326bd3bf88-0\" data-is-intersecting=\"true\">\r\n<section class=\"text-token-text-primary w-full focus:outline-none has-data-writing-block:pointer-events-none [&amp;:has([data-writing-block])&gt;*]:pointer-events-auto R6Vx5W_threadScrollVars scroll-mb-[calc(var(--scroll-root-safe-area-inset-bottom,0px)+var(--thread-response-height))] scroll-mt-[calc(var(--header-height)+min(200px,max(70px,20svh)))]\" dir=\"auto\" data-turn-id=\"request-WEB:c7209562-462d-4929-93ec-85326bd3bf88-0\" data-turn-id-container=\"request-WEB:c7209562-462d-4929-93ec-85326bd3bf88-0\" data-testid=\"conversation-turn-2\" data-scroll-anchor=\"false\" data-turn=\"assistant\">\r\n<div class=\"text-base my-auto mx-auto pb-10 [--thread-content-margin:var(--thread-content-margin-xs,calc(var(--spacing)*4))] @w-sm/main:[--thread-content-margin:var(--thread-content-margin-sm,calc(var(--spacing)*6))] @w-lg/main:[--thread-content-margin:var(--thread-content-margin-lg,calc(var(--spacing)*16))] px-(--thread-content-margin)\">\r\n<div class=\"[--thread-content-max-width:40rem] @w-lg/main:[--thread-content-max-width:48rem] mx-auto max-w-(--thread-content-max-width) flex-1 group/turn-messages focus-visible:outline-hidden relative flex w-full min-w-0 flex-col agent-turn\">\r\n<div class=\"flex max-w-full flex-col gap-4 grow\">\r\n<div class=\"min-h-8 text-message relative flex w-full flex-col items-end gap-2 text-start break-words whitespace-normal outline-none keyboard-focused:focus-ring [.text-message+&amp;]:mt-1\" dir=\"auto\" tabindex=\"0\" data-message-author-role=\"assistant\" data-message-id=\"e00aa739-188c-4c6a-8aba-c579286a63d5\" data-message-model-slug=\"gpt-5-5\" data-turn-start-message=\"true\">\r\n<div class=\"flex w-full flex-col gap-1 empty:hidden\">\r\n<div class=\"markdown prose dark:prose-invert wrap-break-word w-full light markdown-new-styling\">\r\n<p data-start=\"0\" data-end=\"313\" data-is-last-node=\"\" data-is-only-node=\"\">There appears to be no discrepancy in understanding the minimum qualification and experience requirements specified in the tender document. The requirement stated by CHIPS has been retained as it is, while the Authority has merely expressed its inclination toward selecting candidates possessing more relevant experience among the available pool of participants.</p>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n<div class=\"z-0 flex min-h-[46px] justify-start\">&nbsp;</div>\r\n</div>\r\n</div>\r\n</section>\r\n</div>\r\n</div>\r\n<div class=\"pointer-events-none -mt-px h-px translate-y-[calc(var(--scroll-root-safe-area-inset-bottom)-14*var(--spacing))]\" aria-hidden=\"true\">&nbsp;</div>','2026-05-26 17:25:13',NULL,1);
insert  into `eoi_request_prebid_query`(`questionid`,`queryid`,`requestid`,`vendorid`,`clause_reference`,`clause_detail`,`queries_with_justification`,`creationdate`,`iseditable`,`answer`,`answeredon`,`subuserid`,`isprebid`) values (155,33,144,3,'<p>Qualification of<br>Consultant (Position # 3): &amp; Page no: 7</p>','<p>&bull; Ph.D. in Biodiversity<br>Conservation/ Forestry<br>&bull; Preferably 10+ years of<br>experience</p>','<p>We request the inclusion of Ph.D. qualifications in allied disciplines<br>such as Zoology, Botany, and Environmental Sciences. Given that<br>biodiversity is an inherently interdisciplinary domain, relevant expertise<br>is often developed through these fields. This amendment is proposed<br>to broaden the pool of suitably qualified candidates while ensuring<br>alignment with the functional requirements of the position.</p>','2026-05-18 16:39:00',1,'<p>The request for inclusion of Ph.D. qualifications in allied disciplines such as Zoology, Botany, and Environmental Sciences has been examined. However, the Authority has decided to retain the qualification criteria as specified in the tender document. The prescribed educational qualifications have been defined keeping in view the specific functional requirements, technical scope, and domain expertise envisaged for the position. Accordingly, no modification in the eligibility criteria is considered necessary at this stage.&nbsp;</p>','2026-05-26 17:29:00',NULL,1);
insert  into `eoi_request_prebid_query`(`questionid`,`queryid`,`requestid`,`vendorid`,`clause_reference`,`clause_detail`,`queries_with_justification`,`creationdate`,`iseditable`,`answer`,`answeredon`,`subuserid`,`isprebid`) values (156,33,144,3,'<p>Team Composition -<br>Consultant (Social &<br>Other Sectors) & Page no: 8</p>','<p>Qualification requirement<br>specifies Ph.D. in Humanities<br>and Social Sciences/MSW/Rural<br>Development</p>','<p>We request clarification on whether a Ph.D. in Agriculture, with<br>relevant experience in community engagement and livelihood<br>assessment, would be considered acceptable for this position. Given<br>that agriculture plays a strong role in community livelihoods and<br>wetland-related activities, including this qualification would be an<br>added advantage and enrich the expertise available for the project.<br>We request to clarify.</p>','2026-05-18 16:40:06',1,'<p>Yes, a Ph.D. in Agronomy rather than agriculture with relevant experience in community engagement and livelihood&nbsp;assessment would be considered acceptable for this position.&nbsp;</p>','2026-05-26 17:18:22',NULL,1);
insert  into `eoi_request_prebid_query`(`questionid`,`queryid`,`requestid`,`vendorid`,`clause_reference`,`clause_detail`,`queries_with_justification`,`creationdate`,`iseditable`,`answer`,`answeredon`,`subuserid`,`isprebid`) values (157,33,144,3,'<p>Evaluation process &amp; Page no: 9</p>','<p>The marking for presentation and<br>interview shall be done as follows<br>&bull; Bidder Presentation<br>&bull; Candidate Interview</p>','<p>We request that given the specialized nature of the assignment, it is<br>suggested that the evaluation may also consider additional parameters<br>to assess the bidder&rsquo;s relevant institutional experience and capability,<br>in areas such as, biodiversity conservation, support to government<br>programs in forestry sector, etc.</p>','2026-05-18 16:41:37',1,'<p>The marking shall be as done as provided in the tender document.</p>','2026-05-26 17:14:29',NULL,1);
insert  into `eoi_request_prebid_query`(`questionid`,`queryid`,`requestid`,`vendorid`,`clause_reference`,`clause_detail`,`queries_with_justification`,`creationdate`,`iseditable`,`answer`,`answeredon`,`subuserid`,`isprebid`) values (158,34,162,5,'<p>Clause no. 7 on Page 6</p>','<p>The last date for submission of response is 09/06/2026 17:00 Hrs.. Any response received after the abovedeadline will be rejected.</p>','<p>As part of the EoI, we understand that this important assignment requires the right fit of experts over a long duration. In view of the above, we request the Authority to kindly extend the bid due date by 3 weeks from the date of response to pre bid queries.</p>','2026-05-24 12:32:57',1,'<p><span lang=\"EN-IN\" style=\"font-size: 12.0pt; line-height: 115%; font-family: \'Times New Roman\',\'serif\'; mso-fareast-font-family: Aptos; mso-fareast-theme-font: minor-latin; mso-bidi-font-family: Mangal; mso-bidi-theme-font: minor-bidi; color: black; mso-themecolor: text1; mso-ansi-language: EN-IN; mso-fareast-language: EN-US; mso-bidi-language: AR-SA;\">As per EOI document</span></p>','2026-06-02 17:12:00',NULL,1);
insert  into `eoi_request_prebid_query`(`questionid`,`queryid`,`requestid`,`vendorid`,`clause_reference`,`clause_detail`,`queries_with_justification`,`creationdate`,`iseditable`,`answer`,`answeredon`,`subuserid`,`isprebid`) values (159,34,162,5,'<p>Clause 3 Scope of Work&nbsp;<br>Page 4</p>','<p>I. Solid Waste Management (SWM) &ndash; Technical &amp; Regulatory Support</p>\r\n<p>5. Support CECB in conducting site inspections, third-party audits, and environmental compliance assessments of waste processing and disposal facilities across the State.</p>','<p>We understand that the consultant is not expected to conduct third party audits and environment impact assessments. Kindly confirm.</p>','2026-05-25 13:54:06',1,'<p><span lang=\"EN-IN\" style=\"font-size: 12.0pt; line-height: 115%; font-family: \'Times New Roman\',\'serif\'; mso-fareast-font-family: Aptos; mso-fareast-theme-font: minor-latin; mso-bidi-font-family: Mangal; mso-bidi-theme-font: minor-bidi; color: black; mso-themecolor: text1; mso-ansi-language: EN-IN; mso-fareast-language: EN-US; mso-bidi-language: AR-SA;\">As per EOI document</span></p>','2026-06-02 17:12:21',NULL,1);
insert  into `eoi_request_prebid_query`(`questionid`,`queryid`,`requestid`,`vendorid`,`clause_reference`,`clause_detail`,`queries_with_justification`,`creationdate`,`iseditable`,`answer`,`answeredon`,`subuserid`,`isprebid`) values (160,34,162,5,'<p>Clause 3 Scope of Work&nbsp;<br>Page 4</p>','<p>III. Compliance Monitoring and Coordination with Apex-Level Bodies</p>\r\n<p>12. Provide comprehensive support to CECB for preparation, compilation, and timely submission of compliance reports, action-taken reports (ATRs), status affidavits, and supporting documentation required for apex-level committees, oversight bodies, and monitoring authorities constituted under statutory or judicial mandates related to environmental compliance.</p>\r\n<p>13. Draft, review, and finalise high-quality administrative and technical submissions, replies to show cause notices, explanatory notes, and compliance undertakings as required in connection&nbsp;</p>','<p>We understand that the consultant firm is not required to provide any legal opinion and that the support required is purely technical and program management support. Kindly confirm.</p>','2026-05-25 13:55:30',1,'<p><span lang=\"EN-IN\" style=\"font-size: 12.0pt; line-height: 115%; font-family: \'Times New Roman\',\'serif\'; mso-fareast-font-family: Aptos; mso-fareast-theme-font: minor-latin; mso-bidi-font-family: Mangal; mso-bidi-theme-font: minor-bidi; color: black; mso-themecolor: text1; mso-ansi-language: EN-IN; mso-fareast-language: EN-US; mso-bidi-language: AR-SA;\">As per EOI document</span></p>','2026-06-02 17:12:41',NULL,1);
insert  into `eoi_request_prebid_query`(`questionid`,`queryid`,`requestid`,`vendorid`,`clause_reference`,`clause_detail`,`queries_with_justification`,`creationdate`,`iseditable`,`answer`,`answeredon`,`subuserid`,`isprebid`) values (161,34,162,5,'<p>Clause 4 Team Requirements<br>&nbsp;Page 4</p>','<p>Project Lead - Solid &amp; Liquid Waste Management</p>\r\n<p>&bull; &nbsp; &nbsp;B.E./ B.Tech/ M.E./ M.Tech (Civil/ Environmental/Chemical Engineering) OR M.Sc. (Environmental Science/ Chemistry/Environmental Engineering) OR Equivalent Degree from a recognized University.<br>&bull; &nbsp; &nbsp;MBA / PG Diploma in Project Management desirable.<br>&bull; &nbsp; &nbsp;Minimum 10+ Years\' relevant experience in solid and/or liquid waste management projects, preferably in government / PSU / State level assignments.</p>','<p>Considering the availability of specialists in this domain, we request you to kindly modify the requirements as below -&nbsp;</p>\r\n<p>&bull; &nbsp; &nbsp;B.E./ B.Tech/ M.E./ M.Tech (Civil/ Environmental/ Chemical Engineering) OR M.Sc. / M. Tech (Environmental Science/ Chemistry/Environmental Engineering/ Planning/ Management ) OR Equivalent Degree from a recognized University.<br>&bull; &nbsp; &nbsp;MBA / PG Diploma in Project Management is desirable.<br>&bull; &nbsp; &nbsp;Minimum 10+ years of overall experience with at least 7 years relevant experience in solid and/or liquid waste management projects, preferably in government / PSU / State level assignments.</p>','2026-05-25 13:57:44',1,'<p><span lang=\"EN-IN\" style=\"font-size: 12.0pt; line-height: 115%; font-family: \'Times New Roman\',\'serif\'; mso-fareast-font-family: Aptos; mso-fareast-theme-font: minor-latin; mso-bidi-font-family: Mangal; mso-bidi-theme-font: minor-bidi; color: black; mso-themecolor: text1; mso-ansi-language: EN-IN; mso-fareast-language: EN-US; mso-bidi-language: AR-SA;\">As per EOI document</span></p>','2026-06-02 17:13:04',NULL,1);
insert  into `eoi_request_prebid_query`(`questionid`,`queryid`,`requestid`,`vendorid`,`clause_reference`,`clause_detail`,`queries_with_justification`,`creationdate`,`iseditable`,`answer`,`answeredon`,`subuserid`,`isprebid`) values (162,34,162,5,'<p>Clause 4 Team Requirements<br>&nbsp;Page 4 &amp; 5</p>','<p>Subject Matter Expert</p>\r\n<p>&bull; &nbsp; &nbsp;B.E./ B.Tech (Civil/ Environmental/ Chemical) AND M.E./ M.Tech (Environmental/ Civil/ Chemical Engineering) OR M.Sc. (Environmental Science / Chemistry) OR Equivalent Degree from a recognized University.<br>&bull; &nbsp; &nbsp;Minimum 7+ Years\' relevant experience in solid and/or liquid waste management projects, preferably in government/ PSU / State level assignments.</p>','<p>Considering the availability of specialists in this domain, we request you to kindly modify the requirements as below -&nbsp;</p>\r\n<p>&bull; &nbsp; &nbsp;B.E./ B.Tech (Civil/ Environmental/ Chemical) OR M.E./ M.Tech (Environmental/ Civil/ Chemical Engineering) OR M.Sc. (Environmental Science / Chemistry) OR Equivalent Degree from a recognized University.<br>&bull; &nbsp; &nbsp;Minimum 7+ Years\' of overall experience with at least 4 years of relevant experience in solid and/or liquid waste management projects, preferably in government/ PSU / State level assignments.</p>','2026-05-25 13:59:12',1,'<p><span lang=\"EN-IN\" style=\"font-size: 12.0pt; line-height: 115%; font-family: \'Times New Roman\',\'serif\'; mso-fareast-font-family: Aptos; mso-fareast-theme-font: minor-latin; mso-bidi-font-family: Mangal; mso-bidi-theme-font: minor-bidi; color: black; mso-themecolor: text1; mso-ansi-language: EN-IN; mso-fareast-language: EN-US; mso-bidi-language: AR-SA;\">As per EOI document</span></p>','2026-06-02 17:13:24',NULL,1);
insert  into `eoi_request_prebid_query`(`questionid`,`queryid`,`requestid`,`vendorid`,`clause_reference`,`clause_detail`,`queries_with_justification`,`creationdate`,`iseditable`,`answer`,`answeredon`,`subuserid`,`isprebid`) values (163,34,162,5,'<p>Clause 4 Team Requirements<br>&nbsp;Page 5</p>','<p>3. Domain Expert (Compliance &amp; Subject Matter Expert)</p>\r\n<p>&bull; &nbsp; &nbsp;B.E./ B.Tech (Civil/ Environmental/ Chemical) OR LL.B. / LL.M. (Environment Law / Administrative Law) OR M.Sc.(Environmental Science) OR M.E./ M.Tech (Environmental/ Civil/ Chemical Engineering) with a PG Diploma in Environmental Law OR Equivalent Degree from a recognized University.<br>&bull; &nbsp; &nbsp;Minimum 5+ Years\' experience in environmental compliance, administrative coordination with regulatory forums, or policy advisory roles in government/NGO/consulting organizations.</p>\r\n<p>4. Domain Expert (Compliance &amp; Subject Matter Expert)<br>&bull; &nbsp; &nbsp;B.E./ B.Tech (Civil/ Environmental/ Chemical) OR LL.B. / LL.M. (Environment Law / Administrative Law) OR M.Sc.(Environmental Science) OR M.E./ M.Tech (Environmental/ Civil/ Chemical Engineering) with a PG Diploma in Environmental Law OR Equivalent Degree from a recognized University.<br>&bull; &nbsp; &nbsp;Minimum 5+ Years\' experience in environmental compliance, administrative coordination with regulatory forums, or policy advisory roles in government/NGO/consulting organizations.</p>','<p>We have observed that the Authority is seeking two experts with the same qualification. Considering the scope of work of the PMU, we believe that it would be essential to have one program management expert along with one Domain Expert.</p>\r\n<p>In view of the above, we request the Authority to kindly change the 3rd and 4th expert requirement as follows &ndash;&nbsp;</p>\r\n<p>3. Domain Expert (Compliance &amp; Subject Matter Expert)<br>&bull; &nbsp; &nbsp;B.E./ B.Tech (Civil/ Environmental/ Chemical) OR LL.B. / LL.M. (Environment Law / Administrative Law) OR M.Sc.(Environmental Science) OR M.E./ M.Tech (Environmental/ Civil/ Chemical Engineering) with a PG Diploma in Environmental Law OR Equivalent Degree from a recognized University.<br>&bull; &nbsp; &nbsp;Minimum 5+ Years\' of overall experience and 3+ years of relevant experience in environmental compliance, administrative coordination with regulatory forums, or policy advisory roles in government/NGO/consulting organizations.</p>\r\n<p>4. Program Management Expert<br>&bull; &nbsp; &nbsp;M.E./ M.Tech (Engineering/ Planning/ Management/ OR Equivalent Degree from a recognized University.<br>&bull; &nbsp; &nbsp;Minimum 5+ Years\' of overall experience in program management with minimum 3+ years of relevant experience in a PMU.</p>','2026-05-25 14:01:37',1,'<p><span lang=\"EN-IN\" style=\"font-size: 12.0pt; line-height: 115%; font-family: \'Times New Roman\',\'serif\'; mso-fareast-font-family: Aptos; mso-fareast-theme-font: minor-latin; mso-bidi-font-family: Mangal; mso-bidi-theme-font: minor-bidi; color: black; mso-themecolor: text1; mso-ansi-language: EN-IN; mso-fareast-language: EN-US; mso-bidi-language: AR-SA;\">As per EOI document</span></p>','2026-06-02 17:13:52',NULL,1);
insert  into `eoi_request_prebid_query`(`questionid`,`queryid`,`requestid`,`vendorid`,`clause_reference`,`clause_detail`,`queries_with_justification`,`creationdate`,`iseditable`,`answer`,`answeredon`,`subuserid`,`isprebid`) values (164,34,162,5,'<p>Clause 5 Evaluation Process<br>&nbsp;Page 5</p>','<p>Bidder Presentation &ndash; 50 marks&nbsp;<br>&bull; &nbsp; &nbsp;Approach and Methodology<br>&bull; &nbsp; &nbsp;Understanding of the Project<br>&bull; &nbsp; &nbsp;Quality of proposed methodology for such specific kind of a project<br>&bull; &nbsp; &nbsp;Prior Experience to implementing government projects in Bid Management/ Exit Management<br>&bull; &nbsp; &nbsp;Understanding of key SLAs for the project management</p>\r\n<p>Candidate Interview (50 marks)<br>&bull; &nbsp; &nbsp;Suitability of profile<br>&bull; &nbsp; &nbsp;Years of relevant experience<br>&bull; &nbsp; &nbsp;Good understanding of project management best practices framework<br>&bull; &nbsp; &nbsp;Ability to negotiate/ persuade/ influence<br>&bull; &nbsp; &nbsp;Strong ability to understand, deliberate, and report/ monitor the key SLAs<br>&bull; &nbsp; &nbsp;Excellent communication abilities</p>','<p><br>We request the Authority to kindly describe &ldquo;Exit Management&rdquo; and its relevance to the scope of work.&nbsp;</p>\r\n<p>We also request the Authority to kindly share the split of 50 marks across the different sub-sections as this will help us to align our proposal with the requirement.&nbsp;</p>\r\n<p>For Candidate Interviews, we request the Authority to kindly mention the split of the marks across the 4 positions. We request the Authority to further sub-split the marks as follows &ndash;&nbsp;<br>&bull; &nbsp; &nbsp;30% for educational qualification<br>&bull; &nbsp; &nbsp;50% marks for meeting minimum experience qualification<br>&bull; &nbsp; &nbsp;20% of the marks allotted for excellent communication skills</p>','2026-05-25 14:03:29',1,'<p><span lang=\"EN-IN\" style=\"font-size: 12.0pt; line-height: 115%; font-family: \'Times New Roman\',\'serif\'; mso-fareast-font-family: Aptos; mso-fareast-theme-font: minor-latin; mso-bidi-font-family: Mangal; mso-bidi-theme-font: minor-bidi; color: black; mso-themecolor: text1; mso-ansi-language: EN-IN; mso-fareast-language: EN-US; mso-bidi-language: AR-SA;\">As per EOI document</span></p>','2026-06-02 17:14:39',NULL,1);
insert  into `eoi_request_prebid_query`(`questionid`,`queryid`,`requestid`,`vendorid`,`clause_reference`,`clause_detail`,`queries_with_justification`,`creationdate`,`iseditable`,`answer`,`answeredon`,`subuserid`,`isprebid`) values (165,34,162,5,'<p>Clause 8 Documents required as response to this EoI<br>&nbsp;Page 6</p>','<p>&bull; &nbsp; &nbsp;Signed copy of this EoI.<br>&bull; &nbsp; &nbsp;Copy of the approach and methodology presentation.<br>&bull; &nbsp; &nbsp;Resumes of the resources who will appear for the interview.</p>','<p>We understand that we can use the standard World Bank format for resumes. Kindly confirm.&nbsp;</p>','2026-05-25 14:04:53',1,'<p><span style=\"font-size: 12.0pt; line-height: 115%; font-family: \'Times New Roman\',\'serif\'; mso-fareast-font-family: \'Times New Roman\'; color: black; letter-spacing: -.05pt; mso-ansi-language: EN-US; mso-fareast-language: EN-US; mso-bidi-language: EN-US;\">Please Refer CHiPS empanelment document for the format of Resume.</span></p>','2026-06-02 17:15:35',NULL,1);
insert  into `eoi_request_prebid_query`(`questionid`,`queryid`,`requestid`,`vendorid`,`clause_reference`,`clause_detail`,`queries_with_justification`,`creationdate`,`iseditable`,`answer`,`answeredon`,`subuserid`,`isprebid`) values (166,35,161,4,'<p>Team Requirements, Page no 4</p>','<p>Education Expert<br><br>Qualification :<br>Bachelor&rsquo;s degree in HR, business administration.<br>Master&rsquo;s degree in HR, business administration.</p>','<p>With reference to the RFP/ToR for the position of Education Expert, we note that the current eligibility criteria specifying a Bachelor&rsquo;s and Master&rsquo;s degree in HR or Business Administration are restrictive in nature and may limit participation to a narrow pool of candidates. We respectfully suggest that the requirement of a Bachelor&rsquo;s degree in specific fields be revised, and instead, the qualification be defined as a Master&rsquo;s degree in a relevant field.<br><br>Accordingly, we request that the criteria be broadened to include candidates with a Master&rsquo;s in Social Work (MSW), MBA, MA in relevant disciplines such as Education, Sociology, Development Studies, Public Policy, or any other relevant degree.</p>','2026-05-25 15:23:32',1,'<p>To ensure wider/Larger participation, master\'s degree in relevant field can be added in clause detail.</p>','2026-05-29 12:21:46',NULL,1);
insert  into `eoi_request_prebid_query`(`questionid`,`queryid`,`requestid`,`vendorid`,`clause_reference`,`clause_detail`,`queries_with_justification`,`creationdate`,`iseditable`,`answer`,`answeredon`,`subuserid`,`isprebid`) values (167,35,161,4,'<p>Team Requirements, Page no 4</p>','<p>Healthcare Expert<br><br>Qualification :<br>Bachelor’s degree in HR, business administration , life science or nursing.<br>Master’s degree in HR, business administration , life science , health administration.</p>','<p>With reference to the RFP/ToR for the position of Health Expert, we note that the current eligibility criteria specifying a Bachelor’s degree in HR, Business Administration, Life Sciences, or Nursing and a Master’s degree in HR, Business Administration, Life Sciences, or Health Administration are restrictive in nature and may limit participation to a narrow pool of candidates.<br><br>We respectfully suggest that the requirement of a Bachelor’s degree in specific fields be revised, and instead, the qualification be defined primarily as a Master’s degree in a relevant field. Accordingly, we request that the criteria be broadened to include candidates with a master’s in health administration, Public Health, Hospital Management, or any other similar relevant qualification.</p>','2026-05-25 15:24:29',1,'<p>To ensure wider/Larger participation, master\'s degree in relevant field can be added in clause detail.</p>','2026-05-29 12:22:04',NULL,1);
insert  into `eoi_request_prebid_query`(`questionid`,`queryid`,`requestid`,`vendorid`,`clause_reference`,`clause_detail`,`queries_with_justification`,`creationdate`,`iseditable`,`answer`,`answeredon`,`subuserid`,`isprebid`) values (168,36,162,4,'<p>Section 3, Scope of Work, Point No. II, Sub Points no 7 - 11, Page No 3-4</p>','<ul>\r\n<li><span style=\"font-size: 10.0pt; font-family: \'Arial\',sans-serif; mso-fareast-font-family: \'Times New Roman\'; mso-ansi-language: EN-US; mso-fareast-language: EN-US; mso-bidi-language: AR-SA;\">Liquid Waste & Wastewater Management – Technical & Regulatory Support</span></li>\r\n</ul>','<p><span style=\"font-size: 10.0pt; line-height: 115%; font-family: \'Arial\',sans-serif;\">Please clarify for liquid waste advisory (ETPs, STPs, CETPs) ,<br></span>    1. will the team require field visits to industrial/municipal sites across the state. <br>    2. If yes, what is the approximate number and frequency of such inspections expected per quarter?</p>','2026-05-25 16:12:02',1,'<p><span style=\"font-size: 12.0pt; line-height: 115%; font-family: \'Times New Roman\',\'serif\'; mso-fareast-font-family: \'Times New Roman\'; letter-spacing: -.05pt; mso-ansi-language: EN-US; mso-fareast-language: EN-US; mso-bidi-language: EN-US;\">Yes, the team is required to visit industrial/ municipal sites across the state as and when required.</span></p>','2026-06-02 17:16:13',NULL,1);
insert  into `eoi_request_prebid_query`(`questionid`,`queryid`,`requestid`,`vendorid`,`clause_reference`,`clause_detail`,`queries_with_justification`,`creationdate`,`iseditable`,`answer`,`answeredon`,`subuserid`,`isprebid`) values (169,36,162,4,'<p><span style=\"font-size: 10.0pt; font-family: \'Arial\',sans-serif; mso-fareast-font-family: \'Times New Roman\'; mso-ansi-language: EN-US; mso-fareast-language: EN-US; mso-bidi-language: AR-SA;\">Section 3, Scope of Work, Point Point III<em>,</em> Sub Point 12&ndash;16, Page No. 3-4</span></p>','<ul>\r\n<li><span style=\"font-size: 10.0pt; font-family: \'Arial\',sans-serif; mso-fareast-font-family: \'Times New Roman\'; mso-ansi-language: EN-US; mso-fareast-language: EN-US; mso-bidi-language: AR-SA;\">Compliance Monitoring and Coordination with Apex-Level Bodies</span></li>\r\n</ul>','<p class=\"MsoNormal\" style=\"line-height: 115%;\"><span style=\"font-size: 10.0pt; line-height: 115%; font-family: \'Arial\',sans-serif;\">Section 3 mentions preparation of \'compliance reports, ATRs, and status affidavits\' for apex committees. </span></p>\r\n<p><span style=\"font-size: 10.0pt; font-family: \'Arial\',sans-serif; mso-fareast-font-family: \'Times New Roman\'; mso-ansi-language: EN-US; mso-fareast-language: EN-US; mso-bidi-language: AR-SA;\">     1. Could CHiPS specify how many proceedings are estimated per year?</span></p>','2026-05-25 16:14:52',1,'<p><span lang=\"EN-IN\" style=\"font-size: 12.0pt; line-height: 115%; font-family: \'Times New Roman\',\'serif\'; mso-fareast-font-family: Aptos; mso-fareast-theme-font: minor-latin; mso-bidi-font-family: Mangal; mso-bidi-theme-font: minor-bidi; color: black; mso-themecolor: text1; mso-ansi-language: EN-IN; mso-fareast-language: EN-US; mso-bidi-language: AR-SA;\">As per EOI document</span></p>','2026-06-02 17:16:33',NULL,1);
insert  into `eoi_request_prebid_query`(`questionid`,`queryid`,`requestid`,`vendorid`,`clause_reference`,`clause_detail`,`queries_with_justification`,`creationdate`,`iseditable`,`answer`,`answeredon`,`subuserid`,`isprebid`) values (170,37,162,1,'<p class=\"MsoNormal\" style=\"margin-bottom: 0in; line-height: 115%; text-align: justify;\"><span lang=\"EN-IN\" style=\"font-size: 11.0pt; line-height: 115%; font-family: \'Arial\',sans-serif; mso-fareast-font-family: Arial; mso-ansi-language: EN-IN;\">Section 3, Brief Scope of Work, I. Solid Waste Management (SWM) &ndash; Technical &amp; Regulatory Support, Point 5</span><span lang=\"EN-IN\" style=\"font-size: 11.0pt; line-height: 115%; font-family: \'Arial\',sans-serif; mso-fareast-font-family: Arial; mso-ansi-language: EN-IN;\">&nbsp;</span></p>\r\n<p class=\"MsoNormal\" style=\"margin-bottom: 0in; line-height: 115%; text-align: justify;\"><span lang=\"EN-IN\" style=\"font-size: 11.0pt; line-height: 115%; font-family: \'Arial\',sans-serif; mso-fareast-font-family: Arial; mso-ansi-language: EN-IN;\">Page No.4</span></p>','<p style=\"text-align: justify;\"><span lang=\"EN-IN\" style=\"font-size: 11.0pt; line-height: 116%; font-family: \'Arial\',sans-serif; mso-fareast-font-family: Arial; mso-ansi-language: EN-IN; mso-fareast-language: JA; mso-bidi-language: AR-SA;\">Support CECB in conducting site Inspections, third-party audits, and environmental compliance assessments of waste processing and disposal facilities across the State.</span></p>','<p style=\"text-align: justify;\"><span lang=\"EN-IN\" style=\"font-size: 11.0pt; line-height: 116%; font-family: \'Arial\',sans-serif; mso-fareast-font-family: Arial; mso-ansi-language: EN-IN; mso-fareast-language: JA; mso-bidi-language: AR-SA;\">It is understood that site inspection will be led by the officials of CECB and the PMU team may have to assist/facilitate/ accompany them for the site visits. Similarly, for third-party audits and environmental compliance assessments will be done other by third party agencies and PMU team may assist with templates, SOPs for audits based on applicable rules.</span></p>','2026-05-25 16:18:20',1,'<p><span lang=\"EN-IN\" style=\"font-size: 12.0pt; line-height: 115%; font-family: \'Times New Roman\',\'serif\'; mso-fareast-font-family: Aptos; mso-fareast-theme-font: minor-latin; mso-bidi-font-family: Mangal; mso-bidi-theme-font: minor-bidi; color: black; mso-themecolor: text1; mso-ansi-language: EN-IN; mso-fareast-language: EN-US; mso-bidi-language: AR-SA;\">As per EOI document</span></p>','2026-06-02 17:16:53',NULL,1);
insert  into `eoi_request_prebid_query`(`questionid`,`queryid`,`requestid`,`vendorid`,`clause_reference`,`clause_detail`,`queries_with_justification`,`creationdate`,`iseditable`,`answer`,`answeredon`,`subuserid`,`isprebid`) values (171,36,162,4,'<p class=\"MsoNormal\" style=\"line-height: 115%;\"><span style=\"font-size: 10.0pt; line-height: 115%; font-family: \'Arial\',sans-serif;\">Section 4,&nbsp;</span><span style=\"font-size: 10.0pt; font-family: \'Arial\',sans-serif; mso-fareast-font-family: \'Times New Roman\'; mso-ansi-language: EN-US; mso-fareast-language: EN-US; mso-bidi-language: AR-SA;\">Team Requirment, S.No 3-4</span></p>','<p>Qualification; Domain Expert (Compliance and Subject Matter Experts)<br><span style=\"font-size: 10.0pt; font-family: \'Arial\',sans-serif; mso-fareast-font-family: \'Times New Roman\'; mso-ansi-language: EN-US; mso-fareast-language: EN-US; mso-bidi-language: AR-SA;\">The EoI specifies \'LL.B./LL.M. (Environmental Law / Administrative Law)\' as an alternate qualification for Domain Expert (Compliance &amp; Subject Matter Expert).</span></p>','<p class=\"MsoNormal\" style=\"line-height: 115%;\"><span style=\"font-size: 10.0pt; line-height: 115%; font-family: \'Arial\',sans-serif;\">Kindly note that we do not provide any legal services directly or indirectly since we are not permitted to provide the same.</span></p>\r\n<p class=\"MsoNormal\" style=\"line-height: 115%;\"><span style=\"font-size: 10.0pt; line-height: 115%; font-family: \'Arial\',sans-serif;\">&nbsp;</span><span style=\"font-size: 10.0pt; font-family: \'Arial\',sans-serif; mso-fareast-font-family: \'Times New Roman\'; mso-ansi-language: EN-US; mso-fareast-language: EN-US; mso-bidi-language: AR-SA;\">Accordingly, we have to engage a reputed law firm / legal expert on Authority&rsquo;s behalf to address such parts of the scope of work which require to be addressed from the legal perspective. We would coordinate between such law firm / legal expert and the Authority.</span></p>','2026-05-25 16:19:15',1,'<p><span lang=\"EN-IN\" style=\"font-size: 12.0pt; line-height: 115%; font-family: \'Times New Roman\',\'serif\'; mso-fareast-font-family: Aptos; mso-fareast-theme-font: minor-latin; mso-bidi-font-family: Mangal; mso-bidi-theme-font: minor-bidi; color: black; mso-themecolor: text1; mso-ansi-language: EN-IN; mso-fareast-language: EN-US; mso-bidi-language: AR-SA;\">As per EOI document</span></p>','2026-06-02 17:17:36',NULL,1);
insert  into `eoi_request_prebid_query`(`questionid`,`queryid`,`requestid`,`vendorid`,`clause_reference`,`clause_detail`,`queries_with_justification`,`creationdate`,`iseditable`,`answer`,`answeredon`,`subuserid`,`isprebid`) values (172,36,162,4,'<p class=\"MsoNormal\" style=\"line-height: 115%;\"><span style=\"font-size: 10.0pt; line-height: 115%; font-family: \'Arial\',sans-serif;\">Section 6, </span><span style=\"font-size: 10.0pt; line-height: 115%; font-family: \'Arial\',sans-serif;\">Payment Terms, Page No 6</span></p>','<p class=\"MsoNormal\" style=\"line-height: 115%;\"><span style=\"font-size: 10.0pt; line-height: 115%; font-family: \'Arial\',sans-serif;\">The successful bidder shall submit the invoice for payment on a monthly basis.</span></p>\r\n<p><span style=\"font-size: 10.0pt; font-family: \'Arial\',sans-serif; mso-fareast-font-family: \'Times New Roman\'; mso-ansi-language: EN-US; mso-fareast-language: EN-US; mso-bidi-language: AR-SA;\">Each payment will be made only after the delivery of the corresponding deliverable and its acceptance by CHiPS.</span></p>','<p><span style=\"font-size: 10.0pt; font-family: \'Arial\',sans-serif; mso-fareast-font-family: \'Times New Roman\'; mso-ansi-language: EN-US; mso-fareast-language: EN-US; mso-bidi-language: AR-SA;\">Since no specific deliverables are mentioned in the ToR and it&rsquo;s a PMU assignment, we believe that Monthly Progress report will be considered as the deliverable for payment processing,</span></p>','2026-05-25 16:20:18',1,'<p><span style=\"font-size: 12.0pt; line-height: 115%; font-family: \'Times New Roman\',\'serif\'; mso-fareast-font-family: \'Times New Roman\'; color: black; letter-spacing: -.05pt; mso-ansi-language: EN-US; mso-fareast-language: EN-US; mso-bidi-language: EN-US;\">Refer Empanelment Document</span></p>','2026-06-02 17:18:08',NULL,1);
