insert  into `eoi_resource_deployment`(`deploymentid`,`parentdeploymentid`,`orderid`,`recordid`,`userid`,`employee_code`,`name`,`mobilenumber`,`email`,`deployment_date`,`deployed_date`,`delay_days`,`deployment_status`,`remarks`,`actions`,`is_verified`,`verified_by`,`verified_on`,`tierid`,`sectorid`,`positionid`,`role`,`experience`,`experiencelevel`,`qualification`,`deploymenttype`,`duration`,`remark`,`remunerationid`,`remuneration`,`baseprice`,`operating`,`operatingvalue`,`tax`,`taxvalue`,`admincharge`,`adminvalue`,`grandtotal`,`isExtended`,`lastdate`,`old_deployment_id`,`rateid`,`startDate`,`endDate`,`replaced_by_deployment_id`,`supporting_document`,`isClosed`,`forCalculation`) values (402,0,101,3652,0,NULL,NULL,NULL,NULL,'2026-04-01','2026-04-01',0,'Extended',NULL,NULL,1,0,NULL,1,6,1,'','(10+ years)',0,'<ul>\r\n<li>Plan and coordinate the overall study framework, design and methodology, including setting objectives, milestones, and performance metrics, ensuring alignment with study objectives and compliance with quality standards.</li>\r\n<li>Supervise and support the Senior Consultants and Field Supervisors, providing guidance, direction, and resources to ensure effective team performance.</li>\r\n<li>Foster a collaborative and productive work environment, addressing any team dynamics or operational issues.</li>\r\n<li>Monitor study progress, including timelines, budgets, and deliverables, and make adjustments as needed to keep the study on track.</li>\r\n<li>Engage with key stakeholders, including senior management and department officials, to gather input, provide updates, and address concerns.</li>\r\n<li>Implement and monitor quality control measures to maintain the accuracy and reliability of data and findings.</li>\r\n<li>Review and deliver comprehensive reports and presentations to senior management and stakeholders, highlighting key findings, insights, and recommendations.</li>\r\n</ul>\r\n<p>&nbsp;</p>','FULL TIME',12,'<p>Project Manager</p>\r\n<p>&nbsp;</p>',62,'400000.00','400000.00','0.00','0.00','18.00','864000.00','5.00','283200.00','5947200.00',1,NULL,0,2,NULL,NULL,0,NULL,0,0);
insert  into `eoi_resource_deployment`(`deploymentid`,`parentdeploymentid`,`orderid`,`recordid`,`userid`,`employee_code`,`name`,`mobilenumber`,`email`,`deployment_date`,`deployed_date`,`delay_days`,`deployment_status`,`remarks`,`actions`,`is_verified`,`verified_by`,`verified_on`,`tierid`,`sectorid`,`positionid`,`role`,`experience`,`experiencelevel`,`qualification`,`deploymenttype`,`duration`,`remark`,`remunerationid`,`remuneration`,`baseprice`,`operating`,`operatingvalue`,`tax`,`taxvalue`,`admincharge`,`adminvalue`,`grandtotal`,`isExtended`,`lastdate`,`old_deployment_id`,`rateid`,`startDate`,`endDate`,`replaced_by_deployment_id`,`supporting_document`,`isClosed`,`forCalculation`) values (403,0,101,3654,0,NULL,NULL,NULL,NULL,'2026-04-01','2026-04-01',0,'Extended',NULL,NULL,1,0,NULL,1,6,3,'','(5+ years)',0,'<ul>\r\n<li>Conduct desk review of project documentation, gather secondary data, review applicable statutory provisions, and identify any gaps in existing information sources.</li>\r\n<li>Undertake preliminary visit to the project area to carry out preparatory activities.</li>\r\n<li>Design survey instruments, train investigators and pilot test the questionnaires.</li>\r\n<li>Oversee the implementation of the study, ensuring that all activities are conducted according to the study plan.</li>\r\n<li>Provide training and support to the Field Supervisor and their team on study protocols and data collection methods.</li>\r\n<li>Manage and support the Field Supervisor and their team, providing guidance, resources, and troubleshooting as needed.</li>\r\n<li>Monitor progress and performance to ensure adherence to timelines, budgets, and quality standards.</li>\r\n<li>Implement quality control measures to ensure the validity and reliability of the study results.</li>\r\n<li>Review and verify data collection processes and outcomes, addressing any discrepancies or issues.</li>\r\n<li>Maintain a comprehensive record of study activities, data, and communications.</li>\r\n<li>Participate in stakeholder consultations along with the survey team.</li>\r\n<li>Compile, clean, and analyze the quantitative and qualitative data collected during the study, utilizing appropriate analytical tools and techniques.</li>\r\n<li>Synthesize findings, highlighting key insights and implications for stakeholders.</li>\r\n<li>Prepare detailed reports and presentations on the findings and recommendations for action.</li>\r\n</ul>','FULL TIME',12,'',64,'320000.00','320000.00','0.00','0.00','18.00','691200.00','5.00','226560.00','4757760.00',1,NULL,0,2,NULL,NULL,0,NULL,0,0);
