insert  into `eoi_resource_deployment`(`deploymentid`,`parentdeploymentid`,`orderid`,`recordid`,`userid`,`employee_code`,`name`,`mobilenumber`,`email`,`deployment_date`,`deployed_date`,`delay_days`,`deployment_status`,`remarks`,`actions`,`is_verified`,`verified_by`,`verified_on`,`tierid`,`sectorid`,`positionid`,`role`,`experience`,`experiencelevel`,`qualification`,`deploymenttype`,`duration`,`remark`,`remunerationid`,`remuneration`,`baseprice`,`operating`,`operatingvalue`,`tax`,`taxvalue`,`admincharge`,`adminvalue`,`grandtotal`,`isExtended`,`lastdate`,`old_deployment_id`,`rateid`,`startDate`,`endDate`,`replaced_by_deployment_id`,`supporting_document`,`isClosed`,`forCalculation`) values (488,0,117,3742,485,'CSO181','Ashwani Yadu','8770826464',NULL,'2026-04-07','2026-04-15',0,'Active',NULL,NULL,1,0,NULL,1,3,1,'','(10+ years)',0,'<p>Governance Sector</p>','FULL TIME',12,'<p>Focus- Strategy, policy, and high-level administration</p>\r\n<ol>\r\n<li>Strategic roadmap- Develop a 3-5 year digital transformation vision for the corporation.</li>\r\n<li>Policy formulation- Draft internal policies regarding procurement, human resources, and corporate ethics.</li>\r\n<li>Institutional Strengthening- Identify gaps in organizational structure and recommend capacity-building measures.</li>\r\n<li>Regulatory compliance- Ensure all corporate actions align with the Chhattisgarh Excise Act and State Government mandates.</li>\r\n<li>Inter-Departmental Liaison- Act as the primary point of contact between CSMCL and the Department of IT/ Finance.</li>\r\n<li>Performance Audits- Conduct periodic reviews of departmental KPIs and suggest corrective actions.</li>\r\n<li>Resource Optimization- Analyze budget utilization and suggest ways to reduce operational overheads.</li>\r\n<li>Crisis Management- Develop protocols for handling administrative or legal contingencies.</li>\r\n<li>CSR Framework- design and oversee the implementation of Corporate Social Responsibility initiatives.</li>\r\n<li>Board Support- Prepare strategic briefs and presentations for Board of Directors&rsquo; meetings.</li>\r\n</ol>',143,'420000.00','420000.00','0.00','0.00','18.00','864000.00','5.00','283200.00','5947200.00',0,NULL,0,2,NULL,NULL,0,NULL,0,0);
