insert  into `eoi_resource_deployment`(`deploymentid`,`parentdeploymentid`,`orderid`,`recordid`,`userid`,`employee_code`,`name`,`mobilenumber`,`email`,`deployment_date`,`deployed_date`,`delay_days`,`deployment_status`,`remarks`,`actions`,`is_verified`,`verified_by`,`verified_on`,`tierid`,`sectorid`,`positionid`,`role`,`experience`,`experiencelevel`,`qualification`,`deploymenttype`,`duration`,`remark`,`remunerationid`,`remuneration`,`baseprice`,`operating`,`operatingvalue`,`tax`,`taxvalue`,`admincharge`,`adminvalue`,`grandtotal`,`isExtended`,`lastdate`,`old_deployment_id`,`rateid`,`startDate`,`endDate`,`replaced_by_deployment_id`,`supporting_document`,`isClosed`,`forCalculation`) values (599,0,141,3604,626,'EM-1010','Gajendra Sahu','9479020075','gajendra1234@gmail.com','2026-05-12','2026-05-17',0,'Active',NULL,NULL,1,0,NULL,1,4,1,NULL,NULL,0,'<ul>\r\n<li>Should be having a leadership position like Partner/CEO/MD of the organization.</li>\r\n<li>Should have minimum 20 years of experience in management consulting</li>\r\n<li>Should have extensive public sector experience both in India and abroad</li>\r\n<li>Should have done at least 5 engagements in healthcare in the last 5 years including international assignments.</li>\r\n<li>should have worked with ministry of health of family welfare/ state health department</li>\r\n</ul>','PART TIME',6,'<p>Project Director (Should be Available in Raipur as and when required)</p>',148,'420000.00','420000.00','0.00','0.00','18.00','439200.00','5.00','143960.00','3023160.00',0,NULL,0,2,'2026-05-12','2026-11-11',0,NULL,0,0);
