insert  into `eoi_resource_deployment`(`deploymentid`,`parentdeploymentid`,`orderid`,`recordid`,`userid`,`employee_code`,`name`,`mobilenumber`,`email`,`deployment_date`,`deployed_date`,`delay_days`,`deployment_status`,`remarks`,`actions`,`is_verified`,`verified_by`,`verified_on`,`tierid`,`sectorid`,`positionid`,`role`,`experience`,`experiencelevel`,`qualification`,`deploymenttype`,`duration`,`remark`,`remunerationid`,`remuneration`,`baseprice`,`operating`,`operatingvalue`,`tax`,`taxvalue`,`admincharge`,`adminvalue`,`grandtotal`,`isExtended`,`lastdate`,`old_deployment_id`,`rateid`,`startDate`,`endDate`,`replaced_by_deployment_id`,`supporting_document`,`isClosed`,`forCalculation`) values (863,402,167,3652,0,NULL,NULL,NULL,NULL,'2025-08-16','2025-08-16',0,'Active',NULL,NULL,1,0,NULL,1,6,1,'','(10+ years)',0,'<ul>\r\n<li>Plan and coordinate the overall study framework, design and methodology, including setting objectives, milestones, and performance metrics, ensuring alignment with study objectives and compliance with quality standards.</li>\r\n<li>Supervise and support the Senior Consultants and Field Supervisors, providing guidance, direction, and resources to ensure effective team performance.</li>\r\n<li>Foster a collaborative and productive work environment, addressing any team dynamics or operational issues.</li>\r\n<li>Monitor study progress, including timelines, budgets, and deliverables, and make adjustments as needed to keep the study on track.</li>\r\n<li>Engage with key stakeholders, including senior management and department officials, to gather input, provide updates, and address concerns.</li>\r\n<li>Implement and monitor quality control measures to maintain the accuracy and reliability of data and findings.</li>\r\n<li>Review and deliver comprehensive reports and presentations to senior management and stakeholders, highlighting key findings, insights, and recommendations.</li>\r\n</ul>\r\n<p>&nbsp;</p>','FULL TIME',0,NULL,62,'400000.00','400000.00','0.00',NULL,'18.00',NULL,'5.00',NULL,NULL,0,NULL,0,2,'2025-08-16','2026-02-28',0,NULL,0,0);
insert  into `eoi_resource_deployment`(`deploymentid`,`parentdeploymentid`,`orderid`,`recordid`,`userid`,`employee_code`,`name`,`mobilenumber`,`email`,`deployment_date`,`deployed_date`,`delay_days`,`deployment_status`,`remarks`,`actions`,`is_verified`,`verified_by`,`verified_on`,`tierid`,`sectorid`,`positionid`,`role`,`experience`,`experiencelevel`,`qualification`,`deploymenttype`,`duration`,`remark`,`remunerationid`,`remuneration`,`baseprice`,`operating`,`operatingvalue`,`tax`,`taxvalue`,`admincharge`,`adminvalue`,`grandtotal`,`isExtended`,`lastdate`,`old_deployment_id`,`rateid`,`startDate`,`endDate`,`replaced_by_deployment_id`,`supporting_document`,`isClosed`,`forCalculation`) values (864,403,167,3654,0,NULL,NULL,NULL,NULL,'2025-08-16','2025-08-16',0,'Active',NULL,NULL,1,0,NULL,1,6,3,'','(5+ years)',0,'<ul>\r\n<li>Conduct desk review of project documentation, gather secondary data, review applicable statutory provisions, and identify any gaps in existing information sources.</li>\r\n<li>Undertake preliminary visit to the project area to carry out preparatory activities.</li>\r\n<li>Design survey instruments, train investigators and pilot test the questionnaires.</li>\r\n<li>Oversee the implementation of the study, ensuring that all activities are conducted according to the study plan.</li>\r\n<li>Provide training and support to the Field Supervisor and their team on study protocols and data collection methods.</li>\r\n<li>Manage and support the Field Supervisor and their team, providing guidance, resources, and troubleshooting as needed.</li>\r\n<li>Monitor progress and performance to ensure adherence to timelines, budgets, and quality standards.</li>\r\n<li>Implement quality control measures to ensure the validity and reliability of the study results.</li>\r\n<li>Review and verify data collection processes and outcomes, addressing any discrepancies or issues.</li>\r\n<li>Maintain a comprehensive record of study activities, data, and communications.</li>\r\n<li>Participate in stakeholder consultations along with the survey team.</li>\r\n<li>Compile, clean, and analyze the quantitative and qualitative data collected during the study, utilizing appropriate analytical tools and techniques.</li>\r\n<li>Synthesize findings, highlighting key insights and implications for stakeholders.</li>\r\n<li>Prepare detailed reports and presentations on the findings and recommendations for action.</li>\r\n</ul>','FULL TIME',0,NULL,64,'320000.00','320000.00','0.00',NULL,'18.00',NULL,'5.00',NULL,NULL,0,NULL,0,2,'2025-08-16','2026-02-28',0,NULL,0,0);
insert  into `eoi_resource_deployment`(`deploymentid`,`parentdeploymentid`,`orderid`,`recordid`,`userid`,`employee_code`,`name`,`mobilenumber`,`email`,`deployment_date`,`deployed_date`,`delay_days`,`deployment_status`,`remarks`,`actions`,`is_verified`,`verified_by`,`verified_on`,`tierid`,`sectorid`,`positionid`,`role`,`experience`,`experiencelevel`,`qualification`,`deploymenttype`,`duration`,`remark`,`remunerationid`,`remuneration`,`baseprice`,`operating`,`operatingvalue`,`tax`,`taxvalue`,`admincharge`,`adminvalue`,`grandtotal`,`isExtended`,`lastdate`,`old_deployment_id`,`rateid`,`startDate`,`endDate`,`replaced_by_deployment_id`,`supporting_document`,`isClosed`,`forCalculation`) values (865,404,167,3653,0,NULL,NULL,NULL,NULL,'2025-08-16','2025-08-16',0,'Active',NULL,NULL,1,0,NULL,1,6,3,'','(5+ years)',0,'<ul>\r\n<li>Conduct desk review of project documentation, gather secondary data, review applicable statutory provisions, and identify any gaps in existing information sources.</li>\r\n<li>Undertake preliminary visit to the project area to carry out preparatory activities.</li>\r\n<li>Design survey instruments, train investigators and pilot test the questionnaires.</li>\r\n<li>Oversee the implementation of the study, ensuring that all activities are conducted according to the study plan.</li>\r\n<li>Provide training and support to the Field Supervisor and their team on study protocols and data collection methods.</li>\r\n<li>Manage and support the Field Supervisor and their team, providing guidance, resources, and troubleshooting as needed.</li>\r\n<li>Monitor progress and performance to ensure adherence to timelines, budgets, and quality standards.</li>\r\n<li>Implement quality control measures to ensure the validity and reliability of the study results.</li>\r\n<li>Review and verify data collection processes and outcomes, addressing any discrepancies or issues.</li>\r\n<li>Maintain a comprehensive record of study activities, data, and communications.</li>\r\n<li>Participate in stakeholder consultations along with the survey team.</li>\r\n<li>Compile, clean, and analyze the quantitative and qualitative data collected during the study, utilizing appropriate analytical tools and techniques.</li>\r\n<li>Synthesize findings, highlighting key insights and implications for stakeholders.</li>\r\n<li>Prepare detailed reports and presentations on the findings and recommendations for action.</li>\r\n</ul>','FULL TIME',0,NULL,64,'320000.00','320000.00','0.00',NULL,'18.00',NULL,'5.00',NULL,NULL,0,NULL,0,2,'2025-08-16','2026-02-28',0,NULL,0,0);
insert  into `eoi_resource_deployment`(`deploymentid`,`parentdeploymentid`,`orderid`,`recordid`,`userid`,`employee_code`,`name`,`mobilenumber`,`email`,`deployment_date`,`deployed_date`,`delay_days`,`deployment_status`,`remarks`,`actions`,`is_verified`,`verified_by`,`verified_on`,`tierid`,`sectorid`,`positionid`,`role`,`experience`,`experiencelevel`,`qualification`,`deploymenttype`,`duration`,`remark`,`remunerationid`,`remuneration`,`baseprice`,`operating`,`operatingvalue`,`tax`,`taxvalue`,`admincharge`,`adminvalue`,`grandtotal`,`isExtended`,`lastdate`,`old_deployment_id`,`rateid`,`startDate`,`endDate`,`replaced_by_deployment_id`,`supporting_document`,`isClosed`,`forCalculation`) values (866,405,167,3657,0,NULL,NULL,NULL,NULL,'2025-08-16','2025-08-16',0,'Active',NULL,NULL,1,0,NULL,1,6,4,'','(3+ years)',0,'<ul>\r\n<li>Oversee and manage a team of 4 Field Surveyor each.</li>\r\n<li>Provide clear instructions and guidance to the Field Surveyors.</li>\r\n<li>Support the Field Surveyors in conducting the surveys.</li>\r\n<li>Review and verify the collected survey data for accuracy and completeness. Address discrepancies or errors in data collection promptly.</li>\r\n<li>Ensure data is properly recorded, stored, and transmitted according to project guidelines.</li>\r\n<li>Ensure adherence to timelines and protocols</li>\r\n<li>Address any issues or challenges faced by field staff and provide solutions or escalate to higher management as needed.</li>\r\n<li>Prepare and submit regular reports on survey progress, challenges, and findings to the Senior Consultants or Project Manager.</li>\r\n<li>Ensure that all field operations comply with legal, ethical, and safety standards.</li>\r\n<li>Assist in logistical arrangements for field operations, including transportation and equipment.</li>\r\n<li>Coordinate with all stakeholders, including local authorities and community representatives and facilitate necessary stakeholder consultations under the study.</li>\r\n</ul>','FULL TIME',0,NULL,65,'275000.00','275000.00','0.00',NULL,'18.00',NULL,'5.00',NULL,NULL,0,NULL,0,2,'2025-08-16','2026-02-28',0,NULL,0,0);
