insert  into `eoi_resource_deployment`(`deploymentid`,`parentdeploymentid`,`orderid`,`recordid`,`userid`,`employee_code`,`name`,`mobilenumber`,`email`,`deployment_date`,`deployed_date`,`delay_days`,`deployment_status`,`remarks`,`actions`,`is_verified`,`verified_by`,`verified_on`,`tierid`,`sectorid`,`positionid`,`role`,`experience`,`experiencelevel`,`qualification`,`deploymenttype`,`duration`,`remark`,`remunerationid`,`remuneration`,`baseprice`,`operating`,`operatingvalue`,`tax`,`taxvalue`,`admincharge`,`adminvalue`,`grandtotal`,`isExtended`,`lastdate`,`old_deployment_id`,`rateid`,`startDate`,`endDate`,`replaced_by_deployment_id`,`supporting_document`,`isClosed`,`forCalculation`) values (869,408,167,3672,0,NULL,NULL,NULL,NULL,'2025-08-16','2025-08-16',0,'Active',NULL,NULL,1,0,NULL,1,6,5,'','(1-3 years)',0,'<ul>\r\n<li>Participate in training sessions provided by the Senior Consultants and Field Supervisor to understand survey methods and tools.</li>\r\n<li>Conduct face-to-face census survey within the project-affected area, including a comprehensive socio-economic survey of all affected families.</li>\r\n<li>Perform land survey, including the examination of land revenue maps, assessment of land records, field verification of project boundaries and coordinates, and determination of land use within the project area.</li>\r\n<li>Undertake Participatory Rural Appraisal, including resource mapping, social mapping, and transect walks to physically identify and verify families affected by the project.</li>\r\n<li>Photograph and GIS-tag structures within the affected area.</li>\r\n<li>Accurately record responses and ensure data integrity.</li>\r\n<li>Adhere to the survey schedule and visit all designated locations in a timely manner.</li>\r\n<li>Review responses for consistency and accuracy before submission.</li>\r\n<li>Report any discrepancies, incomplete data, or issues encountered during data collection to the Field Supervisor.</li>\r\n<li>Submit daily reports on the progress of data collection and any challenges encountered.</li>\r\n<li>Ensure adherence to legal, ethical, and privacy guidelines related to data collection.</li>\r\n</ul>','FULL TIME',0,NULL,66,'220000.00','220000.00','0.00',NULL,'18.00',NULL,'5.00',NULL,NULL,0,NULL,0,2,'2025-08-16','2026-02-28',0,NULL,0,0);
