  PRIMARY KEY (`log_id`),
  KEY `idx_module` (`module_name`),
  KEY `idx_record` (`record_id`),
  KEY `idx_action` (`action`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

