/*Table structure for table `finance_demand_note` */

DROP TABLE IF EXISTS `finance_demand_note`;

CREATE TABLE `finance_demand_note` (
  `demand_note_id` bigint(20) NOT NULL AUTO_INCREMENT,
  `reference_type` enum('EOI','WORK_ORDER') NOT NULL,
  `demand_note_type` enum('VENDOR_FUNDING','SERVICE_CHARGE') NOT NULL DEFAULT 'VENDOR_FUNDING',
  `demand_note_group_uuid` char(36) DEFAULT NULL,
  `request_id` bigint(20) DEFAULT NULL COMMENT 'EOI ID (Optional)',
  `order_id` bigint(20) DEFAULT NULL COMMENT 'Work Order ID (Optional)',
  `project_type` enum('AWD','CSF') NOT NULL DEFAULT 'CSF',
  `department_id` bigint(20) NOT NULL,
  `project_id` int(11) DEFAULT NULL,
  `vendor_id` int(11) DEFAULT NULL,
  `demand_note_no` varchar(50) NOT NULL,
  `demand_note_date` date NOT NULL,
  `financial_year` varchar(15) NOT NULL,
  `tax_id` bigint(20) DEFAULT NULL,
  `gst_type` enum('INTRA_STATE','INTER_STATE') DEFAULT 'INTRA_STATE',
  `gstin` varchar(20) DEFAULT NULL,
  `from_date` date DEFAULT NULL,
  `to_date` date DEFAULT NULL,
  `particular` text,
  `taxable_amount` decimal(12,2) DEFAULT '0.00',
  `cgst_rate` decimal(5,2) DEFAULT '0.00',
  `cgst_amount` decimal(12,2) DEFAULT '0.00',
  `sgst_rate` decimal(5,2) DEFAULT '0.00',
  `sgst_amount` decimal(12,2) DEFAULT '0.00',
  `igst_rate` decimal(5,2) DEFAULT '0.00',
  `igst_amount` decimal(12,2) DEFAULT '0.00',
  `total_amount` decimal(12,2) DEFAULT '0.00',
  `amount_in_words` varchar(500) DEFAULT NULL,
  `payment_status` enum('Pending','Partially Paid','Paid') DEFAULT 'Pending',
  `status` enum('Draft','Active','Cancelled') DEFAULT 'Active',
  `cancelled_by` bigint(20) DEFAULT NULL,
  `cancelled_at` datetime DEFAULT NULL,
  `cancellation_reason` text,
  `remarks` text,
  `attachment` varchar(255) DEFAULT NULL,
  `created_by` bigint(20) DEFAULT '0',
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`demand_note_id`),
  UNIQUE KEY `uk_demand_note_no` (`demand_note_no`),
  KEY `idx_request` (`request_id`),
  KEY `idx_department` (`department_id`),
  KEY `idx_tax` (`tax_id`),
  KEY `idx_order` (`order_id`),
  KEY `idx_demand_note_group_uuid` (`demand_note_group_uuid`),
  KEY `idx_demand_note_type` (`demand_note_type`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

