  KEY `idx_department_payment` (`department_payment_id`),
  KEY `idx_tax` (`tax_id`),
  KEY `idx_order` (`order_id`),
  KEY `idx_department` (`department_id`),
  KEY `idx_invoice_status` (`status`)
