  `voucher_no` varchar(100) DEFAULT NULL,
  `voucher_date` date DEFAULT NULL,
  `payment_mode_id` bigint(20) NOT NULL,
  `bank_account_id` bigint(20) DEFAULT NULL,
  `transaction_no` varchar(100) DEFAULT NULL COMMENT 'UTR/Cheque/DD Number',
  `gross_received_amount` decimal(12,2) NOT NULL DEFAULT '0.00',
  `taxable_amount` decimal(12,2) NOT NULL DEFAULT '0.00',
  `gst_amount` decimal(12,2) NOT NULL DEFAULT '0.00',
  `tds_tax_id` bigint(20) DEFAULT NULL,
  `tds_amount` decimal(12,2) NOT NULL DEFAULT '0.00',
