  `hsn_sac_code` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `tax_type` enum('GST','TDS','GST_TDS','CESS','OTHER') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'GST',
  `rate` decimal(5,2) NOT NULL DEFAULT '0.00',
  `cgst_percent` decimal(5,2) NOT NULL DEFAULT '0.00',
  `sgst_percent` decimal(5,2) NOT NULL DEFAULT '0.00',
