/*Table structure for table `finance_vendor_payment` */

DROP TABLE IF EXISTS `finance_vendor_payment`;

CREATE TABLE `finance_vendor_payment` (
  `vendor_payment_id` bigint(20) NOT NULL AUTO_INCREMENT,
  `order_id` bigint(20) NOT NULL,
  `request_id` bigint(20) DEFAULT NULL,
  `voucher_id` bigint(20) NOT NULL COMMENT 'invoice_mpr.voucher_id',
  `vendor_id` bigint(20) NOT NULL,
  `payment_date` date NOT NULL,
  `payment_mode_id` bigint(20) NOT NULL,
  `voucher_number` varchar(50) DEFAULT NULL,
  `transaction_no` varchar(100) DEFAULT NULL COMMENT 'UTR / PFMS / Cheque No',
  `bank_id` int(11) DEFAULT NULL,
  `bank_name` varchar(150) DEFAULT NULL,
  `gross_amount` decimal(12,2) DEFAULT '0.00',
  `available_fund` decimal(12,2) NOT NULL DEFAULT '0.00' COMMENT 'A - Available fund from Fund Availability',
  `admin_charge_percent` decimal(5,2) NOT NULL DEFAULT '0.00' COMMENT 'CHiPS administrative charge percentage',
  `admin_charge_amount` decimal(12,2) NOT NULL DEFAULT '0.00' COMMENT 'B - CHiPS Admin Share',
  `approval_amount` decimal(12,2) NOT NULL DEFAULT '0.00' COMMENT 'C - Available Fund less CHiPS Admin Share',
  `basic_amount` decimal(12,2) NOT NULL DEFAULT '0.00' COMMENT 'D - Vendor Invoice Basic/Taxable Amount',
  `tds_tax_id` bigint(20) DEFAULT NULL,
  `tds_rate` decimal(5,2) NOT NULL DEFAULT '0.00',
  `tds_amount` decimal(12,2) DEFAULT '0.00',
