/*!50001 CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `deployment_detail` AS select `a`.`deploymentid` AS `deploymentid`,`a`.`orderid` AS `orderid`,`a`.`recordid` AS `recordid`,`a`.`name` AS `name`,`a`.`mobilenumber` AS `mobilenumber`,`a`.`email` AS `email`,`a`.`deployment_date` AS `deployment_date`,`a`.`deployed_date` AS `deployed_date`,`a`.`deployment_status` AS `deployment_status`,`a`.`is_verified` AS `is_verified`,`a`.`verified_by` AS `verified_by`,`a`.`verified_on` AS `verified_on`,`b`.`remuneration` AS `remuneration`,`b`.`operating` AS `operating`,`b`.`tax` AS `tax`,`b`.`admin` AS `admin` from (`eoi_resource_deployment` `a` join `eoi_request_detail` `b` on((`b`.`recordid` = `a`.`recordid`))) */;

